SELECT '@@TARGET ' || current_database() || ' ' || current_setting('server_version') || ' ' || CASE WHEN pg_is_in_recovery() THEN 'standby' ELSE 'primary' END AS t \gset qq_
\echo :qq_t

-- ======== PG-BAK-001  P1  No WAL archiving: point-in-time recovery impossible ========
SELECT (NOT pg_is_in_recovery()) AS gate_pg_bak_001 \gset
\if :gate_pg_bak_001
\echo '@@CHECK PG-BAK-001'
-- check: PG-BAK-001
-- title: No WAL archiving: point-in-time recovery impossible
-- priority: 1
-- scope: setting
-- cost: 0
-- run_on: primary
SELECT 'PG-BAK-001'::text  AS check_id,
       'setting'::text     AS scope,
       'archive_mode'::text AS object,
       format('archive_mode = off (set in %s%s) on a primary. Without archived WAL there is no point-in-time recovery: the only recoverable states are whatever full backups exist, and every transaction since the newest one is unrecoverable. wal_level = %s, cluster size %s, WAL generated since the last checkpoint statistics reset is visible in PG-INFO-008. A pg_dump is a logical export, not PITR.',
              s.source, coalesce(', ' || s.sourcefile || ':' || s.sourceline::text, ''),
              current_setting('wal_level'),
              pg_size_pretty((SELECT sum(pg_database_size(oid)) FROM pg_database))) AS details,
       json_build_object('archive_mode', s.setting, 'source', s.source,
                         'wal_level', current_setting('wal_level'),
                         'archive_command', current_setting('archive_command'),
                         'cluster_bytes', (SELECT sum(pg_database_size(oid)) FROM pg_database))::text AS evidence_json,
       'medium'::text AS confidence
FROM pg_settings s
WHERE s.name = 'archive_mode' AND s.setting = 'off'
  AND NOT pg_is_in_recovery();
\echo '@@END PG-BAK-001'
\else
\echo '@@SKIP PG-BAK-001 primary only'
\endif

-- ======== PG-BAK-002  P1  archive_command is failing ========
SELECT (current_setting('server_version_num')::int >= 90400 AND NOT pg_is_in_recovery()) AS gate_pg_bak_002 \gset
\if :gate_pg_bak_002
\echo '@@CHECK PG-BAK-002'
-- check: PG-BAK-002
-- title: archive_command is failing
-- priority: 1
-- scope: cluster
-- cost: 0
-- min_version: 9.4
-- run_on: primary
SELECT 'PG-BAK-002'::text AS check_id,
       'cluster'::text    AS scope,
       NULL::text         AS object,
       format('pg_stat_archiver reports %s failures; the last failure was at %s (%s ago) on WAL file %s, and the last success was %s. Failing archiving means WAL segments cannot be recycled: pg_wal grows until the volume fills, at which point the server PANICs. Statistics reset %s.',
              to_char(a.failed_count, 'FM999,999,999,999'),
              a.last_failed_time,
              justify_interval(date_trunc('second', now() - a.last_failed_time)),
              coalesce(a.last_failed_wal, 'unknown'),
              coalesce(a.last_archived_time::text || ' (' || justify_interval(date_trunc('second', now() - a.last_archived_time))::text || ' ago, ' || coalesce(a.last_archived_wal, '?') || ')', 'never'),
              coalesce(a.stats_reset::text, 'unknown')) AS details,
       json_build_object('failed_count', a.failed_count, 'archived_count', a.archived_count,
                         'last_failed_time', a.last_failed_time, 'last_failed_wal', a.last_failed_wal,
                         'last_archived_time', a.last_archived_time, 'last_archived_wal', a.last_archived_wal,
                         'stats_reset', a.stats_reset,
                         'archive_command', current_setting('archive_command'),
                         'seconds_since_last_success',
                            CASE WHEN a.last_archived_time IS NULL THEN NULL
                                 ELSE round(extract(epoch FROM now() - a.last_archived_time))::bigint END)::text AS evidence_json,
       'high'::text AS confidence
FROM pg_stat_archiver a
WHERE a.failed_count > 0
  AND a.last_failed_time > coalesce(a.last_archived_time, '-infinity'::timestamptz);
\echo '@@END PG-BAK-002'
\else
\echo '@@SKIP PG-BAK-002 needs PostgreSQL 9.4 or newer; primary only'
\endif

-- ======== PG-BAK-003  P1  WAL archiving stalled ========
SELECT (current_setting('server_version_num')::int >= 120000 AND NOT pg_is_in_recovery()) AS gate_pg_bak_003 \gset
\if :gate_pg_bak_003
\echo '@@CHECK PG-BAK-003'
-- check: PG-BAK-003
-- title: WAL archiving stalled
-- priority: 1
-- scope: cluster
-- cost: 1
-- min_version: 12
-- run_on: primary
-- thresholds: ready_files, stall_seconds, segments_behind
WITH ready AS (
  SELECT count(*) FILTER (WHERE name LIKE '%.ready') AS ready_files
  FROM pg_ls_archive_statusdir()
),
arch AS (SELECT * FROM pg_stat_archiver)
SELECT 'PG-BAK-003'::text AS check_id,
       'cluster'::text    AS scope,
       NULL::text         AS object,
       format('%s WAL segments are queued for archiving in pg_wal/archive_status (threshold %s). Last archived %s at %s (%s ago); current WAL position is %s. archive_timeout = %s, archive_command = %s. The queue drains only as fast as the archive command succeeds; while it grows, pg_wal grows with it.',
              to_char(r.ready_files, 'FM999,999,999'),
              :'pg_bak_003_ready_files'::text,
              coalesce(a.last_archived_wal, 'nothing'),
              coalesce(a.last_archived_time::text, 'never'),
              coalesce(justify_interval(date_trunc('second', now() - a.last_archived_time))::text, 'n/a'),
              pg_walfile_name(pg_current_wal_lsn()),
              current_setting('archive_timeout'),
              coalesce(nullif(current_setting('archive_command'), ''), '(empty)')) AS details,
       json_build_object('ready_files', r.ready_files, 'threshold_ready_files', :'pg_bak_003_ready_files'::int,
                         'last_archived_wal', a.last_archived_wal, 'last_archived_time', a.last_archived_time,
                         'current_wal_file', pg_walfile_name(pg_current_wal_lsn()),
                         'failed_count', a.failed_count, 'archived_count', a.archived_count,
                         'archive_timeout', current_setting('archive_timeout'))::text AS evidence_json,
       'high'::text AS confidence
FROM ready r CROSS JOIN arch a
WHERE current_setting('archive_mode') <> 'off'
  AND NOT pg_is_in_recovery()
  AND (r.ready_files >= :'pg_bak_003_ready_files'::int
       OR (a.last_archived_time IS NOT NULL
           AND now() - a.last_archived_time > greatest(
                 (:'pg_bak_003_stall_seconds'::int || ' seconds')::interval,
                 3 * (SELECT setting::int FROM pg_settings WHERE name = 'archive_timeout') * interval '1 second')
           AND (SELECT setting::int FROM pg_settings WHERE name = 'archive_timeout') > 0));
\echo '@@END PG-BAK-003'
\else
\echo '@@SKIP PG-BAK-003 needs PostgreSQL 12 or newer; primary only'
\endif

-- ======== PG-BAK-004  P1  archive_command is a no-op (WAL archived to nowhere) ========
SELECT (NOT pg_is_in_recovery()) AS gate_pg_bak_004 \gset
\if :gate_pg_bak_004
\echo '@@CHECK PG-BAK-004'
-- check: PG-BAK-004
-- title: archive_command is a no-op (WAL archived to nowhere)
-- priority: 1
-- scope: setting
-- cost: 0
-- run_on: primary
SELECT 'PG-BAK-004'::text     AS check_id,
       'setting'::text        AS scope,
       'archive_command'::text AS object,
       format('archive_mode = %s but archive_command is %s, which succeeds without storing anything. pg_stat_archiver reports %s segments "archived" and %s failures, so the counters look healthy while no WAL is being kept. Point-in-time recovery is impossible and nothing in the server will say so.',
              current_setting('archive_mode'),
              quote_literal(s.setting),
              to_char((SELECT archived_count FROM pg_stat_archiver), 'FM999,999,999,999'),
              to_char((SELECT failed_count FROM pg_stat_archiver), 'FM999,999,999,999')) AS details,
       json_build_object('archive_command', s.setting, 'archive_mode', current_setting('archive_mode'),
                         'source', s.source,
                         'archived_count', (SELECT archived_count FROM pg_stat_archiver),
                         'failed_count', (SELECT failed_count FROM pg_stat_archiver))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_settings s
WHERE s.name = 'archive_command'
  AND current_setting('archive_mode') <> 'off'
  AND NOT pg_is_in_recovery()
  AND (s.setting ~ '^\s*(/bin/|/usr/bin/)?(true|:)\s*$'
    OR s.setting ~ '^\s*exit\s+0\s*$'
    OR s.setting ~ '^\s*cd\s+\.\s*$'
    OR s.setting ~ '^\s*#'
    OR s.setting ~ '>\s*/dev/null\s*$');
\echo '@@END PG-BAK-004'
\else
\echo '@@SKIP PG-BAK-004 primary only'
\endif

-- ======== PG-CORR-001  P1  Data checksum failures reported ========
SELECT (current_setting('server_version_num')::int >= 120000) AS gate_pg_corr_001 \gset
\if :gate_pg_corr_001
\echo '@@CHECK PG-CORR-001'
-- check: PG-CORR-001
-- title: Data checksum failures reported
-- priority: 1
-- scope: database
-- cost: 0
-- min_version: 12
SELECT 'PG-CORR-001'::text AS check_id,
       'database'::text    AS scope,
       coalesce(d.datname, 'shared objects')::text AS object,
       format('pg_stat_database reports %s checksum failures for %s; the most recent was at %s (%s ago). The server read a page whose checksum did not match its contents. Counters are since the statistics reset at %s. This is a report from the storage layer, not an inference.',
              to_char(d.checksum_failures, 'FM999,999,999,999'),
              coalesce('database ' || d.datname, 'shared catalogs'),
              d.checksum_last_failure,
              justify_interval(date_trunc('second', now() - d.checksum_last_failure)),
              coalesce(d.stats_reset::text, 'unknown')) AS details,
       json_build_object('checksum_failures', d.checksum_failures,
                         'checksum_last_failure', d.checksum_last_failure,
                         'datname', d.datname, 'stats_reset', d.stats_reset,
                         'data_checksums', current_setting('data_checksums'),
                         'ignore_checksum_failure', current_setting('ignore_checksum_failure'))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_stat_database d
WHERE d.checksum_failures > 0
ORDER BY d.checksum_failures DESC;
\echo '@@END PG-CORR-001'
\else
\echo '@@SKIP PG-CORR-001 needs PostgreSQL 12 or newer'
\endif

-- ======== PG-CORR-002  P1  zero_damaged_pages enabled ========
\echo '@@CHECK PG-CORR-002'
-- check: PG-CORR-002
-- title: zero_damaged_pages enabled
-- priority: 1
-- scope: setting
-- cost: 0
SELECT 'PG-CORR-002'::text        AS check_id,
       'setting'::text            AS scope,
       'zero_damaged_pages'::text AS object,
       format('zero_damaged_pages = on (set in %s%s). A page whose header fails validation is replaced with zeros and the read continues, so every row on that page disappears and the server reports only a WARNING. This is a recovery tool for a supervised salvage operation; leaving it on in normal running converts detectable corruption into silent data loss. data_checksums = %s.',
              s.source, coalesce(', ' || s.sourcefile || ':' || s.sourceline::text, ''),
              current_setting('data_checksums')) AS details,
       json_build_object('zero_damaged_pages', s.setting, 'source', s.source,
                         'sourcefile', s.sourcefile, 'sourceline', s.sourceline,
                         'data_checksums', current_setting('data_checksums'))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_settings s
WHERE s.name = 'zero_damaged_pages' AND s.setting = 'on';
\echo '@@END PG-CORR-002'

-- ======== PG-CORR-003  P1  ignore_checksum_failure enabled ========
\echo '@@CHECK PG-CORR-003'
-- check: PG-CORR-003
-- title: ignore_checksum_failure enabled
-- priority: 1
-- scope: setting
-- cost: 0
SELECT 'PG-CORR-003'::text            AS check_id,
       'setting'::text                AS scope,
       'ignore_checksum_failure'::text AS object,
       format('ignore_checksum_failure = on (set in %s%s). A page whose checksum does not match is used anyway after a WARNING, so corrupt data flows into query results, into indexes built from it, and into every backup and replica taken afterwards. data_checksums = %s; checksum failures reported so far: %s.',
              s.source, coalesce(', ' || s.sourcefile || ':' || s.sourceline::text, ''),
              current_setting('data_checksums'),
              coalesce((SELECT sum(checksum_failures)::text FROM pg_stat_database), 'not tracked on this version')) AS details,
       json_build_object('ignore_checksum_failure', s.setting, 'source', s.source,
                         'data_checksums', current_setting('data_checksums'))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_settings s
WHERE s.name = 'ignore_checksum_failure' AND s.setting = 'on';
\echo '@@END PG-CORR-003'

-- ======== PG-DUR-001  P1  fsync disabled ========
\echo '@@CHECK PG-DUR-001'
-- check: PG-DUR-001
-- title: fsync disabled
-- priority: 1
-- scope: setting
-- cost: 0
SELECT 'PG-DUR-001'::text AS check_id,
       'setting'::text    AS scope,
       'fsync'::text      AS object,
       format('fsync = off (set in %s%s). The server never asks the operating system to flush WAL or data pages to durable storage, so an operating-system crash or power loss can leave the cluster in a state recovery cannot repair: this is cluster loss, not the loss of recent transactions. full_page_writes = %s, synchronous_commit = %s, data_checksums = %s. Cluster holds %s.',
              s.source, coalesce(', ' || s.sourcefile || ':' || s.sourceline::text, ''),
              current_setting('full_page_writes'), current_setting('synchronous_commit'),
              current_setting('data_checksums'),
              pg_size_pretty((SELECT sum(pg_database_size(oid)) FROM pg_database))) AS details,
       json_build_object('fsync', s.setting, 'source', s.source,
                         'sourcefile', s.sourcefile, 'sourceline', s.sourceline,
                         'full_page_writes', current_setting('full_page_writes'),
                         'synchronous_commit', current_setting('synchronous_commit'),
                         'cluster_bytes', (SELECT sum(pg_database_size(oid)) FROM pg_database))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_settings s
WHERE s.name = 'fsync' AND s.setting = 'off';
\echo '@@END PG-DUR-001'

-- ======== PG-DUR-002  P1  full_page_writes disabled ========
\echo '@@CHECK PG-DUR-002'
-- check: PG-DUR-002
-- title: full_page_writes disabled
-- priority: 1
-- scope: setting
-- cost: 0
SELECT 'PG-DUR-002'::text          AS check_id,
       'setting'::text             AS scope,
       'full_page_writes'::text    AS object,
       format('full_page_writes = off (set in %s%s). After a checkpoint, the first write to each page is no longer logged in full, so a page torn by a crash mid-write cannot be reconstructed from WAL. This is only safe where the filesystem guarantees atomic %s-byte writes, which ZFS does and ext4, xfs and most cloud block devices do not. Confirm the filesystem before treating this as intentional. fsync = %s, data_checksums = %s, wal_log_hints = %s.',
              s.source, coalesce(', ' || s.sourcefile || ':' || s.sourceline::text, ''),
              current_setting('block_size'),
              current_setting('fsync'), current_setting('data_checksums'),
              current_setting('wal_log_hints')) AS details,
       json_build_object('full_page_writes', s.setting, 'source', s.source,
                         'block_size', current_setting('block_size')::int,
                         'fsync', current_setting('fsync'),
                         'data_checksums', current_setting('data_checksums'),
                         'wal_log_hints', current_setting('wal_log_hints'))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_settings s
WHERE s.name = 'full_page_writes' AND s.setting = 'off';
\echo '@@END PG-DUR-002'

-- ======== PG-REPL-001  P1  Synchronous replication configured but no synchronous standby connected ========
SELECT (current_setting('server_version_num')::int >= 90600 AND NOT pg_is_in_recovery()) AS gate_pg_repl_001 \gset
\if :gate_pg_repl_001
\echo '@@CHECK PG-REPL-001'
-- check: PG-REPL-001
-- title: Synchronous replication configured but no synchronous standby connected
-- priority: 1
-- scope: cluster
-- cost: 0
-- min_version: 9.6
-- run_on: primary
SELECT 'PG-REPL-001'::text AS check_id,
       'cluster'::text     AS scope,
       'synchronous_standby_names'::text AS object,
       format('synchronous_standby_names = %s and synchronous_commit = %s, but no connected standby is in sync_state sync or quorum. Every COMMIT that needs a synchronous confirmation is waiting and will keep waiting until a matching standby connects. Connected standbys: %s. Sessions currently in state active: %s.',
              quote_literal(current_setting('synchronous_standby_names')),
              current_setting('synchronous_commit'),
              coalesce((SELECT string_agg(format('%s (%s, %s)', coalesce(nullif(application_name, ''), 'unnamed'),
                                                 coalesce(host(client_addr), 'local'), sync_state), '; ')
                        FROM pg_stat_replication), 'none'),
              (SELECT count(*) FROM pg_stat_activity WHERE state = 'active' AND backend_type = 'client backend')) AS details,
       json_build_object('synchronous_standby_names', current_setting('synchronous_standby_names'),
                         'synchronous_commit', current_setting('synchronous_commit'),
                         'connected_standbys', (SELECT count(*) FROM pg_stat_replication),
                         'sync_standbys', (SELECT count(*) FROM pg_stat_replication WHERE sync_state IN ('sync', 'quorum')),
                         'active_sessions', (SELECT count(*) FROM pg_stat_activity
                                             WHERE state = 'active' AND backend_type = 'client backend'))::text AS evidence_json,
       'high'::text AS confidence
WHERE NOT pg_is_in_recovery()
  AND coalesce(nullif(trim(current_setting('synchronous_standby_names')), ''), '') <> ''
  AND current_setting('synchronous_commit') NOT IN ('off', 'local')
  AND NOT EXISTS (SELECT 1 FROM pg_stat_replication WHERE sync_state IN ('sync', 'quorum'))
  -- Neon: the named synchronous standby is walproposer, the compute's own WAL
  -- service proposer. It takes a walsender slot with application_name
  -- 'walproposer' expressly so that synchronous_standby_names can name it, then
  -- ships WAL to a Paxos quorum of safekeepers and releases the commit when the
  -- quorum acknowledges. That acknowledgement is not reported as sync_state
  -- 'sync' or 'quorum', so the test above reads a hang that is not happening:
  -- durability on Neon is the safekeepers' and the commit path is healthy.
  -- Guarded by the neon_superuser fingerprint so that the same name on a stock
  -- cluster -- where it would be a real misconfiguration -- still fires.
  -- See reference/platforms.md and reference/checks-postgres.md#pg-repl-001.
  AND NOT (EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'neon_superuser')
           AND (btrim(lower(trim(current_setting('synchronous_standby_names'))), '"''') = 'walproposer'
                OR EXISTS (SELECT 1 FROM pg_stat_replication
                           WHERE application_name = 'walproposer')));
\echo '@@END PG-REPL-001'
\else
\echo '@@SKIP PG-REPL-001 needs PostgreSQL 9.6 or newer; primary only'
\endif

-- ======== PG-REPL-002  P1  Inactive replication slot retaining more than 10 GB of WAL ========
SELECT (current_setting('server_version_num')::int >= 90400) AS gate_pg_repl_002 \gset
\if :gate_pg_repl_002
\echo '@@CHECK PG-REPL-002'
-- check: PG-REPL-002
-- title: Inactive replication slot retaining more than 10 GB of WAL
-- priority: 1
-- scope: slot
-- cost: 0
-- min_version: 9.4
-- thresholds: retained_bytes
\set ON_ERROR_STOP off
SELECT (current_setting('server_version_num')::int >= 130000) AS pg_repl_002_has_wal_status \gset
SELECT (current_setting('server_version_num')::int >= 170000) AS pg_repl_002_has_inactive_since \gset
WITH cur AS (
  SELECT CASE WHEN pg_is_in_recovery() THEN pg_last_wal_receive_lsn() ELSE pg_current_wal_lsn() END AS lsn
),
slots AS (
  SELECT s.slot_name, s.slot_type, s.plugin, s.database, s.active, s.active_pid,
         s.restart_lsn, s.xmin, s.catalog_xmin,
         CASE WHEN s.restart_lsn IS NULL THEN NULL
              ELSE pg_wal_lsn_diff(cur.lsn, s.restart_lsn)::bigint END AS retained_bytes,
\if :pg_repl_002_has_wal_status
         s.wal_status,
\else
         NULL::text AS wal_status,
\endif
\if :pg_repl_002_has_inactive_since
         s.inactive_since,
\else
         NULL::timestamptz AS inactive_since,
\endif
         cur.lsn AS current_lsn
  FROM pg_replication_slots s CROSS JOIN cur
)
SELECT 'PG-REPL-002'::text AS check_id,
       'slot'::text   AS scope,
       s.slot_name::text AS object,
       format('Replication slot %s (%s%s) is inactive and is holding back %s of WAL (threshold %s). restart_lsn %s against current %s.%s%s Until the slot is consumed or dropped, the WAL it pins cannot be recycled or archived away, and pg_wal grows without limit unless max_slot_wal_keep_size is set (currently %s).',
              s.slot_name, s.slot_type,
              coalesce(', plugin ' || s.plugin, ''),
              coalesce(pg_size_pretty(s.retained_bytes), 'an unknown amount'),
              pg_size_pretty(:'pg_repl_002_retained_bytes'::bigint),
              coalesce(s.restart_lsn::text, 'none'), s.current_lsn::text,
              coalesce(' wal_status = ' || s.wal_status || '.', ''),
              coalesce(' Inactive since ' || s.inactive_since::text || ' (' || justify_interval(date_trunc('second', now() - s.inactive_since))::text || ').', ''),
              current_setting('max_slot_wal_keep_size')) AS details,
       json_build_object('slot_name', s.slot_name, 'slot_type', s.slot_type, 'plugin', s.plugin,
                         'database', s.database, 'active', s.active,
                         'retained_bytes', s.retained_bytes,
                         'threshold_bytes', :'pg_repl_002_retained_bytes'::bigint,
                         'restart_lsn', s.restart_lsn::text, 'current_lsn', s.current_lsn::text,
                         'wal_status', s.wal_status, 'inactive_since', s.inactive_since,
                         'xmin_age', CASE WHEN s.xmin IS NULL THEN NULL ELSE age(s.xmin) END,
                         'catalog_xmin_age', CASE WHEN s.catalog_xmin IS NULL THEN NULL ELSE age(s.catalog_xmin) END,
                         'max_slot_wal_keep_size', current_setting('max_slot_wal_keep_size'))::text AS evidence_json,
       'high'::text AS confidence
FROM slots s
WHERE NOT s.active
  AND (coalesce(s.retained_bytes, 0) >= :'pg_repl_002_retained_bytes'::bigint
       OR s.wal_status = 'unreserved')
ORDER BY s.retained_bytes DESC NULLS LAST;
\echo '@@END PG-REPL-002'
\else
\echo '@@SKIP PG-REPL-002 needs PostgreSQL 9.4 or newer'
\endif

-- ======== PG-SEC-001  P1  trust authentication reachable over the network ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_sec_001 \gset
\if :gate_pg_sec_001
\echo '@@CHECK PG-SEC-001'
-- check: PG-SEC-001
-- title: trust authentication reachable over the network
-- priority: 1
-- scope: cluster
-- cost: 0
-- min_version: 10
-- requires: superuser
SELECT 'PG-SEC-001'::text AS check_id,
       'cluster'::text    AS scope,
       format('pg_hba.conf:%s', r.line_number)::text AS object,
       format('pg_hba.conf line %s: %s %s %s %s trust. Anyone who can open a TCP connection to port %s becomes any role they ask for, with no password and no certificate. Databases matched: %s. Roles matched: %s. listen_addresses = %s, ssl = %s.',
              r.line_number, r.type, array_to_string(r.database, ','), array_to_string(r.user_name, ','),
              coalesce(r.address || coalesce('/' || r.netmask, ''), 'all addresses'),
              current_setting('port'),
              array_to_string(r.database, ','), array_to_string(r.user_name, ','),
              current_setting('listen_addresses'), current_setting('ssl')) AS details,
       json_build_object('line_number', r.line_number, 'type', r.type,
                         'database', array_to_string(r.database, ';'),
                         'user_name', array_to_string(r.user_name, ';'),
                         'address', r.address, 'netmask', r.netmask,
                         'auth_method', r.auth_method,
                         'listen_addresses', current_setting('listen_addresses'),
                         'port', current_setting('port'), 'ssl', current_setting('ssl'))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_hba_file_rules r
WHERE r.error IS NULL
  AND r.auth_method = 'trust'
  AND r.type IN ('host', 'hostssl', 'hostnossl', 'hostgssenc', 'hostnogssenc')
  AND coalesce(r.address, '') NOT IN ('127.0.0.1', '::1', 'localhost', 'samehost')
ORDER BY r.line_number;
\echo '@@END PG-SEC-001'
\else
\echo '@@SKIP PG-SEC-001 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-WRAP-001  P1  Transaction ID or MultiXact wraparound imminent ========
\echo '@@CHECK PG-WRAP-001'
-- check: PG-WRAP-001
-- title: Transaction ID or MultiXact wraparound imminent
-- priority: 1
-- scope: database
-- cost: 0
-- thresholds: xid_age
SELECT 'PG-WRAP-001'::text AS check_id,
       'database'::text    AS scope,
       d.datname::text     AS object,
       format('age(datfrozenxid) = %s, mxid_age(datminmxid) = %s; worst is %s%% of the 2,147,483,648 XID limit (threshold %s). autovacuum_freeze_max_age = %s. Database size %s. When the oldest unfrozen XID reaches the limit the cluster stops accepting write transactions.',
              to_char(age(d.datfrozenxid), 'FM999,999,999,999'),
              to_char(mxid_age(d.datminmxid), 'FM999,999,999,999'),
              round(100.0 * greatest(age(d.datfrozenxid), mxid_age(d.datminmxid)) / 2147483648.0, 1)::text,
              to_char(:'pg_wrap_001_xid_age'::bigint, 'FM999,999,999,999'),
              current_setting('autovacuum_freeze_max_age'),
              pg_size_pretty(pg_database_size(d.oid))) AS details,
       json_build_object(
              'xid_age', age(d.datfrozenxid),
              'mxid_age', mxid_age(d.datminmxid),
              'worst_age', greatest(age(d.datfrozenxid), mxid_age(d.datminmxid)),
              'threshold', :'pg_wrap_001_xid_age'::bigint,
              'xid_limit', 2147483648::bigint,
              'pct_of_limit', round(100.0 * greatest(age(d.datfrozenxid), mxid_age(d.datminmxid)) / 2147483648.0, 2),
              'freeze_max_age', current_setting('autovacuum_freeze_max_age')::bigint,
              'datallowconn', d.datallowconn,
              'database_bytes', pg_database_size(d.oid))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_database d
WHERE greatest(age(d.datfrozenxid), mxid_age(d.datminmxid)) >= :'pg_wrap_001_xid_age'::bigint
ORDER BY greatest(age(d.datfrozenxid), mxid_age(d.datminmxid)) DESC;
\echo '@@END PG-WRAP-001'

-- ======== PG-BAK-005  P5  Archiving enabled but no archive_command or archive_library set ========
SELECT (NOT pg_is_in_recovery()) AS gate_pg_bak_005 \gset
\if :gate_pg_bak_005
\echo '@@CHECK PG-BAK-005'
-- check: PG-BAK-005
-- title: Archiving enabled but no archive_command or archive_library set
-- priority: 5
-- scope: setting
-- cost: 0
-- run_on: primary
SELECT 'PG-BAK-005'::text     AS check_id,
       'setting'::text        AS scope,
       'archive_command'::text AS object,
       format('archive_mode = %s but neither archive_command nor archive_library is set. Every completed WAL segment is retained in pg_wal waiting for an archiver that will never succeed, and the server log fills with warnings. pg_wal already holds %s segments awaiting archiving.',
              current_setting('archive_mode'),
              coalesce((SELECT count(*)::text FROM pg_ls_archive_statusdir() WHERE name LIKE '%.ready'), 'an unknown number of')) AS details,
       json_build_object('archive_mode', current_setting('archive_mode'),
                         'archive_command', current_setting('archive_command'),
                         'archive_library', coalesce((SELECT setting FROM pg_settings WHERE name = 'archive_library'), ''))::text AS evidence_json,
       'high'::text AS confidence
WHERE current_setting('archive_mode') <> 'off'
  AND NOT pg_is_in_recovery()
  AND coalesce(nullif(trim(current_setting('archive_command')), ''), '') = ''
  AND coalesce(nullif(trim(coalesce((SELECT setting FROM pg_settings WHERE name = 'archive_library'), '')), ''), '') = '';
\echo '@@END PG-BAK-005'
\else
\echo '@@SKIP PG-BAK-005 primary only'
\endif

-- ======== PG-CONN-001  P5  Connections at 90 percent or more of max_connections ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_conn_001 \gset
\if :gate_pg_conn_001
\echo '@@CHECK PG-CONN-001'
-- check: PG-CONN-001
-- title: Connections at 90 percent or more of max_connections
-- priority: 5
-- scope: cluster
-- cost: 0
-- min_version: 10
-- thresholds: conn_fraction
WITH lim AS (
  SELECT (SELECT setting::int FROM pg_settings WHERE name = 'max_connections')                  AS max_conn,
         (SELECT setting::int FROM pg_settings WHERE name = 'superuser_reserved_connections')   AS su_reserved,
         coalesce((SELECT setting::int FROM pg_settings WHERE name = 'reserved_connections'), 0) AS reserved
),
cur AS (
  SELECT count(*) FILTER (WHERE backend_type = 'client backend')                    AS clients,
         count(*) FILTER (WHERE backend_type = 'client backend' AND state = 'idle') AS idle,
         count(*) FILTER (WHERE backend_type = 'client backend' AND state = 'active') AS active,
         count(*) FILTER (WHERE backend_type = 'client backend' AND state LIKE 'idle in transaction%') AS idle_in_txn
  FROM pg_stat_activity
)
SELECT 'PG-CONN-001'::text AS check_id,
       'cluster'::text  AS scope,
       'max_connections'::text AS object,
       format('%s client backends against a usable ceiling of %s (max_connections %s less %s superuser-reserved and %s reserved): %s%% (threshold %s%%). Of those, %s are active, %s idle and %s idle in transaction. The next connection past the ceiling is refused with "FATAL: sorry, too many clients already", which the application sees as an outage rather than as slowness.',
              c.clients, l.max_conn - l.su_reserved - l.reserved, l.max_conn, l.su_reserved, l.reserved,
              round(100.0 * c.clients / nullif(l.max_conn - l.su_reserved - l.reserved, 0), 1)::text,
              round(100 * :'pg_conn_001_conn_fraction'::numeric)::text,
              c.active, c.idle, c.idle_in_txn) AS details,
       json_build_object('client_backends', c.clients, 'max_connections', l.max_conn,
                         'superuser_reserved_connections', l.su_reserved, 'reserved_connections', l.reserved,
                         'usable_ceiling', l.max_conn - l.su_reserved - l.reserved,
                         'fraction_used', round(c.clients::numeric / nullif(l.max_conn - l.su_reserved - l.reserved, 0), 4),
                         'threshold_fraction', :'pg_conn_001_conn_fraction'::numeric,
                         'active', c.active, 'idle', c.idle, 'idle_in_transaction', c.idle_in_txn)::text AS evidence_json,
       'high'::text AS confidence
FROM cur c CROSS JOIN lim l
WHERE c.clients >= :'pg_conn_001_conn_fraction'::numeric * (l.max_conn - l.su_reserved - l.reserved)
;
\echo '@@END PG-CONN-001'
\else
\echo '@@SKIP PG-CONN-001 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-LOCK-006  P5  Orphaned prepared transactions ========
\echo '@@CHECK PG-LOCK-006'
-- check: PG-LOCK-006
-- title: Orphaned prepared transactions
-- priority: 5
-- scope: cluster
-- cost: 0
-- thresholds: prepared_seconds
SELECT 'PG-LOCK-006'::text AS check_id,
       'cluster'::text     AS scope,
       p.gid::text         AS object,
       format('Prepared transaction "%s" in database %s, owned by %s, has been prepared since %s (%s, threshold %s). Its xmin is %s XIDs old. A prepared transaction holds its locks and its xmin horizon until it is committed or rolled back: it survives server restarts, it does not appear in pg_stat_activity, and nothing will ever time it out. If no external transaction manager is going to resolve it, the fix is ROLLBACK PREPARED %s (or COMMIT PREPARED, if that is genuinely the intent) - which is a write, so it is yours to run, not db-triage''s. max_prepared_transactions = %s.',
              p.gid, p.database, p.owner, p.prepared,
              justify_interval(date_trunc('second', now() - p.prepared)),
              (:'pg_lock_006_prepared_seconds'::int || ' seconds')::interval,
              to_char(age(p.transaction), 'FM999,999,999,999'),
              quote_literal(p.gid),
              current_setting('max_prepared_transactions')) AS details,
       json_build_object('gid', p.gid, 'database', p.database, 'owner', p.owner,
                         'prepared', p.prepared,
                         'open_seconds', round(extract(epoch FROM now() - p.prepared))::bigint,
                         'threshold_seconds', :'pg_lock_006_prepared_seconds'::int,
                         'xid_age', age(p.transaction),
                         'max_prepared_transactions', current_setting('max_prepared_transactions')::int)::text AS evidence_json,
       'high'::text AS confidence
FROM pg_prepared_xacts p
WHERE now() - p.prepared >= (:'pg_lock_006_prepared_seconds'::int || ' seconds')::interval
ORDER BY p.prepared;
\echo '@@END PG-LOCK-006'

-- ======== PG-REPL-003  P5  Inactive replication slot retaining more than 1 GB of WAL ========
SELECT (current_setting('server_version_num')::int >= 90400) AS gate_pg_repl_003 \gset
\if :gate_pg_repl_003
\echo '@@CHECK PG-REPL-003'
-- check: PG-REPL-003
-- title: Inactive replication slot retaining more than 1 GB of WAL
-- priority: 5
-- scope: slot
-- cost: 0
-- min_version: 9.4
-- thresholds: retained_bytes, retained_bytes_high
\set ON_ERROR_STOP off
SELECT (current_setting('server_version_num')::int >= 130000) AS pg_repl_003_has_wal_status \gset
SELECT (current_setting('server_version_num')::int >= 170000) AS pg_repl_003_has_inactive_since \gset
WITH cur AS (
  SELECT CASE WHEN pg_is_in_recovery() THEN pg_last_wal_receive_lsn() ELSE pg_current_wal_lsn() END AS lsn
),
slots AS (
  SELECT s.slot_name, s.slot_type, s.plugin, s.database, s.active, s.active_pid,
         s.restart_lsn, s.xmin, s.catalog_xmin,
         CASE WHEN s.restart_lsn IS NULL THEN NULL
              ELSE pg_wal_lsn_diff(cur.lsn, s.restart_lsn)::bigint END AS retained_bytes,
\if :pg_repl_003_has_wal_status
         s.wal_status,
\else
         NULL::text AS wal_status,
\endif
\if :pg_repl_003_has_inactive_since
         s.inactive_since,
\else
         NULL::timestamptz AS inactive_since,
\endif
         cur.lsn AS current_lsn
  FROM pg_replication_slots s CROSS JOIN cur
)
SELECT 'PG-REPL-003'::text AS check_id,
       'slot'::text   AS scope,
       s.slot_name::text AS object,
       format('Replication slot %s (%s%s) is inactive and is holding back %s of WAL (threshold %s). restart_lsn %s against current %s.%s%s Until the slot is consumed or dropped, the WAL it pins cannot be recycled or archived away, and pg_wal grows without limit unless max_slot_wal_keep_size is set (currently %s).',
              s.slot_name, s.slot_type,
              coalesce(', plugin ' || s.plugin, ''),
              coalesce(pg_size_pretty(s.retained_bytes), 'an unknown amount'),
              pg_size_pretty(:'pg_repl_003_retained_bytes'::bigint),
              coalesce(s.restart_lsn::text, 'none'), s.current_lsn::text,
              coalesce(' wal_status = ' || s.wal_status || '.', ''),
              coalesce(' Inactive since ' || s.inactive_since::text || ' (' || justify_interval(date_trunc('second', now() - s.inactive_since))::text || ').', ''),
              current_setting('max_slot_wal_keep_size')) AS details,
       json_build_object('slot_name', s.slot_name, 'slot_type', s.slot_type, 'plugin', s.plugin,
                         'database', s.database, 'active', s.active,
                         'retained_bytes', s.retained_bytes,
                         'threshold_bytes', :'pg_repl_003_retained_bytes'::bigint,
                         'restart_lsn', s.restart_lsn::text, 'current_lsn', s.current_lsn::text,
                         'wal_status', s.wal_status, 'inactive_since', s.inactive_since,
                         'xmin_age', CASE WHEN s.xmin IS NULL THEN NULL ELSE age(s.xmin) END,
                         'catalog_xmin_age', CASE WHEN s.catalog_xmin IS NULL THEN NULL ELSE age(s.catalog_xmin) END,
                         'max_slot_wal_keep_size', current_setting('max_slot_wal_keep_size'))::text AS evidence_json,
       'high'::text AS confidence
FROM slots s
WHERE NOT s.active
  AND coalesce(s.retained_bytes, 0) >= :'pg_repl_003_retained_bytes'::bigint
  AND coalesce(s.retained_bytes, 0) <  :'pg_repl_003_retained_bytes_high'::bigint
  AND coalesce(s.wal_status, 'reserved') <> 'unreserved'
ORDER BY s.retained_bytes DESC NULLS LAST;
\echo '@@END PG-REPL-003'
\else
\echo '@@SKIP PG-REPL-003 needs PostgreSQL 9.4 or newer'
\endif

-- ======== PG-REPL-006  P5  Streaming replica lagging badly ========
SELECT (current_setting('server_version_num')::int >= 100000 AND NOT pg_is_in_recovery()) AS gate_pg_repl_006 \gset
\if :gate_pg_repl_006
\echo '@@CHECK PG-REPL-006'
-- check: PG-REPL-006
-- title: Streaming replica lagging badly
-- priority: 5
-- scope: replica
-- cost: 0
-- min_version: 10
-- run_on: primary
-- thresholds: lag_bytes, lag_seconds
SELECT 'PG-REPL-006'::text AS check_id,
       'replica'::text  AS scope,
       coalesce(nullif(r.application_name, ''), 'pid:' || r.pid::text)::text AS object,
       format('Standby %s at %s is %s behind on replay and %s behind in time (thresholds %s / %s). state = %s, sync_state = %s. sent %s, write %s, flush %s, replay %s. write_lag %s, flush_lag %s, replay_lag %s. A failover to this standby now would lose everything after its replay position, and promoting it would first have to apply the backlog.',
              coalesce(nullif(r.application_name, ''), 'unnamed'),
              coalesce(host(r.client_addr), 'local socket'),
              pg_size_pretty(greatest(pg_wal_lsn_diff(r.sent_lsn, r.replay_lsn), 0)::bigint),
              coalesce(justify_interval(r.replay_lag)::text, 'an unknown interval'),
              pg_size_pretty(:'pg_repl_006_lag_bytes'::bigint),
              (:'pg_repl_006_lag_seconds'::int || ' seconds')::interval::text,
              r.state, r.sync_state,
              r.sent_lsn::text, r.write_lsn::text, r.flush_lsn::text, r.replay_lsn::text,
              coalesce(r.write_lag::text, 'null'), coalesce(r.flush_lag::text, 'null'),
              coalesce(r.replay_lag::text, 'null')) AS details,
       json_build_object('application_name', r.application_name, 'client_addr', host(r.client_addr),
                         'state', r.state, 'sync_state', r.sync_state, 'pid', r.pid,
                         'lag_bytes', greatest(pg_wal_lsn_diff(r.sent_lsn, r.replay_lsn), 0)::bigint,
                         'replay_lag_seconds', round(extract(epoch FROM r.replay_lag))::bigint,
                         'write_lag_seconds', round(extract(epoch FROM r.write_lag))::bigint,
                         'flush_lag_seconds', round(extract(epoch FROM r.flush_lag))::bigint,
                         'threshold_bytes', :'pg_repl_006_lag_bytes'::bigint,
                         'threshold_seconds', :'pg_repl_006_lag_seconds'::int,
                         'sent_lsn', r.sent_lsn::text, 'replay_lsn', r.replay_lsn::text,
                         'backend_start', r.backend_start)::text AS evidence_json,
       'high'::text AS confidence
FROM pg_stat_replication r
WHERE (greatest(pg_wal_lsn_diff(r.sent_lsn, r.replay_lsn), 0) >= :'pg_repl_006_lag_bytes'::bigint
       OR r.replay_lag >= (:'pg_repl_006_lag_seconds'::int || ' seconds')::interval)
ORDER BY pg_wal_lsn_diff(r.sent_lsn, r.replay_lsn) DESC NULLS LAST;
\echo '@@END PG-REPL-006'
\else
\echo '@@SKIP PG-REPL-006 needs PostgreSQL 10 or newer; primary only'
\endif

-- ======== PG-REPL-008  P5  Standby not streaming ========
SELECT (current_setting('server_version_num')::int >= 90600 AND pg_is_in_recovery()) AS gate_pg_repl_008 \gset
\if :gate_pg_repl_008
\echo '@@CHECK PG-REPL-008'
-- check: PG-REPL-008
-- title: Standby not streaming
-- priority: 5
-- scope: cluster
-- cost: 0
-- min_version: 9.6
-- run_on: standby
-- thresholds: replay_gap_bytes
WITH w AS (SELECT * FROM pg_stat_wal_receiver),
     p AS (SELECT pg_last_wal_receive_lsn() AS recv, pg_last_wal_replay_lsn() AS replay,
                  pg_last_xact_replay_timestamp() AS last_xact)
SELECT 'PG-REPL-008'::text AS check_id,
       'cluster'::text     AS scope,
       NULL::text          AS object,
       format('This standby is not keeping up with its source. WAL receiver: %s. restore_command: %s. Last received LSN %s, last replayed LSN %s, gap %s (threshold %s). Last replayed transaction committed at %s%s. Until this is fixed the standby is stale as a failover target and stale as a read replica.',
              CASE WHEN w.pid IS NULL THEN 'not running'
                   ELSE format('pid %s, status %s, source %s, last message %s',
                               w.pid, w.status, coalesce(w.sender_host, '?'),
                               coalesce(w.last_msg_receipt_time::text, 'never')) END,
              coalesce(nullif(current_setting('restore_command'), ''), '(empty)'),
              coalesce(p.recv::text, 'none'), coalesce(p.replay::text, 'none'),
              coalesce(pg_size_pretty(greatest(pg_wal_lsn_diff(p.recv, p.replay), 0)::bigint), 'unknown'),
              pg_size_pretty(:'pg_repl_008_replay_gap_bytes'::bigint),
              coalesce(p.last_xact::text, 'unknown'),
              coalesce(' (' || justify_interval(date_trunc('second', now() - p.last_xact))::text || ' ago)', '')) AS details,
       json_build_object('receiver_pid', w.pid, 'receiver_status', w.status,
                         'sender_host', w.sender_host, 'last_msg_receipt_time', w.last_msg_receipt_time,
                         'restore_command', current_setting('restore_command'),
                         'last_wal_receive_lsn', p.recv::text, 'last_wal_replay_lsn', p.replay::text,
                         'replay_gap_bytes', greatest(pg_wal_lsn_diff(p.recv, p.replay), 0)::bigint,
                         'threshold_bytes', :'pg_repl_008_replay_gap_bytes'::bigint,
                         'last_xact_replay_timestamp', p.last_xact)::text AS evidence_json,
       'high'::text AS confidence
FROM p LEFT JOIN w ON true
WHERE pg_is_in_recovery()
  AND ((w.pid IS NULL OR w.status IS DISTINCT FROM 'streaming')
        AND coalesce(nullif(trim(current_setting('restore_command')), ''), '') = ''
       OR greatest(pg_wal_lsn_diff(p.recv, p.replay), 0) >= :'pg_repl_008_replay_gap_bytes'::bigint);
\echo '@@END PG-REPL-008'
\else
\echo '@@SKIP PG-REPL-008 needs PostgreSQL 9.6 or newer; standby only'
\endif

-- ======== PG-SEC-002  P5  Cleartext password authentication over the network ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_sec_002 \gset
\if :gate_pg_sec_002
\echo '@@CHECK PG-SEC-002'
-- check: PG-SEC-002
-- title: Cleartext password authentication over the network
-- priority: 5
-- scope: cluster
-- cost: 0
-- min_version: 10
-- requires: superuser
SELECT 'PG-SEC-002'::text AS check_id,
       'cluster'::text    AS scope,
       format('pg_hba.conf:%s', r.line_number)::text AS object,
       format('pg_hba.conf line %s: %s %s %s %s password. The "password" method sends the password across the connection in clear text. On a hostnossl rule, or on a host rule where the client does not negotiate TLS, anyone on the path reads it. ssl = %s. Change the method to scram-sha-256 (password_encryption is currently %s) and require hostssl.',
              r.line_number, r.type, array_to_string(r.database, ','), array_to_string(r.user_name, ','),
              coalesce(r.address || coalesce('/' || r.netmask, ''), 'all addresses'),
              current_setting('ssl'), current_setting('password_encryption')) AS details,
       json_build_object('line_number', r.line_number, 'type', r.type,
                         'database', array_to_string(r.database, ';'),
                         'user_name', array_to_string(r.user_name, ';'),
                         'address', r.address, 'auth_method', r.auth_method,
                         'ssl', current_setting('ssl'),
                         'password_encryption', current_setting('password_encryption'))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_hba_file_rules r
WHERE r.error IS NULL
  AND r.auth_method = 'password'
  AND r.type IN ('host', 'hostnossl', 'hostnogssenc')
ORDER BY r.line_number;
\echo '@@END PG-SEC-002'
\else
\echo '@@SKIP PG-SEC-002 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-WRAP-005  P5  Autovacuum disabled ========
\echo '@@CHECK PG-WRAP-005'
-- check: PG-WRAP-005
-- title: Autovacuum disabled
-- priority: 5
-- scope: setting
-- cost: 0
SELECT 'PG-WRAP-005'::text AS check_id,
       'setting'::text     AS scope,
       'autovacuum'::text  AS object,
       format('autovacuum = off (set in %s%s). Dead tuples are never reclaimed and planner statistics are never refreshed. The emergency anti-wraparound vacuum still runs, which is the only reason this is not P1; the highest XID age in this cluster is currently %s.',
              s.source,
              coalesce(', ' || s.sourcefile || ':' || s.sourceline::text, ''),
              to_char((SELECT max(age(datfrozenxid)) FROM pg_database), 'FM999,999,999,999')) AS details,
       json_build_object(
              'autovacuum', s.setting,
              'source', s.source,
              'sourcefile', s.sourcefile,
              'max_datfrozenxid_age', (SELECT max(age(datfrozenxid)) FROM pg_database),
              'track_counts', current_setting('track_counts'))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_settings s
WHERE s.name = 'autovacuum' AND s.setting = 'off';
\echo '@@END PG-WRAP-005'

-- ======== PG-WRAP-006  P5  Statistics tracking disabled (autovacuum blind) ========
\echo '@@CHECK PG-WRAP-006'
-- check: PG-WRAP-006
-- title: Statistics tracking disabled (autovacuum blind)
-- priority: 5
-- scope: setting
-- cost: 0
SELECT 'PG-WRAP-006'::text  AS check_id,
       'setting'::text      AS scope,
       'track_counts'::text AS object,
       format('track_counts = off (set in %s%s) while autovacuum = %s. Without row-level counters autovacuum cannot see dead tuples or modified rows, so only the anti-wraparound path will ever vacuum, and ANALYZE will never run automatically. Highest XID age in this cluster is %s.',
              s.source,
              coalesce(', ' || s.sourcefile || ':' || s.sourceline::text, ''),
              current_setting('autovacuum'),
              to_char((SELECT max(age(datfrozenxid)) FROM pg_database), 'FM999,999,999,999')) AS details,
       json_build_object(
              'track_counts', s.setting,
              'source', s.source,
              'autovacuum', current_setting('autovacuum'),
              'max_datfrozenxid_age', (SELECT max(age(datfrozenxid)) FROM pg_database))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_settings s
WHERE s.name = 'track_counts' AND s.setting = 'off';
\echo '@@END PG-WRAP-006'

-- ======== PG-DUR-003  P10  synchronous_commit off cluster-wide ========
\echo '@@CHECK PG-DUR-003'
-- check: PG-DUR-003
-- title: synchronous_commit off cluster-wide
-- priority: 10
-- scope: setting
-- cost: 0
SELECT 'PG-DUR-003'::text            AS check_id,
       'setting'::text               AS scope,
       'synchronous_commit'::text    AS object,
       format('synchronous_commit = off at server level (set in %s%s). COMMIT returns before the WAL record is flushed, so a crash of the server process or the host loses every transaction committed in roughly the last %s ms (three times wal_writer_delay). No transaction is torn and the cluster stays consistent; the loss is bounded and silent. %s per-database or per-role override(s) exist (see PG-CFG-002). This is often deliberate on a queue or cache database and always worth stating explicitly.',
              s.source, coalesce(', ' || s.sourcefile || ':' || s.sourceline::text, ''),
              3 * (SELECT setting::int FROM pg_settings WHERE name = 'wal_writer_delay'),
              (SELECT count(*) FROM pg_db_role_setting r
               WHERE array_to_string(r.setconfig, ' ') LIKE '%synchronous_commit%')) AS details,
       json_build_object('synchronous_commit', s.setting, 'source', s.source,
                         'wal_writer_delay_ms', (SELECT setting::int FROM pg_settings WHERE name = 'wal_writer_delay'),
                         'bounded_loss_ms', 3 * (SELECT setting::int FROM pg_settings WHERE name = 'wal_writer_delay'),
                         'db_role_overrides', (SELECT count(*) FROM pg_db_role_setting r
                                               WHERE array_to_string(r.setconfig, ' ') LIKE '%synchronous_commit%'))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_settings s
WHERE s.name = 'synchronous_commit' AND s.setting = 'off';
\echo '@@END PG-DUR-003'

-- ======== PG-LOCK-001  P10  Blocking chain: session blocked more than 5 minutes ========
SELECT (current_setting('server_version_num')::int >= 90600) AS gate_pg_lock_001 \gset
\if :gate_pg_lock_001
\echo '@@CHECK PG-LOCK-001'
-- check: PG-LOCK-001
-- title: Blocking chain: session blocked more than 5 minutes
-- priority: 10
-- scope: session
-- cost: 0
-- min_version: 9.6
-- thresholds: blocked_seconds
SELECT 'PG-LOCK-001'::text AS check_id,
       'session'::text  AS scope,
       ('pid:' || a.pid)::text AS object,
       format('pid %s (%s / %s, from %s) has been blocked for %s (threshold %s) waiting on %s. It is blocked by pid(s) %s. Root blocker pid %s: state %s, transaction open since %s (%s), application %s, query: %s. Blocked query: %s',
              a.pid, coalesce(nullif(a.usename, ''), '?'),
              coalesce(nullif(a.application_name, ''), 'no application_name'),
              coalesce(host(a.client_addr), 'local socket'),
              justify_interval(date_trunc('second', now() - a.state_change)),
              (:'pg_lock_001_blocked_seconds'::int || ' seconds')::interval,
              coalesce(a.wait_event_type || '/' || a.wait_event, 'a lock'),
              array_to_string(pg_blocking_pids(a.pid), ', '),
              b.pid, coalesce(b.state, '?'),
              coalesce(b.xact_start::text, 'no transaction'),
              coalesce(justify_interval(date_trunc('second', now() - b.xact_start))::text, 'n/a'),
              coalesce(nullif(b.application_name, ''), 'no application_name'),
              left(regexp_replace(coalesce(b.query, ''), '\s+', ' ', 'g'), 200),
              left(regexp_replace(coalesce(a.query, ''), '\s+', ' ', 'g'), 200)) AS details,
       json_build_object('blocked_pid', a.pid, 'blocked_seconds', round(extract(epoch FROM now() - a.state_change))::bigint,
                         'threshold_seconds', :'pg_lock_001_blocked_seconds'::int,
                         'blocking_pids', pg_blocking_pids(a.pid),
                         'root_blocker_pid', b.pid, 'root_blocker_state', b.state,
                         'root_blocker_xact_seconds', round(extract(epoch FROM now() - b.xact_start))::bigint,
                         'root_blocker_application', b.application_name,
                         'wait_event_type', a.wait_event_type, 'wait_event', a.wait_event,
                         'blocked_usename', a.usename, 'blocked_database', a.datname,
                         'sampled_at', now())::text AS evidence_json,
       'high'::text AS confidence
FROM pg_stat_activity a
LEFT JOIN LATERAL (
  SELECT * FROM pg_stat_activity x
  WHERE x.pid = (pg_blocking_pids(a.pid))[1]
) b ON true
WHERE cardinality(pg_blocking_pids(a.pid)) > 0
  AND a.state_change IS NOT NULL
  AND now() - a.state_change >= (:'pg_lock_001_blocked_seconds'::int || ' seconds')::interval
ORDER BY a.state_change;
\echo '@@END PG-LOCK-001'
\else
\echo '@@SKIP PG-LOCK-001 needs PostgreSQL 9.6 or newer'
\endif

-- ======== PG-LOCK-003  P10  Idle in transaction for more than 1 hour ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_lock_003 \gset
\if :gate_pg_lock_003
\echo '@@CHECK PG-LOCK-003'
-- check: PG-LOCK-003
-- title: Idle in transaction for more than 1 hour
-- priority: 10
-- scope: session
-- cost: 0
-- min_version: 10
-- thresholds: idle_seconds
SELECT 'PG-LOCK-003'::text AS check_id,
       'session'::text  AS scope,
       ('pid:' || a.pid)::text AS object,
       format('pid %s (%s / %s, from %s, database %s) has been in state "%s" for %s (threshold %s). Its transaction opened at %s and has been open for %s. It holds every lock the transaction has taken and pins the xmin horizon at age %s, so vacuum cannot remove any row version newer than that anywhere in the cluster (PG-VAC-005), and any DDL that needs a lock on the same objects queues behind it. Last statement: %s',
              a.pid, coalesce(nullif(a.usename, ''), '?'),
              coalesce(nullif(a.application_name, ''), 'no application_name'),
              coalesce(host(a.client_addr), 'local socket'), coalesce(a.datname, '?'),
              a.state, justify_interval(date_trunc('second', now() - a.state_change)),
              (:'pg_lock_003_idle_seconds'::int || ' seconds')::interval,
              coalesce(a.xact_start::text, 'unknown'),
              coalesce(justify_interval(date_trunc('second', now() - a.xact_start))::text, 'unknown'),
              coalesce(age(a.backend_xmin)::text, 'none held'),
              left(regexp_replace(coalesce(a.query, ''), '\s+', ' ', 'g'), 200)) AS details,
       json_build_object('pid', a.pid, 'state', a.state, 'usename', a.usename,
                         'application_name', a.application_name, 'datname', a.datname,
                         'client_addr', host(a.client_addr),
                         'idle_seconds', round(extract(epoch FROM now() - a.state_change))::bigint,
                         'threshold_seconds', :'pg_lock_003_idle_seconds'::int,
                         'xact_seconds', round(extract(epoch FROM now() - a.xact_start))::bigint,
                         'backend_xmin_age', CASE WHEN a.backend_xmin IS NULL THEN NULL ELSE age(a.backend_xmin) END,
                         'sampled_at', now())::text AS evidence_json,
       'high'::text AS confidence
FROM pg_stat_activity a
WHERE a.state LIKE 'idle in transaction%'
  AND a.state_change IS NOT NULL
  AND now() - a.state_change >= (:'pg_lock_003_idle_seconds'::int || ' seconds')::interval
ORDER BY a.state_change;
\echo '@@END PG-LOCK-003'
\else
\echo '@@SKIP PG-LOCK-003 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-REL-005  P10  Server restarted within the last 24 hours ========
\echo '@@CHECK PG-REL-005'
-- check: PG-REL-005
-- title: Server restarted within the last 24 hours
-- priority: 10
-- scope: cluster
-- cost: 0
-- thresholds: uptime_seconds
SELECT 'PG-REL-005'::text AS check_id,
       'cluster'::text    AS scope,
       NULL::text         AS object,
       format('The postmaster started at %s, %s ago (threshold %s). Two consequences for this report: every counter-based finding covers only that window, so rates are unreliable and "0 scans since reset" means nothing yet - those findings are marked confidence low. And the restart itself is worth explaining: a planned restart for a configuration change looks identical from here to a crash and automatic recovery (PG-REL-011 reads the log for that, in the deep pass) or to an OOM kill. %s setting(s) are currently marked pending_restart, which would mean the restart has not yet applied everything someone intended.',
              pg_postmaster_start_time(),
              justify_interval(date_trunc('second', now() - pg_postmaster_start_time())),
              (:'pg_rel_005_uptime_seconds'::int || ' seconds')::interval,
              (SELECT count(*) FROM pg_settings WHERE pending_restart)) AS details,
       json_build_object('postmaster_start_time', pg_postmaster_start_time(),
                         'uptime_seconds', round(extract(epoch FROM now() - pg_postmaster_start_time()))::bigint,
                         'threshold_seconds', :'pg_rel_005_uptime_seconds'::int,
                         'pending_restart_settings', (SELECT count(*) FROM pg_settings WHERE pending_restart),
                         'earliest_stats_reset', (SELECT min(stats_reset) FROM pg_stat_database),
                         'in_recovery', pg_is_in_recovery())::text AS evidence_json,
       'high'::text AS confidence
WHERE now() - pg_postmaster_start_time() < (:'pg_rel_005_uptime_seconds'::int || ' seconds')::interval;
\echo '@@END PG-REL-005'

-- ======== PG-REPL-005  P10  Replication slot invalidated or lost ========
SELECT (current_setting('server_version_num')::int >= 130000) AS gate_pg_repl_005 \gset
\if :gate_pg_repl_005
\echo '@@CHECK PG-REPL-005'
-- check: PG-REPL-005
-- title: Replication slot invalidated or lost
-- priority: 10
-- scope: slot
-- cost: 0
-- min_version: 13
\set ON_ERROR_STOP off
SELECT (current_setting('server_version_num')::int >= 160000) AS pg_repl_005_has_conflicting \gset
SELECT (current_setting('server_version_num')::int >= 170000) AS pg_repl_005_has_reason \gset
WITH slots AS (
  SELECT s.slot_name, s.slot_type, s.plugin, s.database, s.active, s.wal_status, s.restart_lsn,
\if :pg_repl_005_has_conflicting
         s.conflicting,
\else
         NULL::boolean AS conflicting,
\endif
\if :pg_repl_005_has_reason
         s.invalidation_reason
\else
         NULL::text AS invalidation_reason
\endif
  FROM pg_replication_slots s
)
SELECT 'PG-REPL-005'::text AS check_id,
       'slot'::text        AS scope,
       s.slot_name::text   AS object,
       format('Replication slot %s (%s%s) is no longer usable: wal_status = %s%s%s. The WAL it needed has already been removed, so the consumer cannot resume from where it stopped and must be re-initialised from a fresh snapshot. The slot still exists, so topology diagrams and monitoring that only check "does the slot exist" will report it as healthy. active = %s.',
              s.slot_name, s.slot_type, coalesce(', plugin ' || s.plugin, ''),
              coalesce(s.wal_status, 'unknown'),
              coalesce(', invalidation_reason = ' || s.invalidation_reason, ''),
              CASE WHEN s.conflicting THEN ', conflicting with recovery' ELSE '' END,
              s.active) AS details,
       json_build_object('slot_name', s.slot_name, 'slot_type', s.slot_type, 'plugin', s.plugin,
                         'database', s.database, 'active', s.active, 'wal_status', s.wal_status,
                         'conflicting', s.conflicting, 'invalidation_reason', s.invalidation_reason,
                         'restart_lsn', s.restart_lsn::text)::text AS evidence_json,
       'high'::text AS confidence
FROM slots s
WHERE s.wal_status = 'lost' OR s.conflicting IS TRUE OR s.invalidation_reason IS NOT NULL;
\echo '@@END PG-REPL-005'
\else
\echo '@@SKIP PG-REPL-005 needs PostgreSQL 13 or newer'
\endif

-- ======== PG-REPL-012  P10  Logical subscription disabled or erroring ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_repl_012 \gset
\if :gate_pg_repl_012
\echo '@@CHECK PG-REPL-012'
-- check: PG-REPL-012
-- title: Logical subscription disabled or erroring
-- priority: 10
-- scope: cluster
-- cost: 0
-- min_version: 10
\set ON_ERROR_STOP off
SELECT (current_setting('server_version_num')::int >= 150000) AS pg_repl_012_has_sub_stats \gset
\if :pg_repl_012_has_sub_stats
SELECT 'PG-REPL-012'::text AS check_id,
       'cluster'::text     AS scope,
       s.subname::text     AS object,
       format('Logical subscription %s: enabled = %s, %s apply worker(s) running, %s apply error(s) and %s table-sync error(s) since %s. Publications: %s. While a subscription is stopped or erroring, the subscriber diverges from the publisher and the publisher''s replication slot keeps retaining WAL for it (see PG-REPL-002/003).',
              s.subname, s.subenabled,
              (SELECT count(*) FROM pg_stat_subscription ss WHERE ss.subid = s.oid AND ss.pid IS NOT NULL),
              st.apply_error_count, st.sync_error_count,
              coalesce(st.stats_reset::text, 'the subscription was created'),
              coalesce(array_to_string(s.subpublications, ', '), 'none')) AS details,
       json_build_object('subname', s.subname, 'subenabled', s.subenabled,
                         'workers', (SELECT count(*) FROM pg_stat_subscription ss WHERE ss.subid = s.oid AND ss.pid IS NOT NULL),
                         'apply_error_count', st.apply_error_count,
                         'sync_error_count', st.sync_error_count,
                         'stats_reset', st.stats_reset,
                         'publications', array_to_string(s.subpublications, ';'),
                         'subslotname', s.subslotname)::text AS evidence_json,
       'high'::text AS confidence
FROM pg_subscription s
LEFT JOIN pg_stat_subscription_stats st ON st.subid = s.oid
WHERE s.subdbid = (SELECT oid FROM pg_database WHERE datname = current_database())
  AND (NOT s.subenabled
       OR coalesce(st.apply_error_count, 0) > 0
       OR coalesce(st.sync_error_count, 0) > 0
       OR NOT EXISTS (SELECT 1 FROM pg_stat_subscription ss WHERE ss.subid = s.oid AND ss.pid IS NOT NULL));
\else
SELECT 'PG-REPL-012'::text AS check_id,
       'cluster'::text     AS scope,
       s.subname::text     AS object,
       format('Logical subscription %s: enabled = %s, %s apply worker(s) running. Publications: %s. This server predates pg_stat_subscription_stats (PostgreSQL 15), so apply and table-sync error counts are not available; check the server log for "logical replication apply worker" errors. While a subscription is stopped, the subscriber diverges from the publisher and the publisher''s slot keeps retaining WAL.',
              s.subname, s.subenabled,
              (SELECT count(*) FROM pg_stat_subscription ss WHERE ss.subid = s.oid AND ss.pid IS NOT NULL),
              coalesce(array_to_string(s.subpublications, ', '), 'none')) AS details,
       json_build_object('subname', s.subname, 'subenabled', s.subenabled,
                         'workers', (SELECT count(*) FROM pg_stat_subscription ss WHERE ss.subid = s.oid AND ss.pid IS NOT NULL),
                         'publications', array_to_string(s.subpublications, ';'),
                         'error_counts_available', false)::text AS evidence_json,
       'medium'::text AS confidence
FROM pg_subscription s
WHERE s.subdbid = (SELECT oid FROM pg_database WHERE datname = current_database())
  AND (NOT s.subenabled
       OR NOT EXISTS (SELECT 1 FROM pg_stat_subscription ss WHERE ss.subid = s.oid AND ss.pid IS NOT NULL));
\endif
\echo '@@END PG-REPL-012'
\else
\echo '@@SKIP PG-REPL-012 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-WRAP-002  P10  Transaction ID or MultiXact age high ========
\echo '@@CHECK PG-WRAP-002'
-- check: PG-WRAP-002
-- title: Transaction ID or MultiXact age high
-- priority: 10
-- scope: database
-- cost: 0
-- thresholds: xid_age, xid_age_critical
SELECT 'PG-WRAP-002'::text AS check_id,
       'database'::text    AS scope,
       d.datname::text     AS object,
       format('age(datfrozenxid) = %s, mxid_age(datminmxid) = %s; worst is %s%% of the 2,147,483,648 XID limit (threshold %s, escalates to PG-WRAP-001 at %s). autovacuum_freeze_max_age = %s, so the anti-wraparound vacuum has been due for %s XIDs.',
              to_char(age(d.datfrozenxid), 'FM999,999,999,999'),
              to_char(mxid_age(d.datminmxid), 'FM999,999,999,999'),
              round(100.0 * greatest(age(d.datfrozenxid), mxid_age(d.datminmxid)) / 2147483648.0, 1)::text,
              to_char(:'pg_wrap_002_xid_age'::bigint, 'FM999,999,999,999'),
              to_char(:'pg_wrap_002_xid_age_critical'::bigint, 'FM999,999,999,999'),
              current_setting('autovacuum_freeze_max_age'),
              to_char(greatest(age(d.datfrozenxid), 0) - current_setting('autovacuum_freeze_max_age')::bigint, 'FM999,999,999,999')) AS details,
       json_build_object(
              'xid_age', age(d.datfrozenxid),
              'mxid_age', mxid_age(d.datminmxid),
              'worst_age', greatest(age(d.datfrozenxid), mxid_age(d.datminmxid)),
              'threshold', :'pg_wrap_002_xid_age'::bigint,
              'escalation_threshold', :'pg_wrap_002_xid_age_critical'::bigint,
              'freeze_max_age', current_setting('autovacuum_freeze_max_age')::bigint,
              'database_bytes', pg_database_size(d.oid))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_database d
WHERE greatest(age(d.datfrozenxid), mxid_age(d.datminmxid)) >= :'pg_wrap_002_xid_age'::bigint
  AND greatest(age(d.datfrozenxid), mxid_age(d.datminmxid)) <  :'pg_wrap_002_xid_age_critical'::bigint
ORDER BY greatest(age(d.datfrozenxid), mxid_age(d.datminmxid)) DESC;
\echo '@@END PG-WRAP-002'

-- ======== PG-BAK-006  P20  wal_level = minimal ========
\echo '@@CHECK PG-BAK-006'
-- check: PG-BAK-006
-- title: wal_level = minimal
-- priority: 20
-- scope: setting
-- cost: 0
SELECT 'PG-BAK-006'::text  AS check_id,
       'setting'::text     AS scope,
       'wal_level'::text   AS object,
       format('wal_level = minimal (set in %s%s). Minimal WAL omits the information a standby or an archive recovery needs, so this cluster cannot stream replication, cannot take an online base backup, and cannot do point-in-time recovery. Raising it to replica requires a restart. max_wal_senders = %s, archive_mode = %s.',
              s.source, coalesce(', ' || s.sourcefile || ':' || s.sourceline::text, ''),
              current_setting('max_wal_senders'), current_setting('archive_mode')) AS details,
       json_build_object('wal_level', s.setting, 'source', s.source,
                         'max_wal_senders', current_setting('max_wal_senders')::int,
                         'archive_mode', current_setting('archive_mode'))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_settings s
WHERE s.name = 'wal_level' AND s.setting = 'minimal';
\echo '@@END PG-BAK-006'

-- ======== PG-CORR-006  P20  Collation version mismatch (index corruption risk) ========
SELECT (current_setting('server_version_num')::int >= 130000) AS gate_pg_corr_006 \gset
\if :gate_pg_corr_006
\echo '@@CHECK PG-CORR-006'
-- check: PG-CORR-006
-- title: Collation version mismatch (index corruption risk)
-- priority: 20
-- scope: database
-- cost: 0
-- min_version: 13
\set ON_ERROR_STOP off
SELECT (current_setting('server_version_num')::int >= 150000) AS pg_corr_006_has_db_collversion \gset
\if :pg_corr_006_has_db_collversion
SELECT 'PG-CORR-006'::text AS check_id,
       'database'::text    AS scope,
       d.datname::text     AS object,
       format('Database %s was created against collation version %s of %s, but the operating system now provides version %s. A collation upgrade changes sort order, so B-tree indexes on text columns built before the change may no longer be in the order the planner assumes: equality and range lookups can silently miss rows. Rebuild the affected text indexes with REINDEX, then run ALTER DATABASE %s REFRESH COLLATION VERSION.',
              d.datname, coalesce(d.datcollversion, 'unknown'), d.datcollate,
              coalesce(pg_database_collation_actual_version(d.oid), 'unknown'),
              quote_ident(d.datname)) AS details,
       json_build_object('object_kind', 'database', 'datname', d.datname,
                         'recorded_version', d.datcollversion,
                         'actual_version', pg_database_collation_actual_version(d.oid),
                         'datcollate', d.datcollate, 'datctype', d.datctype)::text AS evidence_json,
       'high'::text AS confidence
FROM pg_database d
WHERE d.datcollversion IS NOT NULL
  AND pg_database_collation_actual_version(d.oid) IS NOT NULL
  AND d.datcollversion IS DISTINCT FROM pg_database_collation_actual_version(d.oid);
\endif

SELECT 'PG-CORR-006'::text AS check_id,
       'database'::text    AS scope,
       format('%I.collation:%s', current_database(), c.collname)::text AS object,
       format('Collation %s (provider %s) records version %s but the operating system now provides version %s. Every text index using this collation was built under the old sort order. %s index(es) in this database reference it. Rebuild them with REINDEX, then ALTER COLLATION %s REFRESH VERSION.',
              c.collname,
              CASE c.collprovider WHEN 'c' THEN 'libc' WHEN 'i' THEN 'icu' WHEN 'b' THEN 'builtin' ELSE c.collprovider::text END,
              coalesce(c.collversion, 'unknown'),
              coalesce(pg_collation_actual_version(c.oid), 'unknown'),
              (SELECT count(*) FROM pg_index i WHERE c.oid = ANY (i.indcollation::oid[])),
              quote_ident(c.collname)) AS details,
       json_build_object('object_kind', 'collation', 'collname', c.collname,
                         'collprovider', c.collprovider::text,
                         'recorded_version', c.collversion,
                         'actual_version', pg_collation_actual_version(c.oid),
                         'dependent_indexes', (SELECT count(*) FROM pg_index i WHERE c.oid = ANY (i.indcollation::oid[])))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_collation c
WHERE c.collversion IS NOT NULL
  AND pg_collation_actual_version(c.oid) IS NOT NULL
  AND c.collversion IS DISTINCT FROM pg_collation_actual_version(c.oid);
\echo '@@END PG-CORR-006'
\else
\echo '@@SKIP PG-CORR-006 needs PostgreSQL 13 or newer'
\endif

-- ======== PG-LOCK-005  P20  Client transaction open for more than 1 hour ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_lock_005 \gset
\if :gate_pg_lock_005
\echo '@@CHECK PG-LOCK-005'
-- check: PG-LOCK-005
-- title: Client transaction open for more than 1 hour
-- priority: 20
-- scope: session
-- cost: 0
-- min_version: 10
-- thresholds: xact_seconds
SELECT 'PG-LOCK-005'::text AS check_id,
       'session'::text     AS scope,
       ('pid:' || a.pid)::text AS object,
       format('pid %s (%s / %s, from %s, database %s) has had a transaction open for %s (threshold %s), currently in state "%s". Its xmin is %s XIDs old, which is the floor below which vacuum cannot clean anywhere in the cluster (see PG-VAC-005). Maintenance statements (VACUUM, CREATE INDEX, REINDEX, CLUSTER, COPY) and base backups are excluded from this check, so this is application work. Current statement: %s',
              a.pid, coalesce(nullif(a.usename, ''), '?'),
              coalesce(nullif(a.application_name, ''), 'no application_name'),
              coalesce(host(a.client_addr), 'local socket'), coalesce(a.datname, '?'),
              justify_interval(date_trunc('second', now() - a.xact_start)),
              (:'pg_lock_005_xact_seconds'::int || ' seconds')::interval,
              coalesce(a.state, '?'),
              coalesce(age(a.backend_xmin)::text, 'not set'),
              left(regexp_replace(coalesce(a.query, ''), '\s+', ' ', 'g'), 200)) AS details,
       json_build_object('pid', a.pid, 'state', a.state, 'usename', a.usename,
                         'application_name', a.application_name, 'datname', a.datname,
                         'xact_seconds', round(extract(epoch FROM now() - a.xact_start))::bigint,
                         'threshold_seconds', :'pg_lock_005_xact_seconds'::int,
                         'backend_xmin_age', CASE WHEN a.backend_xmin IS NULL THEN NULL ELSE age(a.backend_xmin) END,
                         'sampled_at', now())::text AS evidence_json,
       'high'::text AS confidence
FROM pg_stat_activity a
WHERE a.backend_type = 'client backend'
  AND a.xact_start IS NOT NULL
  AND now() - a.xact_start >= (:'pg_lock_005_xact_seconds'::int || ' seconds')::interval
  AND coalesce(a.query, '') !~* '^\s*(VACUUM|ANALYZE|CREATE\s+(UNIQUE\s+)?INDEX|REINDEX|CLUSTER|COPY|ALTER\s+TABLE\s+\S+\s+SET\s+STATISTICS)'
  AND coalesce(a.application_name, '') !~* '(basebackup|pg_dump|pg_restore|walreceiver|db-triage)'
ORDER BY a.xact_start;
\echo '@@END PG-LOCK-005'
\else
\echo '@@SKIP PG-LOCK-005 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-MEM-001  P20  shared_buffers at the shipped default ========
\echo '@@CHECK PG-MEM-001'
-- check: PG-MEM-001
-- title: shared_buffers at the shipped default
-- priority: 20
-- scope: setting
-- cost: 0
-- thresholds: shared_buffers_bytes
SELECT 'PG-MEM-001'::text       AS check_id,
       'setting'::text          AS scope,
       'shared_buffers'::text   AS object,
       format('shared_buffers = %s (threshold %s), source %s. The shipped default is chosen so the server starts on any machine, not so it performs on this one. This cluster holds %s of data, so at %s the buffer cache can hold %s%% of it and almost every read goes to the operating-system cache or the disk. effective_cache_size = %s. Changing shared_buffers requires a restart.',
              pg_size_pretty(s.bytes::bigint), pg_size_pretty(:'pg_mem_001_shared_buffers_bytes'::bigint), s.source,
              pg_size_pretty((SELECT sum(pg_database_size(oid)) FROM pg_database)),
              pg_size_pretty(s.bytes::bigint),
              round(100.0 * s.bytes / nullif((SELECT sum(pg_database_size(oid)) FROM pg_database), 0), 1)::text,
              current_setting('effective_cache_size')) AS details,
       json_build_object('shared_buffers_bytes', s.bytes::bigint,
                         'threshold_bytes', :'pg_mem_001_shared_buffers_bytes'::bigint,
                         'source', s.source,
                         'cluster_bytes', (SELECT sum(pg_database_size(oid)) FROM pg_database),
                         'effective_cache_size', current_setting('effective_cache_size'))::text AS evidence_json,
       'high'::text AS confidence
FROM (SELECT setting::numeric * 8192 AS bytes, source FROM pg_settings WHERE name = 'shared_buffers') s
WHERE s.bytes <= :'pg_mem_001_shared_buffers_bytes'::bigint;
\echo '@@END PG-MEM-001'

-- ======== PG-WRAP-007  P20  autovacuum_freeze_max_age raised to 1 billion or more ========
\echo '@@CHECK PG-WRAP-007'
-- check: PG-WRAP-007
-- title: autovacuum_freeze_max_age raised to 1 billion or more
-- priority: 20
-- scope: setting
-- cost: 0
-- thresholds: freeze_max_age
SELECT 'PG-WRAP-007'::text AS check_id,
       'setting'::text     AS scope,
       s.name::text        AS object,
       format('%s = %s (default %s, threshold %s), set in %s. The forced anti-wraparound vacuum now starts %s XIDs later, which leaves %s XIDs of headroom before the 2,147,483,648 limit instead of the %s the default gives. On a large table the emergency freeze can take longer than that headroom allows.',
              s.name, to_char(s.setting::bigint, 'FM999,999,999,999'),
              to_char(s.boot_val::bigint, 'FM999,999,999,999'),
              to_char(:'pg_wrap_007_freeze_max_age'::bigint, 'FM999,999,999,999'),
              s.source,
              to_char(s.setting::bigint - s.boot_val::bigint, 'FM999,999,999,999'),
              to_char(2147483648::bigint - s.setting::bigint, 'FM999,999,999,999'),
              to_char(2147483648::bigint - s.boot_val::bigint, 'FM999,999,999,999')) AS details,
       json_build_object(
              'setting', s.name, 'value', s.setting::bigint, 'default', s.boot_val::bigint,
              'source', s.source, 'threshold', :'pg_wrap_007_freeze_max_age'::bigint,
              'headroom_xids', 2147483648::bigint - s.setting::bigint)::text AS evidence_json,
       'high'::text AS confidence
FROM pg_settings s
WHERE s.name IN ('autovacuum_freeze_max_age', 'autovacuum_multixact_freeze_max_age')
  AND s.setting::bigint >= :'pg_wrap_007_freeze_max_age'::bigint;
\echo '@@END PG-WRAP-007'

-- ======== PG-BAK-007  P50  archive_timeout unset on a low-write primary ========
SELECT (NOT pg_is_in_recovery()) AS gate_pg_bak_007 \gset
\if :gate_pg_bak_007
\echo '@@CHECK PG-BAK-007'
-- check: PG-BAK-007
-- title: archive_timeout unset on a low-write primary
-- priority: 50
-- scope: setting
-- cost: 0
-- run_on: primary
SELECT 'PG-BAK-007'::text      AS check_id,
       'setting'::text         AS scope,
       'archive_timeout'::text AS object,
       format('archive_mode = %s with archive_timeout = 0 and no pg_receivewal connected. A WAL segment ships only when it fills, so on a low-write server the current segment may sit unarchived for hours and the recovery point objective is undefined. Archiver has shipped %s segments%s. A value of 60 to 300 seconds bounds the exposure at the cost of one partly-filled 16 MB segment per interval.',
              current_setting('archive_mode'),
              to_char((SELECT archived_count FROM pg_stat_archiver), 'FM999,999,999,999'),
              coalesce('; last at ' || (SELECT last_archived_time FROM pg_stat_archiver)::text
                       || ' (' || justify_interval(now() - (SELECT last_archived_time FROM pg_stat_archiver))::text || ' ago)', '')) AS details,
       json_build_object('archive_timeout', 0, 'archive_mode', current_setting('archive_mode'),
                         'archived_count', (SELECT archived_count FROM pg_stat_archiver),
                         'last_archived_time', (SELECT last_archived_time FROM pg_stat_archiver),
                         'walreceiver_clients', (SELECT count(*) FROM pg_stat_replication
                                                 WHERE application_name ILIKE '%receivewal%'
                                                    OR application_name ILIKE '%pg_receivexlog%'))::text AS evidence_json,
       'medium'::text AS confidence
WHERE current_setting('archive_mode') <> 'off'
  AND NOT pg_is_in_recovery()
  AND (SELECT setting::int FROM pg_settings WHERE name = 'archive_timeout') = 0
  AND NOT EXISTS (SELECT 1 FROM pg_stat_replication
                  WHERE application_name ILIKE '%receivewal%' OR application_name ILIKE '%pg_receivexlog%');
\echo '@@END PG-BAK-007'
\else
\echo '@@SKIP PG-BAK-007 primary only'
\endif

-- ======== PG-CONN-002  P50  Connections at 70 percent or more of max_connections ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_conn_002 \gset
\if :gate_pg_conn_002
\echo '@@CHECK PG-CONN-002'
-- check: PG-CONN-002
-- title: Connections at 70 percent or more of max_connections
-- priority: 50
-- scope: cluster
-- cost: 0
-- min_version: 10
-- thresholds: conn_fraction, conn_fraction_high
WITH lim AS (
  SELECT (SELECT setting::int FROM pg_settings WHERE name = 'max_connections')                  AS max_conn,
         (SELECT setting::int FROM pg_settings WHERE name = 'superuser_reserved_connections')   AS su_reserved,
         coalesce((SELECT setting::int FROM pg_settings WHERE name = 'reserved_connections'), 0) AS reserved
),
cur AS (
  SELECT count(*) FILTER (WHERE backend_type = 'client backend')                    AS clients,
         count(*) FILTER (WHERE backend_type = 'client backend' AND state = 'idle') AS idle,
         count(*) FILTER (WHERE backend_type = 'client backend' AND state = 'active') AS active,
         count(*) FILTER (WHERE backend_type = 'client backend' AND state LIKE 'idle in transaction%') AS idle_in_txn
  FROM pg_stat_activity
)
SELECT 'PG-CONN-002'::text AS check_id,
       'cluster'::text  AS scope,
       'max_connections'::text AS object,
       format('%s client backends against a usable ceiling of %s (max_connections %s less %s superuser-reserved and %s reserved): %s%% (threshold %s%%). Of those, %s are active, %s idle and %s idle in transaction. The next connection past the ceiling is refused with "FATAL: sorry, too many clients already", which the application sees as an outage rather than as slowness.',
              c.clients, l.max_conn - l.su_reserved - l.reserved, l.max_conn, l.su_reserved, l.reserved,
              round(100.0 * c.clients / nullif(l.max_conn - l.su_reserved - l.reserved, 0), 1)::text,
              round(100 * :'pg_conn_002_conn_fraction'::numeric)::text,
              c.active, c.idle, c.idle_in_txn) AS details,
       json_build_object('client_backends', c.clients, 'max_connections', l.max_conn,
                         'superuser_reserved_connections', l.su_reserved, 'reserved_connections', l.reserved,
                         'usable_ceiling', l.max_conn - l.su_reserved - l.reserved,
                         'fraction_used', round(c.clients::numeric / nullif(l.max_conn - l.su_reserved - l.reserved, 0), 4),
                         'threshold_fraction', :'pg_conn_002_conn_fraction'::numeric,
                         'active', c.active, 'idle', c.idle, 'idle_in_transaction', c.idle_in_txn)::text AS evidence_json,
       'high'::text AS confidence
FROM cur c CROSS JOIN lim l
WHERE c.clients >= :'pg_conn_002_conn_fraction'::numeric * (l.max_conn - l.su_reserved - l.reserved)
  AND c.clients < :'pg_conn_002_conn_fraction_high'::numeric * (l.max_conn - l.su_reserved - l.reserved);
\echo '@@END PG-CONN-002'
\else
\echo '@@SKIP PG-CONN-002 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-CONN-003  P50  max_connections very high with no evidence of a pooler ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_conn_003 \gset
\if :gate_pg_conn_003
\echo '@@CHECK PG-CONN-003'
-- check: PG-CONN-003
-- title: max_connections very high with no evidence of a pooler
-- priority: 50
-- scope: setting
-- cost: 0
-- min_version: 10
-- thresholds: max_conn, pooler_address_fraction, pooler_address_count
WITH a AS (
  SELECT count(*) AS clients,
         count(*) FILTER (WHERE application_name ~* '(pgbouncer|pgpool|pgcat|odyssey|supavisor|rds_?proxy|pgagroal)') AS pooler_named,
         count(DISTINCT client_addr) AS distinct_addrs
  FROM pg_stat_activity WHERE backend_type = 'client backend'
),
top AS (
  SELECT coalesce(sum(n), 0) AS top_n_clients FROM (
    SELECT count(*) AS n FROM pg_stat_activity
    WHERE backend_type = 'client backend' AND client_addr IS NOT NULL
    GROUP BY client_addr ORDER BY count(*) DESC
    LIMIT :'pg_conn_003_pooler_address_count'::int) t
)
SELECT 'PG-CONN-003'::text     AS check_id,
       'setting'::text         AS scope,
       'max_connections'::text AS object,
       format('max_connections = %s (threshold %s) and nothing suggests a connection pooler in front of it: no backend has a pooler application_name, and the busiest %s client addresses account for %s of %s current connections (%s%%, threshold %s%%) across %s distinct addresses. Each PostgreSQL connection is an operating-system process with its own memory (see PG-MEM-003, worst case %s) and its own share of the snapshot and lock-manager overhead every backend pays. A transaction-mode pooler usually lets max_connections come down by an order of magnitude.',
              (SELECT setting FROM pg_settings WHERE name = 'max_connections'),
              :'pg_conn_003_max_conn'::text,
              :'pg_conn_003_pooler_address_count'::text,
              t.top_n_clients, a.clients,
              round(100.0 * t.top_n_clients / nullif(a.clients, 0), 1)::text,
              round(100 * :'pg_conn_003_pooler_address_fraction'::numeric)::text,
              a.distinct_addrs,
              pg_size_pretty(((SELECT setting::bigint * 8192 FROM pg_settings WHERE name = 'shared_buffers')
                              + (SELECT setting::bigint FROM pg_settings WHERE name = 'max_connections')
                                * (SELECT setting::bigint * 1024 FROM pg_settings WHERE name = 'work_mem') * 2)::bigint)) AS details,
       json_build_object('max_connections', (SELECT setting::int FROM pg_settings WHERE name = 'max_connections'),
                         'threshold_max_connections', :'pg_conn_003_max_conn'::int,
                         'client_backends', a.clients, 'distinct_client_addrs', a.distinct_addrs,
                         'pooler_named_backends', a.pooler_named,
                         'top_address_clients', t.top_n_clients,
                         'top_address_fraction', round(t.top_n_clients::numeric / nullif(a.clients, 0), 4),
                         'threshold_fraction', :'pg_conn_003_pooler_address_fraction'::numeric)::text AS evidence_json,
       'medium'::text AS confidence
FROM a CROSS JOIN top t
WHERE (SELECT setting::int FROM pg_settings WHERE name = 'max_connections') >= :'pg_conn_003_max_conn'::int
  AND a.pooler_named = 0
  AND coalesce(t.top_n_clients::numeric / nullif(a.clients, 0), 0) < :'pg_conn_003_pooler_address_fraction'::numeric;
\echo '@@END PG-CONN-003'
\else
\echo '@@SKIP PG-CONN-003 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-CONN-008  P50  Sessions currently waiting on locks ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_conn_008 \gset
\if :gate_pg_conn_008
\echo '@@CHECK PG-CONN-008'
-- check: PG-CONN-008
-- title: Sessions currently waiting on locks
-- priority: 50
-- scope: cluster
-- cost: 0
-- min_version: 10
-- thresholds: waiting_sessions
WITH w AS (
  SELECT count(*) AS waiting,
         string_agg(DISTINCT coalesce(wait_event, 'unknown'), ', ') AS events,
         max(now() - state_change) AS longest
  FROM pg_stat_activity
  WHERE wait_event_type = 'Lock' AND backend_type = 'client backend'
)
SELECT 'PG-CONN-008'::text AS check_id,
       'cluster'::text     AS scope,
       NULL::text          AS object,
       format('%s client sessions are waiting on a lock at snapshot time (threshold %s). Lock types being waited on: %s. The longest has been waiting %s. This is a single sample, so it may be a pile-up in progress or a coincidence; PG-LOCK-001 and PG-LOCK-002 identify the chain and the session at the root of it. deadlock_timeout = %s, log_lock_waits = %s.',
              w.waiting, :'pg_conn_008_waiting_sessions'::text,
              coalesce(w.events, 'none'),
              coalesce(justify_interval(w.longest)::text, 'unknown'),
              current_setting('deadlock_timeout'), current_setting('log_lock_waits')) AS details,
       json_build_object('waiting_sessions', w.waiting,
                         'threshold', :'pg_conn_008_waiting_sessions'::int,
                         'wait_events', w.events,
                         'longest_wait_seconds', round(extract(epoch FROM w.longest))::bigint,
                         'deadlock_timeout', current_setting('deadlock_timeout'),
                         'log_lock_waits', current_setting('log_lock_waits'),
                         'sampled_at', now())::text AS evidence_json,
       'high'::text AS confidence
FROM w
WHERE w.waiting >= :'pg_conn_008_waiting_sessions'::int;
\echo '@@END PG-CONN-008'
\else
\echo '@@SKIP PG-CONN-008 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-CORR-004  P50  Data checksums disabled ========
\echo '@@CHECK PG-CORR-004'
-- check: PG-CORR-004
-- title: Data checksums disabled
-- priority: 50
-- scope: cluster
-- cost: 0
SELECT 'PG-CORR-004'::text     AS check_id,
       'cluster'::text         AS scope,
       'data_checksums'::text  AS object,
       format('data_checksums = off. Pages carry no checksum, so storage-level corruption is detected only when it happens to break a structure Postgres validates: a torn page, a flipped bit inside a value, or a silently truncated read returns wrong answers instead of an error. Cluster holds %s across %s databases. Enabling requires pg_checksums with the cluster shut down (PostgreSQL 12 and newer) or a dump and reload. full_page_writes = %s.',
              pg_size_pretty((SELECT sum(pg_database_size(oid)) FROM pg_database)),
              (SELECT count(*) FROM pg_database WHERE datallowconn),
              current_setting('full_page_writes')) AS details,
       json_build_object('data_checksums', 'off',
                         'cluster_bytes', (SELECT sum(pg_database_size(oid)) FROM pg_database),
                         'database_count', (SELECT count(*) FROM pg_database WHERE datallowconn),
                         'full_page_writes', current_setting('full_page_writes'),
                         'server_version_num', current_setting('server_version_num')::int)::text AS evidence_json,
       'high'::text AS confidence
WHERE current_setting('data_checksums') = 'off';
\echo '@@END PG-CORR-004'

-- ======== PG-LOCK-002  P50  Blocking chain: session blocked more than 30 seconds ========
SELECT (current_setting('server_version_num')::int >= 90600) AS gate_pg_lock_002 \gset
\if :gate_pg_lock_002
\echo '@@CHECK PG-LOCK-002'
-- check: PG-LOCK-002
-- title: Blocking chain: session blocked more than 30 seconds
-- priority: 50
-- scope: session
-- cost: 0
-- min_version: 9.6
-- thresholds: blocked_seconds, blocked_seconds_high
SELECT 'PG-LOCK-002'::text AS check_id,
       'session'::text  AS scope,
       ('pid:' || a.pid)::text AS object,
       format('pid %s (%s / %s, from %s) has been blocked for %s (threshold %s) waiting on %s. It is blocked by pid(s) %s. Root blocker pid %s: state %s, transaction open since %s (%s), application %s, query: %s. Blocked query: %s',
              a.pid, coalesce(nullif(a.usename, ''), '?'),
              coalesce(nullif(a.application_name, ''), 'no application_name'),
              coalesce(host(a.client_addr), 'local socket'),
              justify_interval(date_trunc('second', now() - a.state_change)),
              (:'pg_lock_002_blocked_seconds'::int || ' seconds')::interval,
              coalesce(a.wait_event_type || '/' || a.wait_event, 'a lock'),
              array_to_string(pg_blocking_pids(a.pid), ', '),
              b.pid, coalesce(b.state, '?'),
              coalesce(b.xact_start::text, 'no transaction'),
              coalesce(justify_interval(date_trunc('second', now() - b.xact_start))::text, 'n/a'),
              coalesce(nullif(b.application_name, ''), 'no application_name'),
              left(regexp_replace(coalesce(b.query, ''), '\s+', ' ', 'g'), 200),
              left(regexp_replace(coalesce(a.query, ''), '\s+', ' ', 'g'), 200)) AS details,
       json_build_object('blocked_pid', a.pid, 'blocked_seconds', round(extract(epoch FROM now() - a.state_change))::bigint,
                         'threshold_seconds', :'pg_lock_002_blocked_seconds'::int,
                         'blocking_pids', pg_blocking_pids(a.pid),
                         'root_blocker_pid', b.pid, 'root_blocker_state', b.state,
                         'root_blocker_xact_seconds', round(extract(epoch FROM now() - b.xact_start))::bigint,
                         'root_blocker_application', b.application_name,
                         'wait_event_type', a.wait_event_type, 'wait_event', a.wait_event,
                         'blocked_usename', a.usename, 'blocked_database', a.datname,
                         'sampled_at', now())::text AS evidence_json,
       'high'::text AS confidence
FROM pg_stat_activity a
LEFT JOIN LATERAL (
  SELECT * FROM pg_stat_activity x
  WHERE x.pid = (pg_blocking_pids(a.pid))[1]
) b ON true
WHERE cardinality(pg_blocking_pids(a.pid)) > 0
  AND a.state_change IS NOT NULL
  AND now() - a.state_change >= (:'pg_lock_002_blocked_seconds'::int || ' seconds')::interval
  AND now() - a.state_change < (:'pg_lock_002_blocked_seconds_high'::int || ' seconds')::interval
ORDER BY a.state_change;
\echo '@@END PG-LOCK-002'
\else
\echo '@@SKIP PG-LOCK-002 needs PostgreSQL 9.6 or newer'
\endif

-- ======== PG-LOCK-004  P50  Idle in transaction for more than 5 minutes ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_lock_004 \gset
\if :gate_pg_lock_004
\echo '@@CHECK PG-LOCK-004'
-- check: PG-LOCK-004
-- title: Idle in transaction for more than 5 minutes
-- priority: 50
-- scope: session
-- cost: 0
-- min_version: 10
-- thresholds: idle_seconds, idle_seconds_high
SELECT 'PG-LOCK-004'::text AS check_id,
       'session'::text  AS scope,
       ('pid:' || a.pid)::text AS object,
       format('pid %s (%s / %s, from %s, database %s) has been in state "%s" for %s (threshold %s). Its transaction opened at %s and has been open for %s. It holds every lock the transaction has taken and pins the xmin horizon at age %s, so vacuum cannot remove any row version newer than that anywhere in the cluster (PG-VAC-005), and any DDL that needs a lock on the same objects queues behind it. Last statement: %s',
              a.pid, coalesce(nullif(a.usename, ''), '?'),
              coalesce(nullif(a.application_name, ''), 'no application_name'),
              coalesce(host(a.client_addr), 'local socket'), coalesce(a.datname, '?'),
              a.state, justify_interval(date_trunc('second', now() - a.state_change)),
              (:'pg_lock_004_idle_seconds'::int || ' seconds')::interval,
              coalesce(a.xact_start::text, 'unknown'),
              coalesce(justify_interval(date_trunc('second', now() - a.xact_start))::text, 'unknown'),
              coalesce(age(a.backend_xmin)::text, 'none held'),
              left(regexp_replace(coalesce(a.query, ''), '\s+', ' ', 'g'), 200)) AS details,
       json_build_object('pid', a.pid, 'state', a.state, 'usename', a.usename,
                         'application_name', a.application_name, 'datname', a.datname,
                         'client_addr', host(a.client_addr),
                         'idle_seconds', round(extract(epoch FROM now() - a.state_change))::bigint,
                         'threshold_seconds', :'pg_lock_004_idle_seconds'::int,
                         'xact_seconds', round(extract(epoch FROM now() - a.xact_start))::bigint,
                         'backend_xmin_age', CASE WHEN a.backend_xmin IS NULL THEN NULL ELSE age(a.backend_xmin) END,
                         'sampled_at', now())::text AS evidence_json,
       'high'::text AS confidence
FROM pg_stat_activity a
WHERE a.state LIKE 'idle in transaction%'
  AND a.state_change IS NOT NULL
  AND now() - a.state_change >= (:'pg_lock_004_idle_seconds'::int || ' seconds')::interval
  AND now() - a.state_change < (:'pg_lock_004_idle_seconds_high'::int || ' seconds')::interval
ORDER BY a.state_change;
\echo '@@END PG-LOCK-004'
\else
\echo '@@SKIP PG-LOCK-004 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-MEM-003  P50  Worst-case memory commitment exceeds RAM (OOM risk) ========
\echo '@@CHECK PG-MEM-003'
-- check: PG-MEM-003
-- title: Worst-case memory commitment exceeds RAM (OOM risk)
-- priority: 50
-- scope: setting
-- cost: 0
-- thresholds: ram_bytes, ram_fraction
-- Requires RAM: pass -v pg_mem_003_ram_bytes=<bytes>. With RAM unknown (0) the
-- check emits nothing; the computed worst-case figure is still reported in
-- PG-INFO-001 evidence so it is never lost.
WITH s AS (
  SELECT (SELECT setting::numeric * 8192 FROM pg_settings WHERE name = 'shared_buffers')          AS shared_buffers,
         (SELECT setting::numeric * 8192 FROM pg_settings WHERE name = 'wal_buffers')             AS wal_buffers,
         (SELECT setting::int       FROM pg_settings WHERE name = 'max_connections')              AS max_connections,
         (SELECT setting::numeric * 1024 FROM pg_settings WHERE name = 'work_mem')                AS work_mem,
         coalesce((SELECT setting::numeric FROM pg_settings WHERE name = 'hash_mem_multiplier'), 1) AS hash_mult,
         (SELECT setting::numeric * 1024 FROM pg_settings WHERE name = 'maintenance_work_mem')    AS maint_mem,
         (SELECT setting::numeric FROM pg_settings WHERE name = 'autovacuum_work_mem')            AS av_mem_raw,
         (SELECT setting::int FROM pg_settings WHERE name = 'autovacuum_max_workers')             AS av_workers
),
calc AS (
  SELECT s.*,
         CASE WHEN s.av_mem_raw < 0 THEN s.maint_mem ELSE s.av_mem_raw * 1024 END AS av_mem,
         s.shared_buffers + s.wal_buffers
           + s.max_connections * s.work_mem * greatest(2, s.hash_mult)
           + s.av_workers * (CASE WHEN s.av_mem_raw < 0 THEN s.maint_mem ELSE s.av_mem_raw * 1024 END) AS worst_case
  FROM s
)
SELECT 'PG-MEM-003'::text AS check_id,
       'setting'::text    AS scope,
       'max_connections'::text AS object,
       format('Worst-case memory commitment is %s against %s of RAM (%s%%). That is shared_buffers %s + wal_buffers %s + max_connections %s x work_mem %s x hash_mem_multiplier factor %s + %s autovacuum workers x %s. A single backend can use work_mem once per sort, hash or materialise node, so the real ceiling is higher still. When the Linux OOM killer fires it usually takes the postmaster, which restarts the whole cluster and disconnects every session.',
              pg_size_pretty(c.worst_case::bigint),
              pg_size_pretty(:'pg_mem_003_ram_bytes'::bigint),
              round(100.0 * c.worst_case / :'pg_mem_003_ram_bytes'::numeric)::text,
              pg_size_pretty(c.shared_buffers::bigint), pg_size_pretty(c.wal_buffers::bigint),
              c.max_connections, pg_size_pretty(c.work_mem::bigint), greatest(2, c.hash_mult)::text,
              c.av_workers, pg_size_pretty(c.av_mem::bigint)) AS details,
       json_build_object('worst_case_bytes', c.worst_case::bigint,
                         'ram_bytes', :'pg_mem_003_ram_bytes'::bigint,
                         'fraction_of_ram', round(c.worst_case / :'pg_mem_003_ram_bytes'::numeric, 3),
                         'shared_buffers_bytes', c.shared_buffers::bigint,
                         'wal_buffers_bytes', c.wal_buffers::bigint,
                         'max_connections', c.max_connections,
                         'work_mem_bytes', c.work_mem::bigint,
                         'hash_mem_multiplier', c.hash_mult,
                         'autovacuum_max_workers', c.av_workers,
                         'autovacuum_work_mem_bytes', c.av_mem::bigint)::text AS evidence_json,
       'medium'::text AS confidence
FROM calc c
WHERE :'pg_mem_003_ram_bytes'::bigint > 0
  AND c.worst_case >= :'pg_mem_003_ram_fraction'::numeric * :'pg_mem_003_ram_bytes'::bigint;
\echo '@@END PG-MEM-003'

-- ======== PG-REPL-004  P50  Inactive replication slot ========
SELECT (current_setting('server_version_num')::int >= 90400) AS gate_pg_repl_004 \gset
\if :gate_pg_repl_004
\echo '@@CHECK PG-REPL-004'
-- check: PG-REPL-004
-- title: Inactive replication slot
-- priority: 50
-- scope: slot
-- cost: 0
-- min_version: 9.4
-- thresholds: retained_bytes_low
\set ON_ERROR_STOP off
SELECT (current_setting('server_version_num')::int >= 130000) AS pg_repl_004_has_wal_status \gset
SELECT (current_setting('server_version_num')::int >= 170000) AS pg_repl_004_has_inactive_since \gset
WITH cur AS (
  SELECT CASE WHEN pg_is_in_recovery() THEN pg_last_wal_receive_lsn() ELSE pg_current_wal_lsn() END AS lsn
),
slots AS (
  SELECT s.slot_name, s.slot_type, s.plugin, s.database, s.active, s.active_pid,
         s.restart_lsn, s.xmin, s.catalog_xmin,
         CASE WHEN s.restart_lsn IS NULL THEN NULL
              ELSE pg_wal_lsn_diff(cur.lsn, s.restart_lsn)::bigint END AS retained_bytes,
\if :pg_repl_004_has_wal_status
         s.wal_status,
\else
         NULL::text AS wal_status,
\endif
\if :pg_repl_004_has_inactive_since
         s.inactive_since,
\else
         NULL::timestamptz AS inactive_since,
\endif
         cur.lsn AS current_lsn
  FROM pg_replication_slots s CROSS JOIN cur
)
SELECT 'PG-REPL-004'::text AS check_id,
       'slot'::text   AS scope,
       s.slot_name::text AS object,
       format('Replication slot %s (%s%s) is inactive and is holding back %s of WAL (threshold %s). restart_lsn %s against current %s.%s%s Until the slot is consumed or dropped, the WAL it pins cannot be recycled or archived away, and pg_wal grows without limit unless max_slot_wal_keep_size is set (currently %s).',
              s.slot_name, s.slot_type,
              coalesce(', plugin ' || s.plugin, ''),
              coalesce(pg_size_pretty(s.retained_bytes), 'an unknown amount'),
              pg_size_pretty(:'pg_repl_004_retained_bytes_low'::bigint),
              coalesce(s.restart_lsn::text, 'none'), s.current_lsn::text,
              coalesce(' wal_status = ' || s.wal_status || '.', ''),
              coalesce(' Inactive since ' || s.inactive_since::text || ' (' || justify_interval(date_trunc('second', now() - s.inactive_since))::text || ').', ''),
              current_setting('max_slot_wal_keep_size')) AS details,
       json_build_object('slot_name', s.slot_name, 'slot_type', s.slot_type, 'plugin', s.plugin,
                         'database', s.database, 'active', s.active,
                         'retained_bytes', s.retained_bytes,
                         'threshold_bytes', :'pg_repl_004_retained_bytes_low'::bigint,
                         'restart_lsn', s.restart_lsn::text, 'current_lsn', s.current_lsn::text,
                         'wal_status', s.wal_status, 'inactive_since', s.inactive_since,
                         'xmin_age', CASE WHEN s.xmin IS NULL THEN NULL ELSE age(s.xmin) END,
                         'catalog_xmin_age', CASE WHEN s.catalog_xmin IS NULL THEN NULL ELSE age(s.catalog_xmin) END,
                         'max_slot_wal_keep_size', current_setting('max_slot_wal_keep_size'))::text AS evidence_json,
       'high'::text AS confidence
FROM slots s
WHERE NOT s.active
  AND coalesce(s.retained_bytes, 0) < :'pg_repl_004_retained_bytes_low'::bigint
ORDER BY s.retained_bytes DESC NULLS LAST;
\echo '@@END PG-REPL-004'
\else
\echo '@@SKIP PG-REPL-004 needs PostgreSQL 9.4 or newer'
\endif

-- ======== PG-REPL-007  P50  Streaming replica lag moderate ========
SELECT (current_setting('server_version_num')::int >= 100000 AND NOT pg_is_in_recovery()) AS gate_pg_repl_007 \gset
\if :gate_pg_repl_007
\echo '@@CHECK PG-REPL-007'
-- check: PG-REPL-007
-- title: Streaming replica lag moderate
-- priority: 50
-- scope: replica
-- cost: 0
-- min_version: 10
-- run_on: primary
-- thresholds: lag_bytes, lag_seconds, lag_bytes_high, lag_seconds_high
SELECT 'PG-REPL-007'::text AS check_id,
       'replica'::text  AS scope,
       coalesce(nullif(r.application_name, ''), 'pid:' || r.pid::text)::text AS object,
       format('Standby %s at %s is %s behind on replay and %s behind in time (thresholds %s / %s). state = %s, sync_state = %s. sent %s, write %s, flush %s, replay %s. write_lag %s, flush_lag %s, replay_lag %s. A failover to this standby now would lose everything after its replay position, and promoting it would first have to apply the backlog.',
              coalesce(nullif(r.application_name, ''), 'unnamed'),
              coalesce(host(r.client_addr), 'local socket'),
              pg_size_pretty(greatest(pg_wal_lsn_diff(r.sent_lsn, r.replay_lsn), 0)::bigint),
              coalesce(justify_interval(r.replay_lag)::text, 'an unknown interval'),
              pg_size_pretty(:'pg_repl_007_lag_bytes'::bigint),
              (:'pg_repl_007_lag_seconds'::int || ' seconds')::interval::text,
              r.state, r.sync_state,
              r.sent_lsn::text, r.write_lsn::text, r.flush_lsn::text, r.replay_lsn::text,
              coalesce(r.write_lag::text, 'null'), coalesce(r.flush_lag::text, 'null'),
              coalesce(r.replay_lag::text, 'null')) AS details,
       json_build_object('application_name', r.application_name, 'client_addr', host(r.client_addr),
                         'state', r.state, 'sync_state', r.sync_state, 'pid', r.pid,
                         'lag_bytes', greatest(pg_wal_lsn_diff(r.sent_lsn, r.replay_lsn), 0)::bigint,
                         'replay_lag_seconds', round(extract(epoch FROM r.replay_lag))::bigint,
                         'write_lag_seconds', round(extract(epoch FROM r.write_lag))::bigint,
                         'flush_lag_seconds', round(extract(epoch FROM r.flush_lag))::bigint,
                         'threshold_bytes', :'pg_repl_007_lag_bytes'::bigint,
                         'threshold_seconds', :'pg_repl_007_lag_seconds'::int,
                         'sent_lsn', r.sent_lsn::text, 'replay_lsn', r.replay_lsn::text,
                         'backend_start', r.backend_start)::text AS evidence_json,
       'high'::text AS confidence
FROM pg_stat_replication r
WHERE (greatest(pg_wal_lsn_diff(r.sent_lsn, r.replay_lsn), 0) >= :'pg_repl_007_lag_bytes'::bigint
       OR r.replay_lag >= (:'pg_repl_007_lag_seconds'::int || ' seconds')::interval)
  AND NOT (greatest(pg_wal_lsn_diff(r.sent_lsn, r.replay_lsn), 0) >= :'pg_repl_007_lag_bytes_high'::bigint
           OR r.replay_lag >= (:'pg_repl_007_lag_seconds_high'::int || ' seconds')::interval)
ORDER BY pg_wal_lsn_diff(r.sent_lsn, r.replay_lsn) DESC NULLS LAST;
\echo '@@END PG-REPL-007'
\else
\echo '@@SKIP PG-REPL-007 needs PostgreSQL 10 or newer; primary only'
\endif

-- ======== PG-REPL-009  P50  Slot WAL retention unbounded ========
SELECT (current_setting('server_version_num')::int >= 130000 AND NOT pg_is_in_recovery()) AS gate_pg_repl_009 \gset
\if :gate_pg_repl_009
\echo '@@CHECK PG-REPL-009'
-- check: PG-REPL-009
-- title: Slot WAL retention unbounded
-- priority: 50
-- scope: setting
-- cost: 0
-- min_version: 13
-- run_on: primary
SELECT 'PG-REPL-009'::text            AS check_id,
       'setting'::text                AS scope,
       'max_slot_wal_keep_size'::text AS object,
       format('max_slot_wal_keep_size = -1 (unlimited) while %s replication slot(s) exist: %s. Any consumer that stops - a crashed logical decoder, a decommissioned standby whose slot was never dropped, a paused CDC connector - pins WAL indefinitely, and pg_wal grows until the volume fills and the primary PANICs. Setting a cap sized to the WAL volume converts that outage into a broken slot (wal_status = lost, PG-REPL-005), which is recoverable. pg_wal currently holds %s.',
              (SELECT count(*) FROM pg_replication_slots),
              (SELECT string_agg(format('%s (%s, active=%s)', slot_name, slot_type, active), '; ' ORDER BY slot_name)
               FROM pg_replication_slots),
              coalesce((SELECT pg_size_pretty(sum(size)) FROM pg_ls_waldir()), 'an unknown amount')) AS details,
       json_build_object('max_slot_wal_keep_size', '-1',
                         'slot_count', (SELECT count(*) FROM pg_replication_slots),
                         'inactive_slot_count', (SELECT count(*) FROM pg_replication_slots WHERE NOT active),
                         'max_wal_size', current_setting('max_wal_size'),
                         'wal_keep_size', current_setting('wal_keep_size'))::text AS evidence_json,
       'high'::text AS confidence
WHERE NOT pg_is_in_recovery()
  AND (SELECT setting::int FROM pg_settings WHERE name = 'max_slot_wal_keep_size') = -1
  AND (SELECT count(*) FROM pg_replication_slots) >= 1;
\echo '@@END PG-REPL-009'
\else
\echo '@@SKIP PG-REPL-009 needs PostgreSQL 13 or newer; primary only'
\endif

-- ======== PG-REPL-010  P50  Standby streaming without a slot while wal_keep_size is 0 ========
SELECT (current_setting('server_version_num')::int >= 90400 AND NOT pg_is_in_recovery()) AS gate_pg_repl_010 \gset
\if :gate_pg_repl_010
\echo '@@CHECK PG-REPL-010'
-- check: PG-REPL-010
-- title: Standby streaming without a slot while wal_keep_size is 0
-- priority: 50
-- scope: replica
-- cost: 0
-- min_version: 9.4
-- run_on: primary
WITH keepsize AS (
  SELECT coalesce((SELECT setting::bigint FROM pg_settings WHERE name = 'wal_keep_size'),
                  (SELECT setting::bigint FROM pg_settings WHERE name = 'wal_keep_segments'), 0) AS keep,
         coalesce((SELECT name FROM pg_settings WHERE name IN ('wal_keep_size', 'wal_keep_segments')), 'wal_keep_size') AS keep_name
)
SELECT 'PG-REPL-010'::text AS check_id,
       'replica'::text     AS scope,
       coalesce(nullif(r.application_name, ''), 'pid:' || r.pid::text)::text AS object,
       format('Standby %s at %s is streaming without a replication slot while %s = 0. The primary keeps only the WAL its own checkpoints have not yet recycled, so any network interruption longer than the checkpoint interval (checkpoint_timeout = %s, max_wal_size = %s) leaves the standby asking for a segment that no longer exists, and it must be rebuilt from a fresh base backup. Existing slots: %s.',
              coalesce(nullif(r.application_name, ''), 'unnamed'),
              coalesce(host(r.client_addr), 'local socket'), k.keep_name,
              current_setting('checkpoint_timeout'),
              current_setting('max_wal_size'),
              coalesce((SELECT string_agg(slot_name, ', ') FROM pg_replication_slots), 'none')) AS details,
       json_build_object('application_name', r.application_name, 'client_addr', host(r.client_addr),
                         'pid', r.pid, 'state', r.state, 'sync_state', r.sync_state,
                         'wal_keep_setting', k.keep_name, 'wal_keep_value', k.keep,
                         'slot_count', (SELECT count(*) FROM pg_replication_slots))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_stat_replication r CROSS JOIN keepsize k
WHERE NOT pg_is_in_recovery()
  AND k.keep = 0
  AND NOT EXISTS (SELECT 1 FROM pg_replication_slots s WHERE s.active_pid = r.pid);
\echo '@@END PG-REPL-010'
\else
\echo '@@SKIP PG-REPL-010 needs PostgreSQL 9.4 or newer; primary only'
\endif

-- ======== PG-REPL-011  P50  Standby query conflicts high ========
SELECT (pg_is_in_recovery()) AS gate_pg_repl_011 \gset
\if :gate_pg_repl_011
\echo '@@CHECK PG-REPL-011'
-- check: PG-REPL-011
-- title: Standby query conflicts high
-- priority: 50
-- scope: database
-- cost: 0
-- run_on: standby
-- thresholds: conflicts_per_day
WITH win AS (
  SELECT greatest(extract(epoch FROM now() - coalesce(
           (SELECT min(stats_reset) FROM pg_stat_database), pg_postmaster_start_time())) / 86400.0, 0.01) AS days
)
SELECT 'PG-REPL-011'::text AS check_id,
       'database'::text    AS scope,
       c.datname::text     AS object,
       format('%s recovery conflicts in database %s over %s days (%s per day, threshold %s per day): %s tablespace, %s lock, %s snapshot, %s bufferpin, %s deadlock. Queries on this standby are being cancelled to let WAL replay proceed. max_standby_streaming_delay = %s, hot_standby_feedback = %s.',
              to_char(c.confl_tablespace + c.confl_lock + c.confl_snapshot + c.confl_bufferpin + c.confl_deadlock, 'FM999,999,999'),
              c.datname, round(win.days, 1)::text,
              round((c.confl_tablespace + c.confl_lock + c.confl_snapshot + c.confl_bufferpin + c.confl_deadlock) / win.days, 1)::text,
              :'pg_repl_011_conflicts_per_day'::text,
              c.confl_tablespace, c.confl_lock, c.confl_snapshot, c.confl_bufferpin, c.confl_deadlock,
              current_setting('max_standby_streaming_delay'),
              current_setting('hot_standby_feedback')) AS details,
       json_build_object('datname', c.datname,
                         'confl_tablespace', c.confl_tablespace, 'confl_lock', c.confl_lock,
                         'confl_snapshot', c.confl_snapshot, 'confl_bufferpin', c.confl_bufferpin,
                         'confl_deadlock', c.confl_deadlock,
                         'window_days', round(win.days, 2),
                         'conflicts_per_day', round((c.confl_tablespace + c.confl_lock + c.confl_snapshot
                                                   + c.confl_bufferpin + c.confl_deadlock) / win.days, 2),
                         'threshold_per_day', :'pg_repl_011_conflicts_per_day'::numeric,
                         'max_standby_streaming_delay', current_setting('max_standby_streaming_delay'),
                         'hot_standby_feedback', current_setting('hot_standby_feedback'))::text AS evidence_json,
       'medium'::text AS confidence
FROM pg_stat_database_conflicts c CROSS JOIN win
WHERE pg_is_in_recovery()
  AND (c.confl_tablespace + c.confl_lock + c.confl_snapshot + c.confl_bufferpin + c.confl_deadlock) / win.days
      >= :'pg_repl_011_conflicts_per_day'::numeric
ORDER BY (c.confl_tablespace + c.confl_lock + c.confl_snapshot + c.confl_bufferpin + c.confl_deadlock) DESC;
\echo '@@END PG-REPL-011'
\else
\echo '@@SKIP PG-REPL-011 standby only'
\endif

-- ======== PG-REPL-014  P50  Synchronous standby with high flush lag ========
SELECT (current_setting('server_version_num')::int >= 100000 AND NOT pg_is_in_recovery()) AS gate_pg_repl_014 \gset
\if :gate_pg_repl_014
\echo '@@CHECK PG-REPL-014'
-- check: PG-REPL-014
-- title: Synchronous standby with high flush lag
-- priority: 50
-- scope: replica
-- cost: 0
-- min_version: 10
-- run_on: primary
-- thresholds: flush_lag_seconds
SELECT 'PG-REPL-014'::text AS check_id,
       'replica'::text     AS scope,
       coalesce(nullif(r.application_name, ''), 'pid:' || r.pid::text)::text AS object,
       format('Synchronous standby %s at %s has flush_lag %s (threshold %s). synchronous_commit = %s, so every commit on this primary waits for that standby to flush before returning: this lag is added directly to application commit latency. write_lag %s, replay_lag %s, state %s.',
              coalesce(nullif(r.application_name, ''), 'unnamed'),
              coalesce(host(r.client_addr), 'local socket'),
              r.flush_lag::text,
              (:'pg_repl_014_flush_lag_seconds'::numeric || ' seconds')::interval::text,
              current_setting('synchronous_commit'),
              coalesce(r.write_lag::text, 'null'), coalesce(r.replay_lag::text, 'null'), r.state) AS details,
       json_build_object('application_name', r.application_name, 'sync_state', r.sync_state,
                         'flush_lag_seconds', round(extract(epoch FROM r.flush_lag), 3),
                         'write_lag_seconds', round(extract(epoch FROM r.write_lag), 3),
                         'replay_lag_seconds', round(extract(epoch FROM r.replay_lag), 3),
                         'threshold_seconds', :'pg_repl_014_flush_lag_seconds'::numeric,
                         'synchronous_commit', current_setting('synchronous_commit'),
                         'client_addr', host(r.client_addr))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_stat_replication r
WHERE r.sync_state IN ('sync', 'quorum')
  AND r.flush_lag >= (:'pg_repl_014_flush_lag_seconds'::numeric || ' seconds')::interval
ORDER BY r.flush_lag DESC;
\echo '@@END PG-REPL-014'
\else
\echo '@@SKIP PG-REPL-014 needs PostgreSQL 10 or newer; primary only'
\endif

-- ======== PG-REPL-015  P50  WAL senders or replication slots at capacity ========
SELECT (current_setting('server_version_num')::int >= 90400 AND NOT pg_is_in_recovery()) AS gate_pg_repl_015 \gset
\if :gate_pg_repl_015
\echo '@@CHECK PG-REPL-015'
-- check: PG-REPL-015
-- title: WAL senders or replication slots at capacity
-- priority: 50
-- scope: cluster
-- cost: 0
-- min_version: 9.4
-- run_on: primary
WITH c AS (
  SELECT (SELECT count(*) FROM pg_stat_replication)   AS senders,
         (SELECT setting::int FROM pg_settings WHERE name = 'max_wal_senders')       AS max_senders,
         (SELECT count(*) FROM pg_replication_slots)  AS slots,
         (SELECT setting::int FROM pg_settings WHERE name = 'max_replication_slots') AS max_slots
)
SELECT 'PG-REPL-015'::text AS check_id,
       'cluster'::text     AS scope,
       k.object::text      AS object,
       format('%s of %s %s are in use. The next standby, pg_basebackup, pg_receivewal or logical subscriber to connect is refused; raising the limit requires a restart. Current WAL senders: %s. Current slots: %s.',
              k.used, k.limit_val, k.object,
              coalesce((SELECT string_agg(format('%s (%s)', coalesce(nullif(application_name, ''), 'unnamed'), state), '; ')
                        FROM pg_stat_replication), 'none'),
              coalesce((SELECT string_agg(format('%s (active=%s)', slot_name, active), '; ')
                        FROM pg_replication_slots), 'none')) AS details,
       json_build_object('resource', k.object, 'used', k.used, 'limit', k.limit_val,
                         'senders', c.senders, 'max_wal_senders', c.max_senders,
                         'slots', c.slots, 'max_replication_slots', c.max_slots)::text AS evidence_json,
       'high'::text AS confidence
FROM c
CROSS JOIN LATERAL (VALUES ('WAL senders (max_wal_senders)', c.senders, c.max_senders),
                           ('replication slots (max_replication_slots)', c.slots, c.max_slots))
           AS k(object, used, limit_val)
WHERE NOT pg_is_in_recovery() AND k.limit_val > 0 AND k.used >= k.limit_val;
\echo '@@END PG-REPL-015'
\else
\echo '@@SKIP PG-REPL-015 needs PostgreSQL 9.4 or newer; primary only'
\endif

-- ======== PG-SEC-003  P50  Listening on all interfaces with world-open HBA rules ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_sec_003 \gset
\if :gate_pg_sec_003
\echo '@@CHECK PG-SEC-003'
-- check: PG-SEC-003
-- title: Listening on all interfaces with world-open HBA rules
-- priority: 50
-- scope: cluster
-- cost: 0
-- min_version: 10
-- requires: superuser
SELECT 'PG-SEC-003'::text AS check_id,
       'cluster'::text    AS scope,
       format('pg_hba.conf:%s', r.line_number)::text AS object,
       format('listen_addresses = %s (the server accepts connections on every interface) and pg_hba.conf line %s allows %s from %s for database %s, user %s, with method %s. The database''s own access control therefore places no network restriction at all; whatever limits reachability is outside PostgreSQL - a security group, a firewall, or a private network. db-triage cannot see that from here, so confirm it. ssl = %s, port %s.',
              current_setting('listen_addresses'), r.line_number, r.type,
              coalesce(r.address || coalesce('/' || r.netmask, ''), 'any address'),
              array_to_string(r.database, ','), array_to_string(r.user_name, ','),
              r.auth_method, current_setting('ssl'), current_setting('port')) AS details,
       json_build_object('listen_addresses', current_setting('listen_addresses'),
                         'line_number', r.line_number, 'type', r.type, 'address', r.address,
                         'netmask', r.netmask, 'auth_method', r.auth_method,
                         'database', array_to_string(r.database, ';'),
                         'user_name', array_to_string(r.user_name, ';'),
                         'ssl', current_setting('ssl'), 'port', current_setting('port'))::text AS evidence_json,
       'low'::text AS confidence
FROM pg_hba_file_rules r
WHERE r.error IS NULL
  AND current_setting('listen_addresses') IN ('*', '0.0.0.0', '::', '0.0.0.0,::')
  AND r.type IN ('host', 'hostssl', 'hostnossl', 'hostgssenc', 'hostnogssenc')
  AND (coalesce(r.address, '') IN ('0.0.0.0', '::', 'all', 'samenet')
       OR (r.address = '0.0.0.0' AND r.netmask = '0.0.0.0'))
  AND 'all' = ANY (r.database)
ORDER BY r.line_number;
\echo '@@END PG-SEC-003'
\else
\echo '@@SKIP PG-SEC-003 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-SEC-004  P50  SSL disabled while accepting non-local connections ========
\echo '@@CHECK PG-SEC-004'
-- check: PG-SEC-004
-- title: SSL disabled while accepting non-local connections
-- priority: 50
-- scope: setting
-- cost: 0
SELECT 'PG-SEC-004'::text AS check_id,
       'setting'::text    AS scope,
       'ssl'::text        AS object,
       format('ssl = off while listen_addresses = %s, so the server accepts TCP connections but cannot offer TLS on any of them. Every password exchange (password_encryption = %s), every query and every result crosses the network in clear text. %s client backend(s) are connected from %s distinct non-local address(es) right now. Enabling ssl needs a certificate and key readable by the server account and a reload.',
              current_setting('listen_addresses'), current_setting('password_encryption'),
              (SELECT count(*) FROM pg_stat_activity WHERE backend_type = 'client backend' AND client_addr IS NOT NULL),
              (SELECT count(DISTINCT client_addr) FROM pg_stat_activity WHERE client_addr IS NOT NULL)) AS details,
       json_build_object('ssl', 'off', 'listen_addresses', current_setting('listen_addresses'),
                         'password_encryption', current_setting('password_encryption'),
                         'remote_backends', (SELECT count(*) FROM pg_stat_activity
                                             WHERE backend_type = 'client backend' AND client_addr IS NOT NULL),
                         'distinct_client_addrs', (SELECT count(DISTINCT client_addr) FROM pg_stat_activity
                                                   WHERE client_addr IS NOT NULL))::text AS evidence_json,
       'high'::text AS confidence
WHERE current_setting('ssl') = 'off'
  AND current_setting('listen_addresses') NOT IN ('', 'localhost', '127.0.0.1', '::1', '127.0.0.1,::1');
\echo '@@END PG-SEC-004'

-- ======== PG-SEC-008  P50  Application connections running as superuser ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_sec_008 \gset
\if :gate_pg_sec_008
\echo '@@CHECK PG-SEC-008'
-- check: PG-SEC-008
-- title: Application connections running as superuser
-- priority: 50
-- scope: role
-- cost: 0
-- min_version: 10
-- thresholds: min_connections
WITH conns AS (
  SELECT a.usename, count(*) AS n,
         count(*) FILTER (WHERE a.client_addr IS NOT NULL) AS remote,
         string_agg(DISTINCT coalesce(nullif(a.application_name, ''), 'no application_name'), ', ') AS apps,
         string_agg(DISTINCT coalesce(host(a.client_addr), 'local socket'), ', ') AS addrs
  FROM pg_stat_activity a
  JOIN pg_roles r ON r.rolname = a.usename
  WHERE a.backend_type = 'client backend'
    AND r.rolsuper
    AND coalesce(a.application_name, '') !~* '^(psql|pgAdmin|DBeaver|DataGrip|db-triage|pgcli|TablePlus|Postico)'
  GROUP BY a.usename
)
SELECT 'PG-SEC-008'::text AS check_id,
       'role'::text       AS scope,
       c.usename::text    AS object,
       format('Superuser role %s has %s concurrent connection(s), %s of them from a non-local address (%s), with application names: %s. A superuser bypasses every permission check, every row-level security policy and every event trigger, and can read and write files as the server account. An application connecting this way turns any SQL-injection bug into host compromise. Thresholds: %s concurrent connections, or any remote connection.',
              c.usename, c.n, c.remote, c.addrs, c.apps, :'pg_sec_008_min_connections'::text) AS details,
       json_build_object('role', c.usename, 'connections', c.n, 'remote_connections', c.remote,
                         'application_names', c.apps, 'client_addrs', c.addrs,
                         'threshold_connections', :'pg_sec_008_min_connections'::int,
                         'sampled_at', now())::text AS evidence_json,
       'medium'::text AS confidence
FROM conns c
WHERE c.n >= :'pg_sec_008_min_connections'::int OR c.remote > 0
ORDER BY c.n DESC;
\echo '@@END PG-SEC-008'
\else
\echo '@@SKIP PG-SEC-008 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-VAC-002  P50  Autovacuum workers saturated ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_vac_002 \gset
\if :gate_pg_vac_002
\echo '@@CHECK PG-VAC-002'
-- check: PG-VAC-002
-- title: Autovacuum workers saturated
-- priority: 50
-- scope: cluster
-- cost: 1
-- min_version: 10
-- thresholds: overdue_tables
WITH workers AS (
  SELECT count(*) AS running FROM pg_stat_activity WHERE backend_type = 'autovacuum worker'
),
overdue AS (
  SELECT count(*) AS n
  FROM pg_stat_user_tables t
  JOIN pg_class c ON c.oid = t.relid
  WHERE t.n_dead_tup > current_setting('autovacuum_vacuum_threshold')::numeric
                     + current_setting('autovacuum_vacuum_scale_factor')::numeric * greatest(t.n_live_tup, 0)
),
maxw AS (SELECT current_setting('autovacuum_max_workers')::int AS m)
SELECT 'PG-VAC-002'::text AS check_id,
       'cluster'::text    AS scope,
       NULL::text         AS object,
       format('All %s autovacuum workers are busy and %s tables in database %s already exceed their vacuum threshold (threshold %s tables). New work queues behind the running workers, so tables fall further behind. autovacuum_naptime = %s, autovacuum_vacuum_cost_delay = %s.',
              maxw.m, overdue.n, current_database(),
              :'pg_vac_002_overdue_tables'::int,
              current_setting('autovacuum_naptime'),
              current_setting('autovacuum_vacuum_cost_delay')) AS details,
       json_build_object('workers_running', workers.running, 'autovacuum_max_workers', maxw.m,
                         'overdue_tables', overdue.n, 'threshold_tables', :'pg_vac_002_overdue_tables'::int,
                         'autovacuum_naptime', current_setting('autovacuum_naptime'),
                         'database', current_database())::text AS evidence_json,
       'medium'::text AS confidence
FROM workers, overdue, maxw
WHERE workers.running >= maxw.m AND maxw.m > 0
  AND overdue.n >= :'pg_vac_002_overdue_tables'::int;
\echo '@@END PG-VAC-002'
\else
\echo '@@SKIP PG-VAC-002 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-VAC-005  P50  Old transaction horizon holding back vacuum ========
SELECT (current_setting('server_version_num')::int >= 90600) AS gate_pg_vac_005 \gset
\if :gate_pg_vac_005
\echo '@@CHECK PG-VAC-005'
-- check: PG-VAC-005
-- title: Old transaction horizon holding back vacuum
-- priority: 50
-- scope: cluster
-- cost: 0
-- min_version: 9.6
-- thresholds: xmin_age
WITH horizons AS (
  SELECT 'backend'::text AS source_kind,
         format('pid %s (%s / %s, state %s, xact_start %s)', a.pid,
                coalesce(nullif(a.usename, ''), '?'), coalesce(nullif(a.application_name, ''), 'no application_name'),
                coalesce(a.state, '?'), coalesce(a.xact_start::text, 'none')) AS source_name,
         age(a.backend_xmin) AS xmin_age,
         extract(epoch FROM now() - a.xact_start)::bigint AS age_seconds
  FROM pg_stat_activity a WHERE a.backend_xmin IS NOT NULL AND a.pid <> pg_backend_pid()
  UNION ALL
  SELECT 'replication slot', format('slot %s (%s, %s, active=%s)', s.slot_name, s.slot_type,
                                    coalesce(s.plugin, 'physical'), s.active),
         greatest(age(s.xmin), age(s.catalog_xmin)), NULL
  FROM pg_replication_slots s WHERE s.xmin IS NOT NULL OR s.catalog_xmin IS NOT NULL
  UNION ALL
  SELECT 'prepared transaction', format('gid %s (owner %s, prepared %s)', p.gid, p.owner, p.prepared),
         age(p.transaction), extract(epoch FROM now() - p.prepared)::bigint
  FROM pg_prepared_xacts p
  UNION ALL
  SELECT 'standby feedback', format('standby %s from %s (%s)', coalesce(nullif(r.application_name, ''), '?'),
                                    coalesce(host(r.client_addr), 'local'), r.state),
         age(r.backend_xmin), NULL
  FROM pg_stat_replication r WHERE r.backend_xmin IS NOT NULL
)
SELECT 'PG-VAC-005'::text AS check_id,
       'cluster'::text    AS scope,
       NULL::text         AS object,
       format('Oldest xmin horizon is %s XIDs old (threshold %s), held by %s: %s.%s Vacuum cannot remove any row version newer than that horizon anywhere in the cluster, in any database, so dead tuples accumulate and freezing stalls.',
              to_char(h.xmin_age, 'FM999,999,999,999'),
              to_char(:'pg_vac_005_xmin_age'::bigint, 'FM999,999,999,999'),
              h.source_kind, h.source_name,
              CASE WHEN h.age_seconds IS NOT NULL
                   THEN ' It has been open for ' || justify_interval(date_trunc('second', make_interval(secs => h.age_seconds))) || '.'
                   ELSE '' END) AS details,
       json_build_object('source_kind', h.source_kind, 'source', h.source_name,
                         'xmin_age', h.xmin_age, 'threshold', :'pg_vac_005_xmin_age'::bigint,
                         'open_seconds', h.age_seconds,
                         'autovacuum_freeze_max_age', current_setting('autovacuum_freeze_max_age')::bigint)::text AS evidence_json,
       'high'::text AS confidence
FROM horizons h
WHERE h.xmin_age >= :'pg_vac_005_xmin_age'::bigint
ORDER BY h.xmin_age DESC
LIMIT 5;
\echo '@@END PG-VAC-005'
\else
\echo '@@SKIP PG-VAC-005 needs PostgreSQL 9.6 or newer'
\endif

-- ======== PG-WAL-001  P50  Checkpoints mostly requested (max_wal_size too small) ========
SELECT (NOT pg_is_in_recovery()) AS gate_pg_wal_001 \gset
\if :gate_pg_wal_001
\echo '@@CHECK PG-WAL-001'
-- check: PG-WAL-001
-- title: Checkpoints mostly requested (max_wal_size too small)
-- priority: 50
-- scope: cluster
-- cost: 0
-- run_on: primary
-- thresholds: min_checkpoints, requested_ratio
-- PostgreSQL 17 moved the checkpoint counters from pg_stat_bgwriter to
-- pg_stat_checkpointer and renamed them; both shapes are handled below.
\set ON_ERROR_STOP off
SELECT (current_setting('server_version_num')::int >= 170000) AS pg_wal_001_pg17 \gset
WITH c AS (
\if :pg_wal_001_pg17
  SELECT num_timed AS timed, num_requested AS requested, stats_reset FROM pg_stat_checkpointer
\else
  SELECT checkpoints_timed AS timed, checkpoints_req AS requested, stats_reset FROM pg_stat_bgwriter
\endif
)
SELECT 'PG-WAL-001'::text AS check_id,
       'cluster'::text    AS scope,
       'max_wal_size'::text AS object,
       format('%s of %s checkpoints since %s were requested rather than timed (%s%%, threshold %s%%). A requested checkpoint means WAL hit max_wal_size (%s) before checkpoint_timeout (%s) elapsed, so checkpoints are driven by write volume instead of by the clock. Each one restarts full-page-image logging, so WAL volume and I/O both rise. Raising max_wal_size costs disk in pg_wal and nothing else.',
              to_char(c.requested, 'FM999,999,999'), to_char(c.timed + c.requested, 'FM999,999,999'),
              coalesce(c.stats_reset::text, 'the last statistics reset'),
              round(100.0 * c.requested / nullif(c.timed + c.requested, 0), 1)::text,
              round(100 * :'pg_wal_001_requested_ratio'::numeric)::text,
              current_setting('max_wal_size'),
              current_setting('checkpoint_timeout')) AS details,
       json_build_object('checkpoints_timed', c.timed, 'checkpoints_requested', c.requested,
                         'requested_ratio', round(c.requested::numeric / nullif(c.timed + c.requested, 0), 4),
                         'threshold_ratio', :'pg_wal_001_requested_ratio'::numeric,
                         'stats_reset', c.stats_reset,
                         'max_wal_size', current_setting('max_wal_size'),
                         'checkpoint_timeout', current_setting('checkpoint_timeout'))::text AS evidence_json,
       'medium'::text AS confidence
FROM c
WHERE NOT pg_is_in_recovery()
  AND c.timed + c.requested >= :'pg_wal_001_min_checkpoints'::int
  AND c.requested::numeric / nullif(c.timed + c.requested, 0) >= :'pg_wal_001_requested_ratio'::numeric;
\echo '@@END PG-WAL-001'
\else
\echo '@@SKIP PG-WAL-001 primary only'
\endif

-- ======== PG-WAL-006  P50  pg_wal directory unusually large ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_wal_006 \gset
\if :gate_pg_wal_006
\echo '@@CHECK PG-WAL-006'
-- check: PG-WAL-006
-- title: pg_wal directory unusually large
-- priority: 50
-- scope: cluster
-- cost: 1
-- min_version: 10
-- thresholds: waldir_multiple, waldir_floor_bytes
WITH w AS (
  SELECT sum(size)::bigint AS wal_bytes, count(*) AS segments FROM pg_ls_waldir()
),
lim AS (
  SELECT greatest(:'pg_wal_006_waldir_multiple'::numeric
                    * (SELECT setting::bigint FROM pg_settings WHERE name = 'max_wal_size') * 1048576,
                  :'pg_wal_006_waldir_floor_bytes'::bigint) AS threshold
)
SELECT 'PG-WAL-006'::text AS check_id,
       'cluster'::text    AS scope,
       'pg_wal'::text     AS object,
       format('pg_wal holds %s across %s files, above the threshold of %s (the larger of %sx max_wal_size = %s and the floor %s). This is a symptom, not a cause. Look for: archiving failing or stalled (PG-BAK-002/003), a replication slot pinning WAL (PG-REPL-002/003/004 - %s slot(s) exist, %s inactive), or wal_keep_size = %s. If pg_wal shares a volume with the data directory, PG-CAP-001/002 matter more than this row does.',
              pg_size_pretty(w.wal_bytes), w.segments, pg_size_pretty(lim.threshold::bigint),
              :'pg_wal_006_waldir_multiple'::text,
              pg_size_pretty(((SELECT setting::bigint FROM pg_settings WHERE name = 'max_wal_size') * 1048576)::bigint),
              pg_size_pretty(:'pg_wal_006_waldir_floor_bytes'::bigint),
              (SELECT count(*) FROM pg_replication_slots),
              (SELECT count(*) FROM pg_replication_slots WHERE NOT active),
              current_setting('wal_keep_size')) AS details,
       json_build_object('wal_bytes', w.wal_bytes, 'wal_segments', w.segments,
                         'threshold_bytes', lim.threshold::bigint,
                         'max_wal_size', current_setting('max_wal_size'),
                         'wal_keep_size', current_setting('wal_keep_size'),
                         'slot_count', (SELECT count(*) FROM pg_replication_slots),
                         'inactive_slots', (SELECT count(*) FROM pg_replication_slots WHERE NOT active),
                         'archive_mode', current_setting('archive_mode'),
                         'archiver_failed_count', (SELECT failed_count FROM pg_stat_archiver))::text AS evidence_json,
       'high'::text AS confidence
FROM w CROSS JOIN lim
WHERE w.wal_bytes >= lim.threshold;
\echo '@@END PG-WAL-006'
\else
\echo '@@SKIP PG-WAL-006 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-WRAP-003  P50  Anti-wraparound vacuum overdue ========
\echo '@@CHECK PG-WRAP-003'
-- check: PG-WRAP-003
-- title: Anti-wraparound vacuum overdue
-- priority: 50
-- scope: database
-- cost: 0
-- thresholds: freeze_multiple, xid_age_ceiling
WITH s AS (
  SELECT current_setting('autovacuum_freeze_max_age')::bigint            AS fma,
         current_setting('autovacuum_multixact_freeze_max_age')::bigint  AS mfma
)
SELECT 'PG-WRAP-003'::text AS check_id,
       'database'::text    AS scope,
       d.datname::text     AS object,
       format('age(datfrozenxid) = %s vs autovacuum_freeze_max_age %s (%sx); mxid_age = %s vs autovacuum_multixact_freeze_max_age %s (%sx). The forced anti-wraparound vacuum should have started at 1.0x, so something is preventing tuples from being frozen: check PG-VAC-005 (old xmin horizon), PG-LOCK-005/006 (long or prepared transactions) and PG-REPL-002/003 (slots).',
              to_char(age(d.datfrozenxid), 'FM999,999,999,999'), to_char(s.fma, 'FM999,999,999,999'),
              round(age(d.datfrozenxid)::numeric / nullif(s.fma, 0), 2)::text,
              to_char(mxid_age(d.datminmxid), 'FM999,999,999,999'), to_char(s.mfma, 'FM999,999,999,999'),
              round(mxid_age(d.datminmxid)::numeric / nullif(s.mfma, 0), 2)::text) AS details,
       json_build_object(
              'xid_age', age(d.datfrozenxid),
              'mxid_age', mxid_age(d.datminmxid),
              'autovacuum_freeze_max_age', s.fma,
              'autovacuum_multixact_freeze_max_age', s.mfma,
              'xid_multiple', round(age(d.datfrozenxid)::numeric / nullif(s.fma, 0), 3),
              'mxid_multiple', round(mxid_age(d.datminmxid)::numeric / nullif(s.mfma, 0), 3),
              'threshold_multiple', :'pg_wrap_003_freeze_multiple'::numeric)::text AS evidence_json,
       'high'::text AS confidence
FROM pg_database d CROSS JOIN s
WHERE greatest(age(d.datfrozenxid), mxid_age(d.datminmxid)) < :'pg_wrap_003_xid_age_ceiling'::bigint
  AND (age(d.datfrozenxid)     > :'pg_wrap_003_freeze_multiple'::numeric * s.fma
    OR mxid_age(d.datminmxid)  > :'pg_wrap_003_freeze_multiple'::numeric * s.mfma)
ORDER BY greatest(age(d.datfrozenxid), mxid_age(d.datminmxid)) DESC;
\echo '@@END PG-WRAP-003'

-- ======== PG-BAK-011  P100  Base backup running for more than 2 hours ========
SELECT (current_setting('server_version_num')::int >= 130000 AND NOT pg_is_in_recovery()) AS gate_pg_bak_011 \gset
\if :gate_pg_bak_011
\echo '@@CHECK PG-BAK-011'
-- check: PG-BAK-011
-- title: Base backup running for more than 2 hours
-- priority: 100
-- scope: cluster
-- cost: 0
-- min_version: 13
-- run_on: primary
-- thresholds: duration_seconds
SELECT 'PG-BAK-011'::text AS check_id,
       'cluster'::text    AS scope,
       ('pid:' || b.pid)::text AS object,
       format('A base backup started by pid %s has been running for %s (threshold %s). Phase "%s", %s of %s streamed (%s%%), %s of %s tablespaces done. It holds a WAL retention obligation for its whole duration, so pg_wal will not shrink until it finishes.',
              b.pid,
              justify_interval(date_trunc('second', now() - a.backend_start)),
              (:'pg_bak_011_duration_seconds'::int || ' seconds')::interval,
              b.phase,
              pg_size_pretty(b.backup_streamed),
              CASE WHEN b.backup_total > 0 THEN pg_size_pretty(b.backup_total) ELSE 'unknown total' END,
              CASE WHEN b.backup_total > 0
                   THEN round(100.0 * b.backup_streamed / b.backup_total, 1)::text ELSE '?' END,
              b.tablespaces_streamed, b.tablespaces_total) AS details,
       json_build_object('pid', b.pid, 'phase', b.phase,
                         'backup_streamed', b.backup_streamed, 'backup_total', b.backup_total,
                         'tablespaces_streamed', b.tablespaces_streamed, 'tablespaces_total', b.tablespaces_total,
                         'duration_seconds', round(extract(epoch FROM now() - a.backend_start))::bigint,
                         'threshold_seconds', :'pg_bak_011_duration_seconds'::int)::text AS evidence_json,
       'high'::text AS confidence
FROM pg_stat_progress_basebackup b
JOIN pg_stat_activity a ON a.pid = b.pid
WHERE now() - a.backend_start >= (:'pg_bak_011_duration_seconds'::int || ' seconds')::interval;
\echo '@@END PG-BAK-011'
\else
\echo '@@SKIP PG-BAK-011 needs PostgreSQL 13 or newer; primary only'
\endif

-- ======== PG-CAP-008  P100  Temp-file volume high ========
\echo '@@CHECK PG-CAP-008'
-- check: PG-CAP-008
-- title: Temp-file volume high
-- priority: 100
-- scope: database
-- cost: 0
-- thresholds: temp_bytes_per_day
WITH w AS (
  SELECT d.datname, d.temp_bytes, d.temp_files, d.stats_reset,
         greatest(extract(epoch FROM now() - coalesce(d.stats_reset, pg_postmaster_start_time())) / 86400.0, 0.01) AS days
  FROM pg_stat_database d WHERE d.datname IS NOT NULL
)
SELECT 'PG-CAP-008'::text AS check_id,
       'database'::text   AS scope,
       w.datname::text    AS object,
       format('Database %s wrote %s of temporary files in %s files over %s days: %s per day (threshold %s per day), average %s per file. Counted since %s. Every one of those bytes was written to and read back from the data volume by a sort, hash or materialise that did not fit in work_mem (%s) - it is both I/O the queries did not need and disk that could fill the volume, since temp_file_limit is %s (PG-MEM-009). PG-MEM-004 covers the setting, PG-QRY-009 names the statements.',
              w.datname, pg_size_pretty(w.temp_bytes),
              to_char(w.temp_files, 'FM999,999,999,999'), round(w.days, 1)::text,
              pg_size_pretty((w.temp_bytes / w.days)::bigint),
              pg_size_pretty(:'pg_cap_008_temp_bytes_per_day'::bigint),
              pg_size_pretty((w.temp_bytes / greatest(w.temp_files, 1))::bigint),
              coalesce(w.stats_reset::text, 'the last statistics reset'),
              current_setting('work_mem'), current_setting('temp_file_limit')) AS details,
       json_build_object('datname', w.datname, 'temp_bytes', w.temp_bytes, 'temp_files', w.temp_files,
                         'window_days', round(w.days, 2),
                         'temp_bytes_per_day', (w.temp_bytes / w.days)::bigint,
                         'threshold_bytes_per_day', :'pg_cap_008_temp_bytes_per_day'::bigint,
                         'avg_temp_file_bytes', (w.temp_bytes / greatest(w.temp_files, 1))::bigint,
                         'work_mem', current_setting('work_mem'),
                         'temp_file_limit', current_setting('temp_file_limit'),
                         'stats_reset', w.stats_reset)::text AS evidence_json,
       'medium'::text AS confidence
FROM w
WHERE w.temp_bytes / w.days >= :'pg_cap_008_temp_bytes_per_day'::bigint
ORDER BY w.temp_bytes DESC;
\echo '@@END PG-CAP-008'

-- ======== PG-CONN-004  P100  Most connections idle ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_conn_004 \gset
\if :gate_pg_conn_004
\echo '@@CHECK PG-CONN-004'
-- check: PG-CONN-004
-- title: Most connections idle
-- priority: 100
-- scope: cluster
-- cost: 0
-- min_version: 10
-- thresholds: min_connections, idle_fraction
WITH c AS (
  SELECT count(*) FILTER (WHERE backend_type = 'client backend')                      AS clients,
         count(*) FILTER (WHERE backend_type = 'client backend' AND state = 'idle')   AS idle,
         count(*) FILTER (WHERE backend_type = 'client backend' AND state = 'active') AS active,
         max(now() - backend_start) FILTER (WHERE backend_type = 'client backend')    AS oldest
  FROM pg_stat_activity
)
SELECT 'PG-CONN-004'::text AS check_id,
       'cluster'::text     AS scope,
       NULL::text          AS object,
       format('%s of %s client connections are idle (%s%%, threshold %s%%) at snapshot time; %s are active. Oldest connection opened %s ago. Idle backends still hold their process, their catalog caches and their share of the proc array, and they still have to be examined by every snapshot; on a server with a large max_connections that is a fixed tax for connections nobody is using. Usually an application-side pool sized for peak that never shrinks.',
              c.idle, c.clients,
              round(100.0 * c.idle / nullif(c.clients, 0), 1)::text,
              round(100 * :'pg_conn_004_idle_fraction'::numeric)::text,
              c.active, justify_interval(c.oldest)) AS details,
       json_build_object('client_backends', c.clients, 'idle', c.idle, 'active', c.active,
                         'idle_fraction', round(c.idle::numeric / nullif(c.clients, 0), 4),
                         'threshold_fraction', :'pg_conn_004_idle_fraction'::numeric,
                         'threshold_min_connections', :'pg_conn_004_min_connections'::int,
                         'oldest_connection_seconds', round(extract(epoch FROM c.oldest))::bigint,
                         'max_connections', (SELECT setting::int FROM pg_settings WHERE name = 'max_connections'))::text AS evidence_json,
       'high'::text AS confidence
FROM c
WHERE c.clients >= :'pg_conn_004_min_connections'::int
  AND c.idle::numeric / nullif(c.clients, 0) >= :'pg_conn_004_idle_fraction'::numeric;
\echo '@@END PG-CONN-004'
\else
\echo '@@SKIP PG-CONN-004 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-CONN-005  P100  High connection churn ========
SELECT (current_setting('server_version_num')::int >= 140000) AS gate_pg_conn_005 \gset
\if :gate_pg_conn_005
\echo '@@CHECK PG-CONN-005'
-- check: PG-CONN-005
-- title: High connection churn
-- priority: 100
-- scope: cluster
-- cost: 0
-- min_version: 14
-- thresholds: sessions_per_second
WITH w AS (
  SELECT sum(sessions)::numeric AS sessions,
         greatest(extract(epoch FROM now() - coalesce(min(stats_reset), pg_postmaster_start_time())), 60) AS secs,
         min(stats_reset) AS stats_reset
  FROM pg_stat_database WHERE datname IS NOT NULL
)
SELECT 'PG-CONN-005'::text AS check_id,
       'cluster'::text     AS scope,
       NULL::text          AS object,
       format('%s sessions were established in %s: %s per second (threshold %s per second), counted from pg_stat_database since %s. PostgreSQL forks a process and builds fresh catalog caches for every connection, so at this rate a measurable share of the server''s CPU is spent on connection setup rather than on queries, and each connection pays that cost in its own latency. A transaction-mode or session-mode pooler removes it. Currently %s client backends are connected.',
              to_char(w.sessions, 'FM999,999,999,999'),
              justify_interval(date_trunc('second', make_interval(secs => w.secs))),
              round(w.sessions / w.secs, 1)::text,
              :'pg_conn_005_sessions_per_second'::text,
              coalesce(w.stats_reset::text, 'the last statistics reset'),
              (SELECT count(*) FROM pg_stat_activity WHERE backend_type = 'client backend')) AS details,
       json_build_object('sessions', w.sessions::bigint, 'window_seconds', round(w.secs)::bigint,
                         'sessions_per_second', round(w.sessions / w.secs, 3),
                         'threshold_per_second', :'pg_conn_005_sessions_per_second'::numeric,
                         'stats_reset', w.stats_reset,
                         'current_client_backends', (SELECT count(*) FROM pg_stat_activity WHERE backend_type = 'client backend'))::text AS evidence_json,
       'medium'::text AS confidence
FROM w
WHERE w.sessions / w.secs >= :'pg_conn_005_sessions_per_second'::numeric;
\echo '@@END PG-CONN-005'
\else
\echo '@@SKIP PG-CONN-005 needs PostgreSQL 14 or newer'
\endif

-- ======== PG-CONN-006  P100  Sessions ending abnormally ========
SELECT (current_setting('server_version_num')::int >= 140000) AS gate_pg_conn_006 \gset
\if :gate_pg_conn_006
\echo '@@CHECK PG-CONN-006'
-- check: PG-CONN-006
-- title: Sessions ending abnormally
-- priority: 100
-- scope: database
-- cost: 0
-- min_version: 14
-- thresholds: abnormal_fraction, min_sessions
SELECT 'PG-CONN-006'::text AS check_id,
       'database'::text    AS scope,
       d.datname::text     AS object,
       format('%s of %s sessions in database %s ended abnormally (%s%%, threshold %s%%) since %s: %s fatal errors, %s killed by an administrator, %s abandoned by the client without a clean disconnect. Abandoned sessions usually mean a network device or a container runtime cutting idle connections; fatal ones mean the server refused or terminated them. Each one is an error the application had to handle, or did not.',
              to_char(d.sessions_fatal + d.sessions_killed + d.sessions_abandoned, 'FM999,999,999,999'),
              to_char(d.sessions, 'FM999,999,999,999'), d.datname,
              round(100.0 * (d.sessions_fatal + d.sessions_killed + d.sessions_abandoned) / nullif(d.sessions, 0), 2)::text,
              round(100 * :'pg_conn_006_abnormal_fraction'::numeric, 2)::text,
              coalesce(d.stats_reset::text, 'the last statistics reset'),
              d.sessions_fatal, d.sessions_killed, d.sessions_abandoned) AS details,
       json_build_object('datname', d.datname, 'sessions', d.sessions,
                         'sessions_fatal', d.sessions_fatal, 'sessions_killed', d.sessions_killed,
                         'sessions_abandoned', d.sessions_abandoned,
                         'abnormal_fraction', round((d.sessions_fatal + d.sessions_killed + d.sessions_abandoned)::numeric
                                                    / nullif(d.sessions, 0), 4),
                         'threshold_fraction', :'pg_conn_006_abnormal_fraction'::numeric,
                         'stats_reset', d.stats_reset)::text AS evidence_json,
       'medium'::text AS confidence
FROM pg_stat_database d
WHERE d.datname IS NOT NULL
  AND d.sessions >= :'pg_conn_006_min_sessions'::bigint
  AND (d.sessions_fatal + d.sessions_killed + d.sessions_abandoned)::numeric / nullif(d.sessions, 0)
      >= :'pg_conn_006_abnormal_fraction'::numeric
ORDER BY (d.sessions_fatal + d.sessions_killed + d.sessions_abandoned) DESC;
\echo '@@END PG-CONN-006'
\else
\echo '@@SKIP PG-CONN-006 needs PostgreSQL 14 or newer'
\endif

-- ======== PG-CORR-007  P100  No integrity-verification tooling installed (amcheck) ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_corr_007 \gset
\if :gate_pg_corr_007
\echo '@@CHECK PG-CORR-007'
-- check: PG-CORR-007
-- title: No integrity-verification tooling installed (amcheck)
-- priority: 100
-- scope: database
-- cost: 0
-- min_version: 10
SELECT 'PG-CORR-007'::text  AS check_id,
       'database'::text     AS scope,
       current_database()::text AS object,
       format('amcheck is available on this server (version %s) but is not installed in database %s. Nothing here can verify that a B-tree index still agrees with its heap; a collation change (PG-CORR-006), a storage fault, or a bad restore is discovered by a user getting wrong answers. data_checksums = %s. This database holds %s across %s indexes.',
              a.default_version, current_database(), current_setting('data_checksums'),
              pg_size_pretty(pg_database_size(current_database())),
              (SELECT count(*) FROM pg_index)) AS details,
       json_build_object('amcheck_available_version', a.default_version,
                         'amcheck_installed', false,
                         'data_checksums', current_setting('data_checksums'),
                         'database_bytes', pg_database_size(current_database()),
                         'index_count', (SELECT count(*) FROM pg_index))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_available_extensions a
WHERE a.name = 'amcheck'
  AND NOT EXISTS (SELECT 1 FROM pg_extension e WHERE e.extname = 'amcheck');
\echo '@@END PG-CORR-007'
\else
\echo '@@SKIP PG-CORR-007 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-DUR-004  P100  synchronous_commit weaker than the synchronous-standby expectation ========
SELECT (current_setting('server_version_num')::int >= 90600 AND NOT pg_is_in_recovery()) AS gate_pg_dur_004 \gset
\if :gate_pg_dur_004
\echo '@@CHECK PG-DUR-004'
-- check: PG-DUR-004
-- title: synchronous_commit weaker than the synchronous-standby expectation
-- priority: 100
-- scope: setting
-- cost: 0
-- min_version: 9.6
-- run_on: primary
SELECT 'PG-DUR-004'::text         AS check_id,
       'setting'::text            AS scope,
       'synchronous_commit'::text AS object,
       format('Standby %s is in sync_state = %s while synchronous_commit = %s. At that level the primary waits only for the standby to %s, not to flush WAL to its own durable storage, so a crash of the standby host can lose transactions the primary already reported as safely replicated. synchronous_standby_names = %s.',
              coalesce(nullif(r.application_name, ''), 'unnamed'), r.sync_state, s.setting,
              CASE s.setting WHEN 'remote_write' THEN 'receive the WAL into its operating-system cache'
                             WHEN 'local' THEN 'nothing at all: only the primary flush is awaited'
                             ELSE s.setting END,
              coalesce(nullif(current_setting('synchronous_standby_names'), ''), '(empty)')) AS details,
       json_build_object('synchronous_commit', s.setting, 'source', s.source,
                         'standby', r.application_name, 'sync_state', r.sync_state,
                         'synchronous_standby_names', current_setting('synchronous_standby_names'),
                         'flush_lsn', r.flush_lsn::text, 'write_lsn', r.write_lsn::text)::text AS evidence_json,
       'high'::text AS confidence
FROM pg_settings s
JOIN pg_stat_replication r ON r.sync_state IN ('sync', 'quorum')
WHERE s.name = 'synchronous_commit' AND s.setting IN ('local', 'remote_write');
\echo '@@END PG-DUR-004'
\else
\echo '@@SKIP PG-DUR-004 needs PostgreSQL 9.6 or newer; primary only'
\endif

-- ======== PG-LOCK-007  P100  idle_in_transaction_session_timeout disabled ========
SELECT (current_setting('server_version_num')::int >= 90600) AS gate_pg_lock_007 \gset
\if :gate_pg_lock_007
\echo '@@CHECK PG-LOCK-007'
-- check: PG-LOCK-007
-- title: idle_in_transaction_session_timeout disabled
-- priority: 100
-- scope: setting
-- cost: 0
-- min_version: 9.6
SELECT 'PG-LOCK-007'::text                        AS check_id,
       'setting'::text                            AS scope,
       'idle_in_transaction_session_timeout'::text AS object,
       format('idle_in_transaction_session_timeout = 0 at server level with no role or database override for it. Nothing stops a client that opened a transaction and then went away - a paused debugger, a crashed worker, a connection a firewall silently dropped - from holding its locks and the cluster''s xmin horizon indefinitely (PG-LOCK-003, PG-VAC-005). %s session(s) are in an idle-in-transaction state right now, the oldest for %s. 5 to 15 minutes for application roles is a common setting; leave interactive and migration roles alone.',
              (SELECT count(*) FROM pg_stat_activity WHERE state LIKE 'idle in transaction%'),
              coalesce((SELECT justify_interval(max(now() - state_change))::text FROM pg_stat_activity
                        WHERE state LIKE 'idle in transaction%'), 'n/a')) AS details,
       json_build_object('idle_in_transaction_session_timeout', '0',
                         'current_idle_in_transaction', (SELECT count(*) FROM pg_stat_activity WHERE state LIKE 'idle in transaction%'),
                         'db_role_overrides', (SELECT count(*) FROM pg_db_role_setting r
                                               WHERE array_to_string(r.setconfig, ' ') LIKE '%idle_in_transaction_session_timeout%'),
                         'statement_timeout', current_setting('statement_timeout'))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_settings s
WHERE s.name = 'idle_in_transaction_session_timeout' AND s.reset_val = '0'
  AND NOT EXISTS (SELECT 1 FROM pg_db_role_setting r
                  WHERE array_to_string(r.setconfig, ' ') LIKE '%idle_in_transaction_session_timeout%');
\echo '@@END PG-LOCK-007'
\else
\echo '@@SKIP PG-LOCK-007 needs PostgreSQL 9.6 or newer'
\endif

-- ======== PG-LOCK-010  P100  Active query running more than 10 minutes ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_lock_010 \gset
\if :gate_pg_lock_010
\echo '@@CHECK PG-LOCK-010'
-- check: PG-LOCK-010
-- title: Active query running more than 10 minutes
-- priority: 100
-- scope: session
-- cost: 0
-- min_version: 10
-- thresholds: query_seconds
SELECT 'PG-LOCK-010'::text AS check_id,
       'session'::text     AS scope,
       ('pid:' || a.pid)::text AS object,
       format('pid %s (%s / %s, from %s, database %s) has been running one statement for %s (threshold %s). Wait state: %s. Transaction open for %s, xmin age %s. Maintenance statements and backup application names are excluded, so this is either analytics that legitimately takes this long or a query that has found a bad plan. Statement: %s',
              a.pid, coalesce(nullif(a.usename, ''), '?'),
              coalesce(nullif(a.application_name, ''), 'no application_name'),
              coalesce(host(a.client_addr), 'local socket'), coalesce(a.datname, '?'),
              justify_interval(date_trunc('second', now() - a.query_start)),
              (:'pg_lock_010_query_seconds'::int || ' seconds')::interval,
              coalesce(a.wait_event_type || '/' || a.wait_event, 'running on CPU'),
              coalesce(justify_interval(date_trunc('second', now() - a.xact_start))::text, 'n/a'),
              coalesce(age(a.backend_xmin)::text, 'not set'),
              left(regexp_replace(coalesce(a.query, ''), '\s+', ' ', 'g'), 200)) AS details,
       json_build_object('pid', a.pid, 'usename', a.usename, 'application_name', a.application_name,
                         'datname', a.datname, 'client_addr', host(a.client_addr),
                         'query_seconds', round(extract(epoch FROM now() - a.query_start))::bigint,
                         'threshold_seconds', :'pg_lock_010_query_seconds'::int,
                         'wait_event_type', a.wait_event_type, 'wait_event', a.wait_event,
                         'backend_xmin_age', CASE WHEN a.backend_xmin IS NULL THEN NULL ELSE age(a.backend_xmin) END,
                         'sampled_at', now())::text AS evidence_json,
       'medium'::text AS confidence
FROM pg_stat_activity a
WHERE a.backend_type = 'client backend' AND a.state = 'active'
  AND a.query_start IS NOT NULL
  AND now() - a.query_start >= (:'pg_lock_010_query_seconds'::int || ' seconds')::interval
  AND coalesce(a.query, '') !~* '^\s*(VACUUM|ANALYZE|CREATE\s+(UNIQUE\s+)?INDEX|REINDEX|CLUSTER|COPY)'
  AND coalesce(a.application_name, '') !~* '(basebackup|pg_dump|pg_restore|walreceiver|db-triage)'
ORDER BY a.query_start;
\echo '@@END PG-LOCK-010'
\else
\echo '@@SKIP PG-LOCK-010 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-MEM-002  P100  shared_buffers above 40 percent of RAM ========
\echo '@@CHECK PG-MEM-002'
-- check: PG-MEM-002
-- title: shared_buffers above 40 percent of RAM
-- priority: 100
-- scope: setting
-- cost: 0
-- thresholds: ram_fraction, ram_bytes
-- Requires RAM: pass -v pg_mem_002_ram_bytes=<bytes> (bin/db-triage supplies it
-- from the host helper or from baseline.ram_gb). With RAM unknown (0) the check
-- emits nothing and the runner records it skipped with reason no-input.
SELECT 'PG-MEM-002'::text     AS check_id,
       'setting'::text        AS scope,
       'shared_buffers'::text AS object,
       format('shared_buffers = %s, which is %s%% of the %s of RAM reported for this host (threshold %s%%). Past roughly 40%% the buffer cache mostly duplicates pages the operating-system cache already holds, while leaving less room for work_mem allocations and for the page cache that backs sequential reads; checkpoints also have more dirty pages to write. effective_cache_size = %s.',
              pg_size_pretty(s.bytes::bigint),
              round(100.0 * s.bytes / :'pg_mem_002_ram_bytes'::numeric, 1)::text,
              pg_size_pretty(:'pg_mem_002_ram_bytes'::bigint),
              round(100 * :'pg_mem_002_ram_fraction'::numeric)::text,
              current_setting('effective_cache_size')) AS details,
       json_build_object('shared_buffers_bytes', s.bytes::bigint,
                         'ram_bytes', :'pg_mem_002_ram_bytes'::bigint,
                         'fraction_of_ram', round(s.bytes / :'pg_mem_002_ram_bytes'::numeric, 4),
                         'threshold_fraction', :'pg_mem_002_ram_fraction'::numeric,
                         'source', s.source)::text AS evidence_json,
       'high'::text AS confidence
FROM (SELECT setting::numeric * 8192 AS bytes, source FROM pg_settings WHERE name = 'shared_buffers') s
WHERE :'pg_mem_002_ram_bytes'::bigint > 0
  AND s.bytes > :'pg_mem_002_ram_fraction'::numeric * :'pg_mem_002_ram_bytes'::bigint;
\echo '@@END PG-MEM-002'

-- ======== PG-MEM-004  P100  work_mem at the default with heavy temp-file spill ========
\echo '@@CHECK PG-MEM-004'
-- check: PG-MEM-004
-- title: work_mem at the default with heavy temp-file spill
-- priority: 100
-- scope: setting
-- cost: 0
-- thresholds: work_mem_bytes, temp_bytes_per_day, temp_files_per_day
WITH win AS (
  SELECT sum(d.temp_bytes)::numeric AS temp_bytes, sum(d.temp_files)::numeric AS temp_files,
         greatest(extract(epoch FROM now() - coalesce(min(d.stats_reset), pg_postmaster_start_time())) / 86400.0, 0.01) AS days,
         min(d.stats_reset) AS stats_reset
  FROM pg_stat_database d WHERE d.datname IS NOT NULL
)
SELECT 'PG-MEM-004'::text AS check_id,
       'setting'::text    AS scope,
       'work_mem'::text   AS object,
       format('work_mem = %s (threshold %s) while the cluster wrote %s of temporary files in %s files over %s days: %s per day and %s files per day (thresholds %s per day, %s files per day). Every one of those is a sort, hash or materialise that did not fit in work_mem and went to disk. Counted from pg_stat_database since %s. Raise work_mem for the roles that run the heavy queries (ALTER ROLE ... SET work_mem), not globally - the global value multiplies by max_connections in PG-MEM-003.',
              current_setting('work_mem'),
              pg_size_pretty(:'pg_mem_004_work_mem_bytes'::bigint),
              pg_size_pretty(w.temp_bytes::bigint), to_char(w.temp_files, 'FM999,999,999,999'),
              round(w.days, 1)::text,
              pg_size_pretty((w.temp_bytes / w.days)::bigint),
              to_char(round(w.temp_files / w.days), 'FM999,999,999'),
              pg_size_pretty(:'pg_mem_004_temp_bytes_per_day'::bigint),
              to_char(:'pg_mem_004_temp_files_per_day'::bigint, 'FM999,999,999'),
              coalesce(w.stats_reset::text, 'the last statistics reset')) AS details,
       json_build_object('work_mem_bytes', (SELECT setting::bigint * 1024 FROM pg_settings WHERE name = 'work_mem'),
                         'threshold_work_mem_bytes', :'pg_mem_004_work_mem_bytes'::bigint,
                         'temp_bytes', w.temp_bytes::bigint, 'temp_files', w.temp_files::bigint,
                         'window_days', round(w.days, 2),
                         'temp_bytes_per_day', (w.temp_bytes / w.days)::bigint,
                         'temp_files_per_day', round(w.temp_files / w.days)::bigint,
                         'threshold_bytes_per_day', :'pg_mem_004_temp_bytes_per_day'::bigint,
                         'threshold_files_per_day', :'pg_mem_004_temp_files_per_day'::bigint,
                         'stats_reset', w.stats_reset)::text AS evidence_json,
       'medium'::text AS confidence
FROM win w
WHERE (SELECT setting::bigint * 1024 FROM pg_settings WHERE name = 'work_mem') <= :'pg_mem_004_work_mem_bytes'::bigint
  AND (w.temp_bytes / w.days >= :'pg_mem_004_temp_bytes_per_day'::bigint
    OR w.temp_files / w.days >= :'pg_mem_004_temp_files_per_day'::bigint);
\echo '@@END PG-MEM-004'

-- ======== PG-MEM-005  P100  maintenance_work_mem at the default on a large database ========
\echo '@@CHECK PG-MEM-005'
-- check: PG-MEM-005
-- title: maintenance_work_mem at the default on a large database
-- priority: 100
-- scope: setting
-- cost: 0
-- thresholds: maintenance_work_mem_bytes, total_bytes
SELECT 'PG-MEM-005'::text            AS check_id,
       'setting'::text               AS scope,
       'maintenance_work_mem'::text  AS object,
       format('maintenance_work_mem = %s (threshold %s) while the connectable databases total %s (threshold %s). This is the working memory for CREATE INDEX, REINDEX, ALTER TABLE rewrites and, before PostgreSQL 17, for the dead-tuple array of every vacuum: a vacuum that exceeds it has to make an extra pass over every index. autovacuum_work_mem = %s, autovacuum_max_workers = %s, so the autovacuum ceiling is %s in total.',
              current_setting('maintenance_work_mem'),
              pg_size_pretty(:'pg_mem_005_maintenance_work_mem_bytes'::bigint),
              pg_size_pretty((SELECT sum(pg_database_size(oid)) FROM pg_database WHERE datallowconn)),
              pg_size_pretty(:'pg_mem_005_total_bytes'::bigint),
              current_setting('autovacuum_work_mem'),
              (SELECT setting FROM pg_settings WHERE name = 'autovacuum_max_workers'),
              pg_size_pretty(((SELECT setting::bigint FROM pg_settings WHERE name = 'autovacuum_max_workers')
                              * (CASE WHEN (SELECT setting::bigint FROM pg_settings WHERE name = 'autovacuum_work_mem') < 0
                                      THEN (SELECT setting::bigint FROM pg_settings WHERE name = 'maintenance_work_mem')
                                      ELSE (SELECT setting::bigint FROM pg_settings WHERE name = 'autovacuum_work_mem') END) * 1024)::bigint)) AS details,
       json_build_object('maintenance_work_mem_bytes', (SELECT setting::bigint * 1024 FROM pg_settings WHERE name = 'maintenance_work_mem'),
                         'threshold_bytes', :'pg_mem_005_maintenance_work_mem_bytes'::bigint,
                         'cluster_bytes', (SELECT sum(pg_database_size(oid)) FROM pg_database WHERE datallowconn),
                         'threshold_cluster_bytes', :'pg_mem_005_total_bytes'::bigint,
                         'autovacuum_work_mem', current_setting('autovacuum_work_mem'),
                         'autovacuum_max_workers', (SELECT setting::int FROM pg_settings WHERE name = 'autovacuum_max_workers'))::text AS evidence_json,
       'medium'::text AS confidence
WHERE (SELECT setting::bigint * 1024 FROM pg_settings WHERE name = 'maintenance_work_mem') <= :'pg_mem_005_maintenance_work_mem_bytes'::bigint
  AND (SELECT sum(pg_database_size(oid)) FROM pg_database WHERE datallowconn) >= :'pg_mem_005_total_bytes'::bigint;
\echo '@@END PG-MEM-005'

-- ======== PG-MEM-006  P100  effective_cache_size at the default ========
\echo '@@CHECK PG-MEM-006'
-- check: PG-MEM-006
-- title: effective_cache_size at the default
-- priority: 100
-- scope: setting
-- cost: 0
SELECT 'PG-MEM-006'::text            AS check_id,
       'setting'::text               AS scope,
       'effective_cache_size'::text  AS object,
       format('effective_cache_size is at the default %s with source %s. This setting allocates no memory: it tells the planner how much of the data it can expect to find cached, in shared_buffers plus the operating-system page cache. Left at 4 GB on a host with more memory than that, the planner over-estimates the cost of repeated index lookups and drifts towards sequential scans and hash joins. The usual starting point is 50 to 75 percent of RAM. shared_buffers = %s, cluster size %s.',
              pg_size_pretty(s.setting::bigint * 8192), s.source,
              current_setting('shared_buffers'),
              pg_size_pretty((SELECT sum(pg_database_size(oid)) FROM pg_database))) AS details,
       json_build_object('effective_cache_size_bytes', s.setting::bigint * 8192,
                         'source', s.source, 'boot_val_bytes', s.boot_val::bigint * 8192,
                         'shared_buffers', current_setting('shared_buffers'),
                         'cluster_bytes', (SELECT sum(pg_database_size(oid)) FROM pg_database),
                         'random_page_cost', (SELECT setting FROM pg_settings WHERE name = 'random_page_cost'))::text AS evidence_json,
       'medium'::text AS confidence
FROM pg_settings s
WHERE s.name = 'effective_cache_size' AND s.source = 'default';
\echo '@@END PG-MEM-006'

-- ======== PG-MEM-008  P100  Huge pages not in effect with a large buffer cache ========
\echo '@@CHECK PG-MEM-008'
-- check: PG-MEM-008
-- title: Huge pages not in effect with a large buffer cache
-- priority: 100
-- scope: setting
-- cost: 0
-- thresholds: shared_buffers_bytes
\set ON_ERROR_STOP off
SELECT (current_setting('server_version_num')::int >= 170000) AS pg_mem_008_has_status \gset
WITH hp AS (
\if :pg_mem_008_has_status
  SELECT current_setting('huge_pages') AS requested, current_setting('huge_pages_status') AS status
\else
  SELECT current_setting('huge_pages') AS requested, 'unknown (huge_pages_status is PostgreSQL 17+)'::text AS status
\endif
)
SELECT 'PG-MEM-008'::text     AS check_id,
       'setting'::text        AS scope,
       'huge_pages'::text     AS object,
       format('shared_buffers = %s (threshold %s) with huge_pages = %s and huge_pages_status = %s. Mapping a buffer cache this size with 4 kB pages costs roughly %s of page tables per backend and puts constant pressure on the TLB; with 2 MB huge pages the same mapping is %s. max_connections = %s. Enabling huge pages needs vm.nr_hugepages set on the host and a server restart, and huge_pages = on (rather than try) makes the server refuse to start if they are unavailable, which is the safer signal.',
              current_setting('shared_buffers'),
              pg_size_pretty(:'pg_mem_008_shared_buffers_bytes'::bigint),
              hp.requested, hp.status,
              pg_size_pretty(((SELECT setting::bigint FROM pg_settings WHERE name = 'shared_buffers') * 8192 / 4096 * 8)::bigint),
              pg_size_pretty(((SELECT setting::bigint FROM pg_settings WHERE name = 'shared_buffers') * 8192 / 2097152 * 8)::bigint),
              (SELECT setting FROM pg_settings WHERE name = 'max_connections')) AS details,
       json_build_object('shared_buffers_bytes', (SELECT setting::bigint * 8192 FROM pg_settings WHERE name = 'shared_buffers'),
                         'threshold_bytes', :'pg_mem_008_shared_buffers_bytes'::bigint,
                         'huge_pages', hp.requested, 'huge_pages_status', hp.status,
                         'max_connections', (SELECT setting::int FROM pg_settings WHERE name = 'max_connections'))::text AS evidence_json,
       'medium'::text AS confidence
FROM hp
WHERE (SELECT setting::bigint * 8192 FROM pg_settings WHERE name = 'shared_buffers') >= :'pg_mem_008_shared_buffers_bytes'::bigint
  AND (hp.requested = 'off' OR hp.status = 'off');
\echo '@@END PG-MEM-008'

-- ======== PG-MEM-009  P100  temp_file_limit unlimited ========
\echo '@@CHECK PG-MEM-009'
-- check: PG-MEM-009
-- title: temp_file_limit unlimited
-- priority: 100
-- scope: setting
-- cost: 0
SELECT 'PG-MEM-009'::text        AS check_id,
       'setting'::text           AS scope,
       'temp_file_limit'::text   AS object,
       format('temp_file_limit = -1 (unlimited), source %s. A single sort, hash join or CTE materialisation that under-estimates its input can write until the data volume is full, at which point every write in the cluster fails and, if pg_wal shares the volume, the server PANICs. The cluster already writes %s of temporary files per day (PG-CAP-008 measures it). A limit sized so one query cannot fill the volume turns that outage into one failed query with "temporary file size exceeds temp_file_limit". work_mem = %s.',
              s.source,
              coalesce(pg_size_pretty((SELECT (sum(temp_bytes) / greatest(extract(epoch FROM now() - coalesce(min(stats_reset), pg_postmaster_start_time())) / 86400.0, 0.01))::bigint
                                       FROM pg_stat_database)), 'an unknown amount'),
              current_setting('work_mem')) AS details,
       json_build_object('temp_file_limit', -1, 'source', s.source,
                         'work_mem', current_setting('work_mem'),
                         'temp_bytes_total', (SELECT sum(temp_bytes) FROM pg_stat_database))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_settings s
WHERE s.name = 'temp_file_limit' AND s.setting::bigint = -1;
\echo '@@END PG-MEM-009'

-- ======== PG-QRY-001  P100  pg_stat_statements not available ========
\echo '@@CHECK PG-QRY-001'
-- check: PG-QRY-001
-- title: pg_stat_statements not available
-- priority: 100
-- scope: database
-- cost: 0
SELECT 'PG-QRY-001'::text AS check_id,
       'database'::text   AS scope,
       current_database()::text AS object,
       format('pg_stat_statements is %s. Without it there is no per-statement view of this workload at all: PG-QRY-003 through PG-QRY-016 cannot run, and the only evidence about what the server spends its time on is the aggregate counters in pg_stat_database and whatever the slow-query log has captured (log_min_duration_statement = %s). %s Collecting it costs a small fixed amount of shared memory and a hash lookup per statement.',
              CASE WHEN NOT p.preloaded THEN 'not in shared_preload_libraries'
                   WHEN NOT p.available THEN 'preloaded but not present as an available extension'
                   ELSE format('preloaded but not created in database %s', current_database()) END,
              current_setting('log_min_duration_statement'),
              CASE WHEN NOT p.preloaded
                   THEN 'Adding it to shared_preload_libraries requires a server restart, then CREATE EXTENSION pg_stat_statements in each database you want to observe.'
                   ELSE 'The library is already loaded, so only CREATE EXTENSION pg_stat_statements is needed here - no restart.' END) AS details,
       json_build_object('preloaded', p.preloaded, 'available', p.available, 'installed', p.installed,
                         'shared_preload_libraries', current_setting('shared_preload_libraries'),
                         'log_min_duration_statement', current_setting('log_min_duration_statement'),
                         'database', current_database())::text AS evidence_json,
       'high'::text AS confidence
FROM (
  SELECT current_setting('shared_preload_libraries') LIKE '%pg_stat_statements%' AS preloaded,
         EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'pg_stat_statements') AS available,
         EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_stat_statements') AS installed
) p
WHERE NOT p.installed OR NOT p.preloaded;
\echo '@@END PG-QRY-001'

-- ======== PG-QRY-011  P100  High transaction rollback ratio ========
\echo '@@CHECK PG-QRY-011'
-- check: PG-QRY-011
-- title: High transaction rollback ratio
-- priority: 100
-- scope: database
-- cost: 0
-- thresholds: rollback_ratio, min_transactions
SELECT 'PG-QRY-011'::text AS check_id,
       'database'::text   AS scope,
       d.datname::text    AS object,
       format('%s of %s transactions in database %s ended in ROLLBACK (%s%%, threshold %s%%) since %s. PostgreSQL rolls a transaction back when the application asks it to, and also whenever any statement in it raises an error - after which every subsequent statement fails with "current transaction is aborted" until the block ends. A tenth of all transactions failing is usually one recurring application error, a retry loop around a constraint violation, or a health check that deliberately aborts. Deadlocks in this database: %s (PG-LOCK-008).',
              to_char(d.xact_rollback, 'FM999,999,999,999'),
              to_char(d.xact_commit + d.xact_rollback, 'FM999,999,999,999'), d.datname,
              round(100.0 * d.xact_rollback / nullif(d.xact_commit + d.xact_rollback, 0), 1)::text,
              round(100 * :'pg_qry_011_rollback_ratio'::numeric)::text,
              coalesce(d.stats_reset::text, 'the last statistics reset'),
              d.deadlocks) AS details,
       json_build_object('datname', d.datname, 'xact_commit', d.xact_commit, 'xact_rollback', d.xact_rollback,
                         'rollback_ratio', round(d.xact_rollback::numeric / nullif(d.xact_commit + d.xact_rollback, 0), 4),
                         'threshold_ratio', :'pg_qry_011_rollback_ratio'::numeric,
                         'threshold_min_transactions', :'pg_qry_011_min_transactions'::bigint,
                         'deadlocks', d.deadlocks, 'stats_reset', d.stats_reset)::text AS evidence_json,
       'medium'::text AS confidence
FROM pg_stat_database d
WHERE d.datname IS NOT NULL
  AND d.xact_commit + d.xact_rollback >= :'pg_qry_011_min_transactions'::bigint
  AND d.xact_rollback::numeric / nullif(d.xact_commit + d.xact_rollback, 0) >= :'pg_qry_011_rollback_ratio'::numeric
ORDER BY d.xact_rollback DESC;
\echo '@@END PG-QRY-011'

-- ======== PG-REL-006  P100  Slow-query logging disabled ========
\echo '@@CHECK PG-REL-006'
-- check: PG-REL-006
-- title: Slow-query logging disabled
-- priority: 100
-- scope: setting
-- cost: 0
SELECT 'PG-REL-006'::text                  AS check_id,
       'setting'::text                     AS scope,
       'log_min_duration_statement'::text  AS object,
       format('log_min_duration_statement = -1 (source %s) and auto_explain is not loaded. No statement is ever logged for being slow, so when someone reports that "the application was slow at 3am" there is nothing on the server to look at afterwards: pg_stat_statements (%s here) gives cumulative totals, not the individual slow execution, its parameters or its timestamp. A threshold of 250 to 1000 ms costs one log line per slow statement; on a busy server log_min_duration_sample plus log_statement_sample_rate (PostgreSQL 13 and newer) bound the volume. log_statement = %s, log_destination = %s.',
              s.source,
              CASE WHEN EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_stat_statements')
                   THEN 'installed' ELSE 'not installed' END,
              current_setting('log_statement'), current_setting('log_destination')) AS details,
       json_build_object('log_min_duration_statement', s.setting, 'source', s.source,
                         'auto_explain_loaded', current_setting('shared_preload_libraries') LIKE '%auto_explain%',
                         'pgss_installed', EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_stat_statements'),
                         'log_statement', current_setting('log_statement'),
                         'log_destination', current_setting('log_destination'),
                         'logging_collector', current_setting('logging_collector'))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_settings s
WHERE s.name = 'log_min_duration_statement' AND s.setting::int = -1
  AND current_setting('shared_preload_libraries') NOT LIKE '%auto_explain%';
\echo '@@END PG-REL-006'

-- ======== PG-REL-009  P100  No evidence of a monitoring agent ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_rel_009 \gset
\if :gate_pg_rel_009
\echo '@@CHECK PG-REL-009'
-- check: PG-REL-009
-- title: No evidence of a monitoring agent
-- priority: 100
-- scope: cluster
-- cost: 0
-- min_version: 10
SELECT 'PG-REL-009'::text AS check_id,
       'cluster'::text    AS scope,
       NULL::text         AS object,
       format('Nothing visible from inside the server suggests a monitoring agent is collecting from it: no role name and no application_name among the %s current connection(s) matches a known agent, and no monitoring extension is installed. Extensions present: %s. Roles that can log in: %s. This is weak evidence - an agent that polls every minute is simply not connected at the moment this ran, and an agent may collect from a replica instead - so confidence is low. It matters because every rate in this report is a since-reset average: without a time series there is no way to tell a problem that started this morning from one that has been there for a year.',
              (SELECT count(*) FROM pg_stat_activity WHERE backend_type = 'client backend'),
              coalesce((SELECT string_agg(extname, ', ' ORDER BY extname) FROM pg_extension), 'none'),
              (SELECT count(*) FROM pg_roles WHERE rolcanlogin)) AS details,
       json_build_object('client_backends', (SELECT count(*) FROM pg_stat_activity WHERE backend_type = 'client backend'),
                         'extensions', (SELECT string_agg(extname, ';' ORDER BY extname) FROM pg_extension),
                         'login_roles', (SELECT count(*) FROM pg_roles WHERE rolcanlogin),
                         'detection', 'application_name, role name and extension name matching against a list of known agents')::text AS evidence_json,
       'low'::text AS confidence
WHERE NOT EXISTS (
  SELECT 1 FROM pg_stat_activity a
  WHERE coalesce(a.application_name, '') || ' ' || coalesce(a.usename, '')
        ~* '(datadog|newrelic|new_relic|pgwatch|postgres_exporter|prometheus|pganalyze|zabbix|nagios|check_postgres|grafana|percona|pmm|sentry|dynatrace|telegraf|netdata|instana|appdynamics)')
  AND NOT EXISTS (
  SELECT 1 FROM pg_roles r
  WHERE r.rolname NOT LIKE 'pg\_%'
    AND r.rolname ~* '(datadog|newrelic|new_relic|pgwatch|postgres_exporter|prometheus|pganalyze|zabbix|nagios|check_postgres|grafana|percona|pmm|telegraf|netdata|monitor)')
  AND NOT EXISTS (
  SELECT 1 FROM pg_extension e WHERE e.extname IN ('pg_stat_monitor', 'pgwatch', 'pg_qualstats', 'powa', 'pg_stat_kcache'));
\echo '@@END PG-REL-009'
\else
\echo '@@SKIP PG-REL-009 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-REL-010  P100  Settings changed but awaiting restart ========
SELECT (current_setting('server_version_num')::int >= 90500) AS gate_pg_rel_010 \gset
\if :gate_pg_rel_010
\echo '@@CHECK PG-REL-010'
-- check: PG-REL-010
-- title: Settings changed but awaiting restart
-- priority: 100
-- scope: setting
-- cost: 0
-- min_version: 9.5
SELECT 'PG-REL-010'::text AS check_id,
       'setting'::text    AS scope,
       s.name::text       AS object,
       format('%s is set to %s in %s but the running server is still using %s: the change needs a restart and has not had one. The server has been up for %s. Anyone reading postgresql.conf, or an infrastructure-as-code diff, will believe the new value is live. %s',
              s.name, coalesce(s.setting, '(null)'),
              coalesce(s.sourcefile || ':' || s.sourceline::text, s.source),
              coalesce(s.reset_val, '(null)'),
              justify_interval(date_trunc('second', now() - pg_postmaster_start_time())),
              CASE WHEN s.name IN ('shared_buffers', 'max_connections', 'wal_level', 'max_wal_senders',
                                   'max_replication_slots', 'max_worker_processes', 'shared_preload_libraries',
                                   'max_prepared_transactions', 'huge_pages', 'wal_buffers')
                   THEN 'This one changes what the server can do, not only how fast it does it.'
                   ELSE '' END) AS details,
       json_build_object('setting', s.name, 'pending_value', s.setting, 'running_value', s.reset_val,
                         'source', s.source, 'sourcefile', s.sourcefile, 'sourceline', s.sourceline,
                         'context', s.context,
                         'uptime_seconds', round(extract(epoch FROM now() - pg_postmaster_start_time()))::bigint)::text AS evidence_json,
       'high'::text AS confidence
FROM pg_settings s
WHERE s.pending_restart
ORDER BY s.name;
\echo '@@END PG-REL-010'
\else
\echo '@@SKIP PG-REL-010 needs PostgreSQL 9.5 or newer'
\endif

-- ======== PG-REL-012  P100  restart_after_crash disabled ========
\echo '@@CHECK PG-REL-012'
-- check: PG-REL-012
-- title: restart_after_crash disabled
-- priority: 100
-- scope: setting
-- cost: 0
SELECT 'PG-REL-012'::text            AS check_id,
       'setting'::text               AS scope,
       'restart_after_crash'::text   AS object,
       format('restart_after_crash = off (source %s). If any backend dies abnormally, the postmaster shuts the whole cluster down and leaves it down instead of running crash recovery and coming back. That is the correct setting when an external cluster manager - Patroni, repmgr, a Kubernetes operator - needs to make the failover decision itself, and it is an outage waiting to happen when nothing external is watching. Record the supervisor in .db-triage.yml as baseline.supervisor to silence this. Uptime %s, %s connection(s) now.',
              s.source,
              justify_interval(date_trunc('second', now() - pg_postmaster_start_time())),
              (SELECT count(*) FROM pg_stat_activity WHERE backend_type = 'client backend')) AS details,
       json_build_object('restart_after_crash', s.setting, 'source', s.source,
                         'uptime_seconds', round(extract(epoch FROM now() - pg_postmaster_start_time()))::bigint,
                         'in_recovery', pg_is_in_recovery(),
                         'replication_slots', (SELECT count(*) FROM pg_replication_slots))::text AS evidence_json,
       'medium'::text AS confidence
FROM pg_settings s
WHERE s.name = 'restart_after_crash' AND s.setting = 'off';
\echo '@@END PG-REL-012'

-- ======== PG-SCHEMA-013  P100  Large objects present (vacuumlo candidate) ========
\echo '@@CHECK PG-SCHEMA-013'
-- check: PG-SCHEMA-013
-- title: Large objects present (vacuumlo candidate)
-- priority: 100
-- scope: database
-- cost: 1
-- thresholds: min_bytes
SELECT 'PG-SCHEMA-013'::text  AS check_id,
       'database'::text       AS scope,
       format('%I.pg_largeobject', current_database())::text AS object,
       format('pg_largeobject holds %s across %s large object(s) in database %s (threshold %s). A large object is not owned by the row that references its OID: deleting that row leaves the object behind forever, and nothing in the server ever notices. The standard sweep is the vacuumlo utility, which finds OIDs no column references and unlinks them - that is a write, so it is yours to schedule. pg_largeobject is also a normal table for vacuum purposes, so it bloats and freezes like one; its relfrozenxid age is %s.',
              pg_size_pretty(pg_total_relation_size('pg_largeobject'::regclass)),
              to_char((SELECT count(*) FROM pg_largeobject_metadata), 'FM999,999,999,999'),
              current_database(),
              pg_size_pretty(:'pg_schema_013_min_bytes'::bigint),
              to_char((SELECT age(relfrozenxid) FROM pg_class WHERE oid = 'pg_largeobject'::regclass), 'FM999,999,999,999')) AS details,
       json_build_object('database', current_database(),
                         'largeobject_bytes', pg_total_relation_size('pg_largeobject'::regclass),
                         'largeobject_count', (SELECT count(*) FROM pg_largeobject_metadata),
                         'threshold_bytes', :'pg_schema_013_min_bytes'::bigint,
                         'relfrozenxid_age', (SELECT age(relfrozenxid) FROM pg_class WHERE oid = 'pg_largeobject'::regclass))::text AS evidence_json,
       'high'::text AS confidence
WHERE pg_total_relation_size('pg_largeobject'::regclass) >= :'pg_schema_013_min_bytes'::bigint;
\echo '@@END PG-SCHEMA-013'

-- ======== PG-SEC-005  P100  Most client connections not using SSL ========
SELECT (current_setting('server_version_num')::int >= 90500) AS gate_pg_sec_005 \gset
\if :gate_pg_sec_005
\echo '@@CHECK PG-SEC-005'
-- check: PG-SEC-005
-- title: Most client connections not using SSL
-- priority: 100
-- scope: cluster
-- cost: 0
-- min_version: 9.5
-- thresholds: ssl_fraction
WITH c AS (
  SELECT count(*) AS remote,
         count(*) FILTER (WHERE s.ssl) AS encrypted,
         string_agg(DISTINCT coalesce(s.version, 'none'), ', ') AS versions
  FROM pg_stat_activity a
  JOIN pg_stat_ssl s ON s.pid = a.pid
  WHERE a.backend_type = 'client backend' AND a.client_addr IS NOT NULL
)
SELECT 'PG-SEC-005'::text AS check_id,
       'cluster'::text    AS scope,
       NULL::text         AS object,
       format('Only %s of %s non-local client connections are using TLS (%s%%, threshold %s%%) at snapshot time. TLS versions in use: %s. The server has ssl = on, so the capability exists and clients are choosing not to use it - usually because sslmode defaults to prefer and pg_hba.conf accepts a plain host rule. Requiring it means changing the matching host lines to hostssl, which will break any client that has not been configured first.',
              c.encrypted, c.remote,
              round(100.0 * c.encrypted / nullif(c.remote, 0), 1)::text,
              round(100 * :'pg_sec_005_ssl_fraction'::numeric)::text,
              coalesce(c.versions, 'none')) AS details,
       json_build_object('remote_connections', c.remote, 'encrypted_connections', c.encrypted,
                         'encrypted_fraction', round(c.encrypted::numeric / nullif(c.remote, 0), 4),
                         'threshold_fraction', :'pg_sec_005_ssl_fraction'::numeric,
                         'tls_versions', c.versions, 'ssl', current_setting('ssl'),
                         'sampled_at', now())::text AS evidence_json,
       'medium'::text AS confidence
FROM c
WHERE current_setting('ssl') = 'on'
  AND c.remote > 0
  AND c.encrypted::numeric / nullif(c.remote, 0) < :'pg_sec_005_ssl_fraction'::numeric;
\echo '@@END PG-SEC-005'
\else
\echo '@@SKIP PG-SEC-005 needs PostgreSQL 9.5 or newer'
\endif

-- ======== PG-SEC-006  P100  Non-SCRAM password authentication in use ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_sec_006 \gset
\if :gate_pg_sec_006
\echo '@@CHECK PG-SEC-006'
-- check: PG-SEC-006
-- title: Non-SCRAM password authentication in use
-- priority: 100
-- scope: cluster
-- cost: 0
-- min_version: 10
-- The pg_authid part needs superuser; without it only the setting is evaluated
-- and the run records the role scan as skipped for privilege.
SELECT 'PG-SEC-006'::text            AS check_id,
       'cluster'::text               AS scope,
       'password_encryption'::text   AS object,
       format('password_encryption = %s, so every password set from now on is stored as an MD5 hash of the password and the role name. MD5 verification sends a value derived only from that hash, so anyone who reads pg_authid can authenticate without knowing the password, and the hash itself is offline-crackable. SCRAM-SHA-256 has been the alternative since PostgreSQL 10 and the default since 14; PostgreSQL 18 warns on md5. Changing the setting does not re-hash existing passwords - each role must set its password again.',
              s.setting) AS details,
       json_build_object('password_encryption', s.setting, 'source', s.source,
                         'server_version_num', current_setting('server_version_num')::int)::text AS evidence_json,
       'high'::text AS confidence
FROM pg_settings s
WHERE s.name = 'password_encryption' AND s.setting = 'md5';
\echo '@@END PG-SEC-006'
\else
\echo '@@SKIP PG-SEC-006 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-SEC-007  P100  trust authentication on the local socket ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_sec_007 \gset
\if :gate_pg_sec_007
\echo '@@CHECK PG-SEC-007'
-- check: PG-SEC-007
-- title: trust authentication on the local socket
-- priority: 100
-- scope: cluster
-- cost: 0
-- min_version: 10
-- requires: superuser
SELECT 'PG-SEC-007'::text AS check_id,
       'cluster'::text    AS scope,
       format('pg_hba.conf:%s', r.line_number)::text AS object,
       format('pg_hba.conf line %s: local %s %s trust. Any operating-system account that can reach the Unix socket at %s can connect as any role, including superusers, with no credential. That includes every process in the same container and anything that gets a shell on the host. This is P100 rather than P1 because it needs host access first; "peer" gives the same convenience for the postgres account without giving it to everything else.',
              r.line_number, array_to_string(r.database, ','), array_to_string(r.user_name, ','),
              current_setting('unix_socket_directories')) AS details,
       json_build_object('line_number', r.line_number, 'type', r.type,
                         'database', array_to_string(r.database, ';'),
                         'user_name', array_to_string(r.user_name, ';'),
                         'auth_method', r.auth_method,
                         'unix_socket_directories', current_setting('unix_socket_directories'))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_hba_file_rules r
WHERE r.error IS NULL AND r.type = 'local' AND r.auth_method = 'trust'
ORDER BY r.line_number;
\echo '@@END PG-SEC-007'
\else
\echo '@@SKIP PG-SEC-007 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-SEC-011  P100  Non-superuser roles with server file access ========
SELECT (current_setting('server_version_num')::int >= 110000) AS gate_pg_sec_011 \gset
\if :gate_pg_sec_011
\echo '@@CHECK PG-SEC-011'
-- check: PG-SEC-011
-- title: Non-superuser roles with server file access
-- priority: 100
-- scope: role
-- cost: 0
-- min_version: 11
SELECT 'PG-SEC-011'::text AS check_id,
       'role'::text       AS scope,
       m.member_name::text AS object,
       format('Role %s is a member of %s. %s That is equivalent to a superuser in practice, without appearing in the superuser list (PG-SEC-009). Login: %s. Currently connected: %s session(s).',
              m.member_name, m.granted_role,
              CASE m.granted_role
                WHEN 'pg_read_server_files' THEN 'It can read any file the server account can read, including postgresql.conf, pg_hba.conf, the server''s TLS private key, and anything else on the host filesystem.'
                WHEN 'pg_write_server_files' THEN 'It can write any file the server account can write, which includes overwriting configuration and libraries the server loads.'
                WHEN 'pg_execute_server_program' THEN 'It can run arbitrary programs on the host as the server account through COPY ... FROM PROGRAM.'
                ELSE '' END,
              m.can_login,
              (SELECT count(*) FROM pg_stat_activity a WHERE a.usename = m.member_name)) AS details,
       json_build_object('role', m.member_name, 'granted_role', m.granted_role,
                         'can_login', m.can_login,
                         'current_sessions', (SELECT count(*) FROM pg_stat_activity a WHERE a.usename = m.member_name))::text AS evidence_json,
       'high'::text AS confidence
FROM (
  SELECT member.rolname AS member_name, grantee.rolname AS granted_role, member.rolcanlogin AS can_login
  FROM pg_auth_members am
  JOIN pg_roles grantee ON grantee.oid = am.roleid
  JOIN pg_roles member  ON member.oid  = am.member
  WHERE grantee.rolname IN ('pg_read_server_files', 'pg_write_server_files', 'pg_execute_server_program')
    AND NOT member.rolsuper
) m
ORDER BY m.member_name, m.granted_role;
\echo '@@END PG-SEC-011'
\else
\echo '@@SKIP PG-SEC-011 needs PostgreSQL 11 or newer'
\endif

-- ======== PG-VAC-008  P100  Autovacuum throttled at defaults on a large database ========
\echo '@@CHECK PG-VAC-008'
-- check: PG-VAC-008
-- title: Autovacuum throttled at defaults on a large database
-- priority: 100
-- scope: setting
-- cost: 0
-- thresholds: total_bytes, cost_delay_ms
WITH s AS (
  SELECT (SELECT sum(pg_database_size(oid)) FROM pg_database WHERE datallowconn) AS total_bytes,
         (SELECT setting::numeric FROM pg_settings WHERE name = 'autovacuum_vacuum_cost_delay') AS delay_ms,
         (SELECT setting::int FROM pg_settings WHERE name = 'autovacuum_vacuum_cost_limit') AS av_limit,
         (SELECT setting::int FROM pg_settings WHERE name = 'vacuum_cost_limit')            AS vac_limit,
         (SELECT setting::numeric FROM pg_settings WHERE name = 'vacuum_cost_page_dirty')   AS dirty_cost,
         current_setting('block_size')::numeric                                             AS bs
)
SELECT 'PG-VAC-008'::text                      AS check_id,
       'setting'::text                         AS scope,
       'autovacuum_vacuum_cost_limit'::text    AS object,
       format('Cluster holds %s of connectable databases (threshold %s) while autovacuum runs at the shipped cost settings: autovacuum_vacuum_cost_delay = %s ms, effective cost limit %s%s. That is roughly %s MB/s of dirty pages per worker across %s workers, which cannot keep up with hundreds of GB of churn.',
              pg_size_pretty(s.total_bytes), pg_size_pretty(:'pg_vac_008_total_bytes'::bigint),
              s.delay_ms::text,
              CASE WHEN s.av_limit < 0 THEN s.vac_limit ELSE s.av_limit END,
              CASE WHEN s.av_limit < 0 THEN ' (inherited from vacuum_cost_limit)' ELSE '' END,
              round(((CASE WHEN s.av_limit < 0 THEN s.vac_limit ELSE s.av_limit END)::numeric / s.dirty_cost)
                    * (1000.0 / greatest(s.delay_ms, 0.1)) * s.bs / 1048576.0, 1)::text,
              current_setting('autovacuum_max_workers')) AS details,
       json_build_object('total_bytes', s.total_bytes, 'threshold_bytes', :'pg_vac_008_total_bytes'::bigint,
                         'autovacuum_vacuum_cost_delay_ms', s.delay_ms,
                         'autovacuum_vacuum_cost_limit', s.av_limit,
                         'vacuum_cost_limit', s.vac_limit,
                         'vacuum_cost_page_dirty', s.dirty_cost,
                         'dirty_mb_per_sec_per_worker',
                            round(((CASE WHEN s.av_limit < 0 THEN s.vac_limit ELSE s.av_limit END)::numeric / s.dirty_cost)
                                  * (1000.0 / greatest(s.delay_ms, 0.1)) * s.bs / 1048576.0, 2),
                         'autovacuum_max_workers', current_setting('autovacuum_max_workers')::int)::text AS evidence_json,
       'medium'::text AS confidence
FROM s
WHERE s.total_bytes >= :'pg_vac_008_total_bytes'::bigint
  AND s.delay_ms >= :'pg_vac_008_cost_delay_ms'::numeric
  AND s.av_limit < 0 AND s.vac_limit <= 200;
\echo '@@END PG-VAC-008'

-- ======== PG-WAL-002  P100  max_wal_size at the default on a write-active primary ========
SELECT (NOT pg_is_in_recovery()) AS gate_pg_wal_002 \gset
\if :gate_pg_wal_002
\echo '@@CHECK PG-WAL-002'
-- check: PG-WAL-002
-- title: max_wal_size at the default on a write-active primary
-- priority: 100
-- scope: setting
-- cost: 0
-- run_on: primary
-- thresholds: wal_bytes_per_hour
-- pg_stat_wal arrived in PostgreSQL 14. Below that the WAL rate is estimated
-- from the position of the write-ahead log against server uptime, which is a
-- lower bound (it misses WAL written before the last restart).
\set ON_ERROR_STOP off
SELECT (current_setting('server_version_num')::int >= 140000) AS pg_wal_002_has_stat_wal \gset
WITH w AS (
\if :pg_wal_002_has_stat_wal
  SELECT wal_bytes::numeric AS wal_bytes,
         greatest(extract(epoch FROM now() - coalesce(stats_reset, pg_postmaster_start_time())), 60) AS window_seconds,
         'pg_stat_wal since stats_reset'::text AS source
  FROM pg_stat_wal
\else
  SELECT pg_wal_lsn_diff(pg_current_wal_lsn(), '0/0')::numeric AS wal_bytes,
         greatest(extract(epoch FROM now() - pg_postmaster_start_time()), 60) AS window_seconds,
         'WAL position against uptime (lower bound)'::text AS source
\endif
)
SELECT 'PG-WAL-002'::text   AS check_id,
       'setting'::text      AS scope,
       'max_wal_size'::text AS object,
       format('max_wal_size is at the shipped default of 1 GB while this primary generates about %s of WAL per hour (%s, over %s). At that rate max_wal_size is consumed every %s, so checkpoints are triggered by volume rather than by checkpoint_timeout (%s) - see PG-WAL-001. Raising max_wal_size trades pg_wal disk for fewer checkpoints and less full-page-image WAL.',
              pg_size_pretty((w.wal_bytes / w.window_seconds * 3600)::bigint),
              w.source,
              justify_interval(date_trunc('second', make_interval(secs => w.window_seconds))),
              justify_interval(date_trunc('second',
                make_interval(secs => (1073741824.0 / greatest(w.wal_bytes / w.window_seconds, 1))::double precision))),
              current_setting('checkpoint_timeout')) AS details,
       json_build_object('max_wal_size_bytes', 1073741824::bigint,
                         'wal_bytes_per_hour', round(w.wal_bytes / w.window_seconds * 3600)::bigint,
                         'threshold_bytes_per_hour', :'pg_wal_002_wal_bytes_per_hour'::bigint,
                         'window_seconds', round(w.window_seconds)::bigint,
                         'measurement_source', w.source,
                         'checkpoint_timeout', current_setting('checkpoint_timeout'))::text AS evidence_json,
       'medium'::text AS confidence
FROM w
WHERE NOT pg_is_in_recovery()
  AND (SELECT setting::bigint FROM pg_settings WHERE name = 'max_wal_size') = 1024
  AND w.wal_bytes / w.window_seconds * 3600 >= :'pg_wal_002_wal_bytes_per_hour'::bigint;
\echo '@@END PG-WAL-002'
\else
\echo '@@SKIP PG-WAL-002 primary only'
\endif

-- ======== PG-WAL-004  P100  Backends forced to write or fsync their own buffers ========
SELECT (NOT pg_is_in_recovery()) AS gate_pg_wal_004 \gset
\if :gate_pg_wal_004
\echo '@@CHECK PG-WAL-004'
-- check: PG-WAL-004
-- title: Backends forced to write or fsync their own buffers
-- priority: 100
-- scope: cluster
-- cost: 0
-- run_on: primary
-- pg_stat_io (PostgreSQL 16+) reports backend writes and fsyncs directly.
-- Before 16 the same signal comes from pg_stat_bgwriter.buffers_backend and
-- buffers_backend_fsync, which PostgreSQL 17 removed.
\set ON_ERROR_STOP off
SELECT (current_setting('server_version_num')::int >= 160000) AS pg_wal_004_has_stat_io \gset
\if :pg_wal_004_has_stat_io
WITH io AS (
  SELECT sum(writes) FILTER (WHERE backend_type = 'client backend')          AS backend_writes,
         sum(fsyncs) FILTER (WHERE backend_type = 'client backend')          AS backend_fsyncs,
         sum(writes) FILTER (WHERE backend_type IN ('checkpointer', 'background writer')) AS helper_writes,
         max(stats_reset)                                                    AS stats_reset
  FROM pg_stat_io
  WHERE context = 'normal' AND object = 'relation'
)
SELECT 'PG-WAL-004'::text AS check_id,
       'cluster'::text    AS scope,
       NULL::text         AS object,
       format('Client backends performed %s buffer writes and %s fsyncs of their own since %s, against %s writes by the checkpointer and background writer combined. A backend that has to evict and write its own dirty buffer stalls the query that owns it, and a backend fsync means the fsync request queue was full. Raise max_wal_size, raise bgwriter_lru_maxpages (currently %s), or fix storage latency. Read from pg_stat_io.',
              to_char(coalesce(io.backend_writes, 0), 'FM999,999,999,999'),
              to_char(coalesce(io.backend_fsyncs, 0), 'FM999,999,999,999'),
              coalesce(io.stats_reset::text, 'the last statistics reset'),
              to_char(coalesce(io.helper_writes, 0), 'FM999,999,999,999'),
              (SELECT setting FROM pg_settings WHERE name = 'bgwriter_lru_maxpages')) AS details,
       json_build_object('source', 'pg_stat_io',
                         'backend_writes', coalesce(io.backend_writes, 0),
                         'backend_fsyncs', coalesce(io.backend_fsyncs, 0),
                         'helper_writes', coalesce(io.helper_writes, 0),
                         'stats_reset', io.stats_reset,
                         'bgwriter_lru_maxpages', (SELECT setting::int FROM pg_settings WHERE name = 'bgwriter_lru_maxpages'),
                         'max_wal_size', current_setting('max_wal_size'))::text AS evidence_json,
       'medium'::text AS confidence
FROM io
WHERE NOT pg_is_in_recovery()
  AND (coalesce(io.backend_fsyncs, 0) > 0
    OR coalesce(io.backend_writes, 0) > coalesce(io.helper_writes, 0));
\else
SELECT 'PG-WAL-004'::text AS check_id,
       'cluster'::text    AS scope,
       NULL::text         AS object,
       format('Client backends performed %s buffer writes and %s fsyncs of their own since %s, against %s by the checkpointer and %s by the background writer. A backend that has to evict and write its own dirty buffer stalls the query that owns it, and a backend fsync means the fsync request queue was full. Raise max_wal_size, raise bgwriter_lru_maxpages (currently %s), or fix storage latency. Read from pg_stat_bgwriter.',
              to_char(b.buffers_backend, 'FM999,999,999,999'),
              to_char(b.buffers_backend_fsync, 'FM999,999,999,999'),
              coalesce(b.stats_reset::text, 'the last statistics reset'),
              to_char(b.buffers_checkpoint, 'FM999,999,999,999'),
              to_char(b.buffers_clean, 'FM999,999,999,999'),
              (SELECT setting FROM pg_settings WHERE name = 'bgwriter_lru_maxpages')) AS details,
       json_build_object('source', 'pg_stat_bgwriter',
                         'buffers_backend', b.buffers_backend,
                         'buffers_backend_fsync', b.buffers_backend_fsync,
                         'buffers_checkpoint', b.buffers_checkpoint,
                         'buffers_clean', b.buffers_clean,
                         'stats_reset', b.stats_reset,
                         'bgwriter_lru_maxpages', (SELECT setting::int FROM pg_settings WHERE name = 'bgwriter_lru_maxpages'))::text AS evidence_json,
       'medium'::text AS confidence
FROM pg_stat_bgwriter b
WHERE NOT pg_is_in_recovery()
  AND (b.buffers_backend_fsync > 0
    OR b.buffers_backend > b.buffers_checkpoint + b.buffers_clean);
\endif
\echo '@@END PG-WAL-004'
\else
\echo '@@SKIP PG-WAL-004 primary only'
\endif

-- ======== PG-WAL-007  P100  WAL buffers overflowing ========
SELECT (current_setting('server_version_num')::int >= 140000 AND NOT pg_is_in_recovery()) AS gate_pg_wal_007 \gset
\if :gate_pg_wal_007
\echo '@@CHECK PG-WAL-007'
-- check: PG-WAL-007
-- title: WAL buffers overflowing
-- priority: 100
-- scope: cluster
-- cost: 0
-- min_version: 14
-- run_on: primary
-- thresholds: full_ratio, min_full
SELECT 'PG-WAL-007'::text  AS check_id,
       'cluster'::text     AS scope,
       'wal_buffers'::text AS object,
       format('wal_buffers_full = %s against wal_write = %s (%s%%, thresholds %s%% and %s occurrences) since %s. Each of those is a backend that had to flush WAL itself because the shared WAL buffer was full, which serialises writers behind an I/O. wal_buffers = %s; raising it needs a restart. wal_bytes since reset: %s.',
              to_char(w.wal_buffers_full, 'FM999,999,999,999'),
              to_char(w.wal_write, 'FM999,999,999,999'),
              round(100.0 * w.wal_buffers_full / nullif(w.wal_write, 0), 1)::text,
              round(100 * :'pg_wal_007_full_ratio'::numeric)::text,
              to_char(:'pg_wal_007_min_full'::bigint, 'FM999,999,999,999'),
              coalesce(w.stats_reset::text, 'the last statistics reset'),
              current_setting('wal_buffers'),
              pg_size_pretty(w.wal_bytes::bigint)) AS details,
       json_build_object('wal_buffers_full', w.wal_buffers_full, 'wal_write', w.wal_write,
                         'full_ratio', round(w.wal_buffers_full::numeric / nullif(w.wal_write, 0), 4),
                         'threshold_ratio', :'pg_wal_007_full_ratio'::numeric,
                         'threshold_min_full', :'pg_wal_007_min_full'::bigint,
                         'wal_bytes', w.wal_bytes::bigint, 'stats_reset', w.stats_reset,
                         'wal_buffers', current_setting('wal_buffers'))::text AS evidence_json,
       'medium'::text AS confidence
FROM pg_stat_wal w
WHERE NOT pg_is_in_recovery()
  AND w.wal_buffers_full >= :'pg_wal_007_min_full'::bigint
  AND w.wal_buffers_full::numeric / nullif(w.wal_write, 0) >= :'pg_wal_007_full_ratio'::numeric;
\echo '@@END PG-WAL-007'
\else
\echo '@@SKIP PG-WAL-007 needs PostgreSQL 14 or newer; primary only'
\endif

-- ======== PG-WAL-009  P100  Slow checkpoint sync phase ========
SELECT (NOT pg_is_in_recovery()) AS gate_pg_wal_009 \gset
\if :gate_pg_wal_009
\echo '@@CHECK PG-WAL-009'
-- check: PG-WAL-009
-- title: Slow checkpoint sync phase
-- priority: 100
-- scope: cluster
-- cost: 0
-- run_on: primary
-- thresholds: sync_ms, min_checkpoints
-- PostgreSQL 17 renamed checkpoint_write_time/checkpoint_sync_time to
-- write_time/sync_time and moved them to pg_stat_checkpointer.
\set ON_ERROR_STOP off
SELECT (current_setting('server_version_num')::int >= 170000) AS pg_wal_009_pg17 \gset
WITH c AS (
\if :pg_wal_009_pg17
  SELECT num_timed + num_requested AS checkpoints,
         write_time::numeric AS write_time, sync_time::numeric AS sync_time, stats_reset
  FROM pg_stat_checkpointer
\else
  SELECT checkpoints_timed + checkpoints_req AS checkpoints,
         checkpoint_write_time::numeric AS write_time, checkpoint_sync_time::numeric AS sync_time, stats_reset
  FROM pg_stat_bgwriter
\endif
)
SELECT 'PG-WAL-009'::text     AS check_id,
       'cluster'::text        AS scope,
       'checkpoint sync'::text AS object,
       format('Checkpoints spend an average of %s ms in the sync phase (threshold %s ms) across %s checkpoints since %s, against %s ms average in the write phase. The sync phase is the fsync of every file the checkpoint dirtied; a long one is storage fsync latency, and it blocks the checkpoint from completing while WAL keeps accumulating. Total sync time %s ms.',
              round(c.sync_time / nullif(c.checkpoints, 0), 1)::text,
              :'pg_wal_009_sync_ms'::text,
              to_char(c.checkpoints, 'FM999,999,999'),
              coalesce(c.stats_reset::text, 'the last statistics reset'),
              round(c.write_time / nullif(c.checkpoints, 0), 1)::text,
              to_char(c.sync_time, 'FM999,999,999,999')) AS details,
       json_build_object('checkpoints', c.checkpoints,
                         'avg_sync_ms', round(c.sync_time / nullif(c.checkpoints, 0), 2),
                         'avg_write_ms', round(c.write_time / nullif(c.checkpoints, 0), 2),
                         'total_sync_ms', c.sync_time, 'total_write_ms', c.write_time,
                         'threshold_ms', :'pg_wal_009_sync_ms'::numeric,
                         'stats_reset', c.stats_reset)::text AS evidence_json,
       'medium'::text AS confidence
FROM c
WHERE NOT pg_is_in_recovery()
  AND c.checkpoints >= :'pg_wal_009_min_checkpoints'::int
  AND c.sync_time / nullif(c.checkpoints, 0) >= :'pg_wal_009_sync_ms'::numeric;
\echo '@@END PG-WAL-009'
\else
\echo '@@SKIP PG-WAL-009 primary only'
\endif

-- ======== PG-WRAP-008  P100  vacuum_failsafe_age raised above the default ========
SELECT (current_setting('server_version_num')::int >= 140000) AS gate_pg_wrap_008 \gset
\if :gate_pg_wrap_008
\echo '@@CHECK PG-WRAP-008'
-- check: PG-WRAP-008
-- title: vacuum_failsafe_age raised above the default
-- priority: 100
-- scope: setting
-- cost: 0
-- min_version: 14
-- thresholds: failsafe_age
SELECT 'PG-WRAP-008'::text AS check_id,
       'setting'::text     AS scope,
       s.name::text        AS object,
       format('%s = %s (default %s, threshold %s), set in %s. The failsafe is what makes a vacuum abandon cost delays and index cleanup so it can finish before wraparound; raising it delays that last automatic defence by %s XIDs.',
              s.name, to_char(s.setting::bigint, 'FM999,999,999,999'),
              to_char(s.boot_val::bigint, 'FM999,999,999,999'),
              to_char(:'pg_wrap_008_failsafe_age'::bigint, 'FM999,999,999,999'),
              s.source,
              to_char(s.setting::bigint - s.boot_val::bigint, 'FM999,999,999,999')) AS details,
       json_build_object('setting', s.name, 'value', s.setting::bigint, 'default', s.boot_val::bigint,
                         'source', s.source, 'threshold', :'pg_wrap_008_failsafe_age'::bigint)::text AS evidence_json,
       'high'::text AS confidence
FROM pg_settings s
WHERE s.name IN ('vacuum_failsafe_age', 'vacuum_multixact_failsafe_age')
  AND s.setting::bigint > :'pg_wrap_008_failsafe_age'::bigint;
\echo '@@END PG-WRAP-008'
\else
\echo '@@SKIP PG-WRAP-008 needs PostgreSQL 14 or newer'
\endif

-- ======== PG-CAP-007  P150  Log directory large ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_cap_007 \gset
\if :gate_pg_cap_007
\echo '@@CHECK PG-CAP-007'
-- check: PG-CAP-007
-- title: Log directory large
-- priority: 150
-- scope: cluster
-- cost: 1
-- min_version: 10
-- thresholds: min_bytes
\set ON_ERROR_STOP off
-- pg_ls_logdir() raises if log_directory does not exist, which is the normal state
-- when logging_collector is off (logs go to stderr / the OS journal). Gate on it.
SELECT (current_setting('logging_collector') = 'on') AS pg_cap_007_has_logdir \gset
\if :pg_cap_007_has_logdir
WITH l AS (SELECT sum(size)::bigint AS bytes, count(*) AS files,
                  min(modification) AS oldest, max(modification) AS newest FROM pg_ls_logdir())
SELECT 'PG-CAP-007'::text AS check_id,
       'cluster'::text    AS scope,
       'log_directory'::text AS object,
       format('The log directory holds %s across %s files (threshold %s), spanning %s to %s. On most installations the logs share a volume with the data directory, so this is disk the database cannot use (PG-CAP-001/002). Rotation and retention settings: log_rotation_age = %s, log_rotation_size = %s, log_truncate_on_rotation = %s, log_filename = %s. Volume drivers: log_min_duration_statement = %s, log_statement = %s, log_connections = %s.',
              pg_size_pretty(l.bytes), l.files, pg_size_pretty(:'pg_cap_007_min_bytes'::bigint),
              coalesce(l.oldest::text, 'unknown'), coalesce(l.newest::text, 'unknown'),
              current_setting('log_rotation_age'), current_setting('log_rotation_size'),
              current_setting('log_truncate_on_rotation'), current_setting('log_filename'),
              current_setting('log_min_duration_statement'), current_setting('log_statement'),
              current_setting('log_connections')) AS details,
       json_build_object('log_bytes', l.bytes, 'log_files', l.files,
                         'oldest', l.oldest, 'newest', l.newest,
                         'threshold_bytes', :'pg_cap_007_min_bytes'::bigint,
                         'log_rotation_age', current_setting('log_rotation_age'),
                         'log_rotation_size', current_setting('log_rotation_size'),
                         'log_truncate_on_rotation', current_setting('log_truncate_on_rotation'),
                         'log_min_duration_statement', current_setting('log_min_duration_statement'),
                         'log_statement', current_setting('log_statement'))::text AS evidence_json,
       'high'::text AS confidence
FROM l
WHERE l.bytes >= :'pg_cap_007_min_bytes'::bigint;
\endif
\echo '@@END PG-CAP-007'
\else
\echo '@@SKIP PG-CAP-007 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-CONN-007  P150  statement_timeout unset globally ========
\echo '@@CHECK PG-CONN-007'
-- check: PG-CONN-007
-- title: statement_timeout unset globally
-- priority: 150
-- scope: setting
-- cost: 0
SELECT 'PG-CONN-007'::text        AS check_id,
       'setting'::text            AS scope,
       'statement_timeout'::text  AS object,
       format('statement_timeout = 0 (no limit) at server level, and no per-database or per-role override sets one (%s override(s) exist in pg_db_role_setting, none for statement_timeout). Any statement can run until it finishes or the client goes away, holding its snapshot and its locks the whole time - which is how one bad query becomes PG-LOCK-001 and PG-VAC-005. Set it per application role (ALTER ROLE app SET statement_timeout = ...) rather than globally, so that migrations, backups and maintenance sessions are not cut off. idle_in_transaction_session_timeout = %s, lock_timeout = %s.',
              (SELECT count(*) FROM pg_db_role_setting),
              current_setting('idle_in_transaction_session_timeout'),
              current_setting('lock_timeout')) AS details,
       json_build_object('statement_timeout', '0',
                         'db_role_settings_total', (SELECT count(*) FROM pg_db_role_setting),
                         'idle_in_transaction_session_timeout', current_setting('idle_in_transaction_session_timeout'),
                         'lock_timeout', current_setting('lock_timeout'))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_settings s
WHERE s.name = 'statement_timeout' AND s.reset_val = '0'
  AND NOT EXISTS (SELECT 1 FROM pg_db_role_setting r
                  WHERE array_to_string(r.setconfig, ' ') LIKE '%statement_timeout%');
\echo '@@END PG-CONN-007'

-- ======== PG-DUR-006  P150  wal_sync_method changed from the platform default ========
\echo '@@CHECK PG-DUR-006'
-- check: PG-DUR-006
-- title: wal_sync_method changed from the platform default
-- priority: 150
-- scope: setting
-- cost: 0
SELECT 'PG-DUR-006'::text         AS check_id,
       'setting'::text            AS scope,
       'wal_sync_method'::text    AS object,
       format('wal_sync_method = %s, changed from the platform default of %s (set in %s%s). PostgreSQL picks the fastest method its build detected as safe on this platform; overriding it is occasionally right for a specific storage stack and is more often a copied setting whose original justification is gone. fsync = %s.',
              s.setting, s.boot_val, s.source,
              coalesce(', ' || s.sourcefile || ':' || s.sourceline::text, ''),
              current_setting('fsync')) AS details,
       json_build_object('wal_sync_method', s.setting, 'default', s.boot_val,
                         'source', s.source, 'sourcefile', s.sourcefile,
                         'fsync', current_setting('fsync'))::text AS evidence_json,
       'medium'::text AS confidence
FROM pg_settings s
WHERE s.name = 'wal_sync_method' AND s.source <> 'default' AND s.setting IS DISTINCT FROM s.boot_val;
\echo '@@END PG-DUR-006'

-- ======== PG-LOCK-008  P150  Deadlocks occurring regularly ========
\echo '@@CHECK PG-LOCK-008'
-- check: PG-LOCK-008
-- title: Deadlocks occurring regularly
-- priority: 150
-- scope: database
-- cost: 0
-- thresholds: deadlocks_per_day, min_deadlocks
WITH w AS (
  SELECT d.datname, d.deadlocks, d.stats_reset,
         greatest(extract(epoch FROM now() - coalesce(d.stats_reset, pg_postmaster_start_time())) / 86400.0, 0.01) AS days
  FROM pg_stat_database d WHERE d.datname IS NOT NULL
)
SELECT 'PG-LOCK-008'::text AS check_id,
       'database'::text    AS scope,
       w.datname::text     AS object,
       format('%s deadlocks in database %s over %s days (%s per day, thresholds %s per day and %s total), counted since %s. A deadlock is always an application lock-ordering bug: two transactions took the same locks in different orders and PostgreSQL killed one of them. The victim gets an error, so the cost is user-visible even though the server is fine. log_lock_waits = %s and deadlock_timeout = %s control whether the server logs the graph you need to find the pair of statements.',
              to_char(w.deadlocks, 'FM999,999,999'), w.datname, round(w.days, 1)::text,
              round(w.deadlocks / w.days, 2)::text,
              :'pg_lock_008_deadlocks_per_day'::text, :'pg_lock_008_min_deadlocks'::text,
              coalesce(w.stats_reset::text, 'the last statistics reset'),
              current_setting('log_lock_waits'), current_setting('deadlock_timeout')) AS details,
       json_build_object('datname', w.datname, 'deadlocks', w.deadlocks,
                         'window_days', round(w.days, 2),
                         'deadlocks_per_day', round(w.deadlocks / w.days, 3),
                         'threshold_per_day', :'pg_lock_008_deadlocks_per_day'::numeric,
                         'threshold_total', :'pg_lock_008_min_deadlocks'::bigint,
                         'stats_reset', w.stats_reset,
                         'log_lock_waits', current_setting('log_lock_waits'),
                         'deadlock_timeout', current_setting('deadlock_timeout'))::text AS evidence_json,
       'medium'::text AS confidence
FROM w
WHERE w.deadlocks >= :'pg_lock_008_min_deadlocks'::bigint
  AND w.deadlocks / w.days >= :'pg_lock_008_deadlocks_per_day'::numeric
ORDER BY w.deadlocks DESC;
\echo '@@END PG-LOCK-008'

-- ======== PG-LOCK-009  P150  lock_timeout unset ========
\echo '@@CHECK PG-LOCK-009'
-- check: PG-LOCK-009
-- title: lock_timeout unset
-- priority: 150
-- scope: setting
-- cost: 0
SELECT 'PG-LOCK-009'::text     AS check_id,
       'setting'::text         AS scope,
       'lock_timeout'::text    AS object,
       format('lock_timeout = 0 at server level. A statement that needs a lock waits for it forever - and while an ALTER TABLE waits for its ACCESS EXCLUSIVE lock, every subsequent statement against the same table queues behind the waiting ALTER, including plain SELECTs. That is how a routine migration behind one long transaction (PG-LOCK-005) becomes a total outage on a hot table. Setting lock_timeout to a few seconds in migration sessions makes the migration fail instead of the application. statement_timeout = %s, deadlock_timeout = %s, log_lock_waits = %s.',
              current_setting('statement_timeout'),
              current_setting('deadlock_timeout'),
              current_setting('log_lock_waits')) AS details,
       json_build_object('lock_timeout', '0',
                         'statement_timeout', current_setting('statement_timeout'),
                         'deadlock_timeout', current_setting('deadlock_timeout'),
                         'log_lock_waits', current_setting('log_lock_waits'),
                         'db_role_overrides', (SELECT count(*) FROM pg_db_role_setting r
                                               WHERE array_to_string(r.setconfig, ' ') LIKE '%lock_timeout%'))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_settings s
WHERE s.name = 'lock_timeout' AND s.reset_val = '0';
\echo '@@END PG-LOCK-009'

-- ======== PG-MEM-007  P150  random_page_cost at the spinning-disk default ========
\echo '@@CHECK PG-MEM-007'
-- check: PG-MEM-007
-- title: random_page_cost at the spinning-disk default
-- priority: 150
-- scope: setting
-- cost: 0
-- thresholds: storage_class
-- storage_class comes from .db-triage.yml baseline.storage: hdd|ssd|nvme|cloud|unknown.
SELECT 'PG-MEM-007'::text          AS check_id,
       'setting'::text             AS scope,
       'random_page_cost'::text    AS object,
       format('random_page_cost = %s (the default), seq_page_cost = %s, with baseline.storage = %s. The 4:1 ratio models a spinning disk where a random seek costs four sequential reads. On SSD, NVMe and cloud block storage the real ratio is close to 1, and leaving it at 4 makes the planner prefer sequential scans over index scans on exactly the queries where an index would win. 1.1 for local NVMe and 1.1 to 2.0 for cloud volumes are the common settings. %s',
              s.setting,
              (SELECT setting FROM pg_settings WHERE name = 'seq_page_cost'),
              :'pg_mem_007_storage_class'::text,
              CASE WHEN :'pg_mem_007_storage_class' = 'unknown'
                   THEN 'Storage type was not supplied, so this is a guess: set baseline.storage in .db-triage.yml to confirm or silence it.'
                   ELSE '' END) AS details,
       json_build_object('random_page_cost', s.setting::numeric,
                         'seq_page_cost', (SELECT setting::numeric FROM pg_settings WHERE name = 'seq_page_cost'),
                         'source', s.source, 'storage_class', :'pg_mem_007_storage_class'::text,
                         'effective_cache_size', current_setting('effective_cache_size'))::text AS evidence_json,
       CASE WHEN :'pg_mem_007_storage_class' = 'unknown' THEN 'low' ELSE 'medium' END::text AS confidence
FROM pg_settings s
WHERE s.name = 'random_page_cost'
  AND s.setting::numeric = 4
  AND :'pg_mem_007_storage_class' IN ('ssd', 'nvme', 'cloud', 'unknown');
\echo '@@END PG-MEM-007'

-- ======== PG-MEM-010  P150  Buffer cache hit ratio below 90 percent ========
\echo '@@CHECK PG-MEM-010'
-- check: PG-MEM-010
-- title: Buffer cache hit ratio below 90 percent
-- priority: 150
-- scope: database
-- cost: 0
-- thresholds: hit_ratio, min_reads
SELECT 'PG-MEM-010'::text AS check_id,
       'database'::text   AS scope,
       d.datname::text    AS object,
       format('Buffer cache hit ratio %s%% in database %s (threshold %s%%): %s blocks found in shared_buffers against %s read from outside it, since %s. "Read from outside" includes blocks served by the operating-system page cache, which this counter cannot distinguish from a real disk read, so a low ratio on a host with plenty of free memory may cost nothing at all. Read this next to PG-MEM-001 and PG-MEM-002 rather than as a target to tune towards. shared_buffers = %s, database size %s.',
              round(100.0 * d.blks_hit / nullif(d.blks_hit + d.blks_read, 0), 1)::text,
              d.datname, round(100 * :'pg_mem_010_hit_ratio'::numeric)::text,
              to_char(d.blks_hit, 'FM999,999,999,999'), to_char(d.blks_read, 'FM999,999,999,999'),
              coalesce(d.stats_reset::text, 'the last statistics reset'),
              current_setting('shared_buffers'),
              pg_size_pretty(pg_database_size(d.datname))) AS details,
       json_build_object('datname', d.datname, 'blks_hit', d.blks_hit, 'blks_read', d.blks_read,
                         'hit_ratio', round(d.blks_hit::numeric / nullif(d.blks_hit + d.blks_read, 0), 4),
                         'threshold_ratio', :'pg_mem_010_hit_ratio'::numeric,
                         'threshold_min_reads', :'pg_mem_010_min_reads'::bigint,
                         'stats_reset', d.stats_reset,
                         'database_bytes', pg_database_size(d.datname))::text AS evidence_json,
       'low'::text AS confidence
FROM pg_stat_database d
WHERE d.datname IS NOT NULL
  AND d.blks_read >= :'pg_mem_010_min_reads'::bigint
  AND d.blks_hit::numeric / nullif(d.blks_hit + d.blks_read, 0) < :'pg_mem_010_hit_ratio'::numeric
ORDER BY d.blks_read DESC;
\echo '@@END PG-MEM-010'

-- ======== PG-QRY-002  P150  pg_stat_statements evicting entries ========
SELECT (current_setting('server_version_num')::int >= 140000) AS gate_pg_qry_002 \gset
\if :gate_pg_qry_002
\echo '@@CHECK PG-QRY-002'
-- check: PG-QRY-002
-- title: pg_stat_statements evicting entries
-- priority: 150
-- scope: database
-- cost: 0
-- min_version: 14
-- thresholds: min_dealloc, dealloc_per_day
\set ON_ERROR_STOP off
SELECT (to_regclass('pg_stat_statements_info') IS NOT NULL) AS pg_qry_002_has_info \gset
\if :pg_qry_002_has_info
WITH w AS (
  SELECT i.dealloc, i.stats_reset,
         greatest(extract(epoch FROM now() - coalesce(i.stats_reset, pg_postmaster_start_time())) / 86400.0, 0.01) AS days
  FROM pg_stat_statements_info i
)
SELECT 'PG-QRY-002'::text AS check_id,
       'database'::text   AS scope,
       'pg_stat_statements'::text AS object,
       format('pg_stat_statements has evicted entries %s times since %s (%s per day; thresholds %s total, %s per day). pg_stat_statements.max is %s and the hash currently holds %s entries. Eviction discards the least-executed half of the table, so any "top 10 by total time" list is missing whatever was evicted, and the totals it is a percentage of are wrong too. Raising pg_stat_statements.max requires a restart. High eviction usually means unparameterised SQL: each literal produces a distinct queryid.',
              to_char(w.dealloc, 'FM999,999,999,999'),
              coalesce(w.stats_reset::text, 'the last reset'),
              round(w.dealloc / w.days, 1)::text,
              to_char(:'pg_qry_002_min_dealloc'::bigint, 'FM999,999,999,999'),
              :'pg_qry_002_dealloc_per_day'::text,
              current_setting('pg_stat_statements.max'),
              to_char((SELECT count(*) FROM pg_stat_statements), 'FM999,999,999,999')) AS details,
       json_build_object('dealloc', w.dealloc, 'stats_reset', w.stats_reset,
                         'window_days', round(w.days, 2),
                         'dealloc_per_day', round(w.dealloc / w.days, 2),
                         'threshold_total', :'pg_qry_002_min_dealloc'::bigint,
                         'threshold_per_day', :'pg_qry_002_dealloc_per_day'::numeric,
                         'pgss_max', current_setting('pg_stat_statements.max')::int,
                         'current_entries', (SELECT count(*) FROM pg_stat_statements))::text AS evidence_json,
       'high'::text AS confidence
FROM w
WHERE w.dealloc >= :'pg_qry_002_min_dealloc'::bigint
   OR w.dealloc / w.days >= :'pg_qry_002_dealloc_per_day'::numeric;
\endif
\echo '@@END PG-QRY-002'
\else
\echo '@@SKIP PG-QRY-002 needs PostgreSQL 14 or newer'
\endif

-- ======== PG-QRY-012  P150  track_io_timing disabled ========
\echo '@@CHECK PG-QRY-012'
-- check: PG-QRY-012
-- title: track_io_timing disabled
-- priority: 150
-- scope: setting
-- cost: 0
SELECT 'PG-QRY-012'::text        AS check_id,
       'setting'::text           AS scope,
       'track_io_timing'::text   AS object,
       format('track_io_timing = off (source %s). Every I/O-time column is therefore zero: blk_read_time and blk_write_time in pg_stat_database, the corresponding columns in pg_stat_statements, and the "I/O Timings" line in EXPLAIN (ANALYZE, BUFFERS). Without them there is no way to tell a query that is slow because it is waiting on storage from one that is slow because it is burning CPU, which is the first fork in any performance investigation. Measure the cost on this host with pg_test_timing before enabling it; on modern hardware with a TSC clocksource it is a few nanoseconds per call. track_functions = %s, track_activities = %s.',
              s.source, current_setting('track_functions'), current_setting('track_activities')) AS details,
       json_build_object('track_io_timing', s.setting, 'source', s.source,
                         'track_functions', current_setting('track_functions'),
                         'track_activities', current_setting('track_activities'),
                         'pgss_installed', EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_stat_statements'))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_settings s
WHERE s.name = 'track_io_timing' AND s.setting = 'off';
\echo '@@END PG-QRY-012'

-- ======== PG-QRY-015  P150  compute_query_id off ========
SELECT (current_setting('server_version_num')::int >= 140000) AS gate_pg_qry_015 \gset
\if :gate_pg_qry_015
\echo '@@CHECK PG-QRY-015'
-- check: PG-QRY-015
-- title: compute_query_id off
-- priority: 150
-- scope: setting
-- cost: 0
-- min_version: 14
SELECT 'PG-QRY-015'::text          AS check_id,
       'setting'::text             AS scope,
       'compute_query_id'::text    AS object,
       format('compute_query_id = %s and no query-id provider is active, so pg_stat_activity.query_id is null and %%Q in log_line_prefix produces nothing. Without a query id there is no way to join a slow line in the log, or a session seen in pg_stat_activity, to its row in pg_stat_statements: every correlation has to be done by matching query text by hand. On "auto" the id is computed only when an extension asks for it; pg_stat_statements does ask, so "auto" is enough when it is loaded - here it is %s. Setting it to "on" costs one hash per parse. log_line_prefix = %s.',
              s.setting,
              CASE WHEN current_setting('shared_preload_libraries') LIKE '%pg_stat_statements%'
                   THEN 'loaded' ELSE 'not loaded' END,
              quote_literal(current_setting('log_line_prefix'))) AS details,
       json_build_object('compute_query_id', s.setting, 'source', s.source,
                         'pgss_preloaded', current_setting('shared_preload_libraries') LIKE '%pg_stat_statements%',
                         'log_line_prefix', current_setting('log_line_prefix'))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_settings s
WHERE s.name = 'compute_query_id'
  AND (s.setting = 'off'
       OR (s.setting = 'auto' AND current_setting('shared_preload_libraries') NOT LIKE '%pg_stat_statements%'));
\echo '@@END PG-QRY-015'
\else
\echo '@@SKIP PG-QRY-015 needs PostgreSQL 14 or newer'
\endif

-- ======== PG-REL-007  P150  Diagnostic logging off ========
\echo '@@CHECK PG-REL-007'
-- check: PG-REL-007
-- title: Diagnostic logging off
-- priority: 150
-- scope: setting
-- cost: 0
WITH gaps AS (
  SELECT array_remove(ARRAY[
    CASE WHEN current_setting('log_checkpoints') = 'off'
         THEN 'log_checkpoints = off (no record of when checkpoints ran, how long they took, or how many buffers they wrote - the default before PostgreSQL 15)' END,
    CASE WHEN current_setting('log_lock_waits') = 'off'
         THEN 'log_lock_waits = off (a session that waits longer than deadlock_timeout for a lock is never logged, so blocking chains leave no trace after the fact)' END,
    CASE WHEN (SELECT setting::int FROM pg_settings WHERE name = 'log_autovacuum_min_duration') = -1
         THEN 'log_autovacuum_min_duration = -1 (no autovacuum run is ever logged, so there is no way to see which tables it works on or how long it takes)' END,
    CASE WHEN (SELECT setting::int FROM pg_settings WHERE name = 'log_temp_files') = -1
         THEN 'log_temp_files = -1 (temp-file spills are counted in pg_stat_database but never attributed to a statement in the log)' END,
    CASE WHEN current_setting('log_line_prefix') NOT LIKE '%\%m%'
         THEN 'log_line_prefix has no %m (log lines carry no timestamp)' END,
    CASE WHEN current_setting('log_line_prefix') NOT LIKE '%\%p%'
         THEN 'log_line_prefix has no %p (log lines carry no process id, so lines from one session cannot be grouped)' END
  ], NULL) AS missing
)
SELECT 'PG-REL-007'::text AS check_id,
       'setting'::text    AS scope,
       'logging'::text    AS object,
       format('%s diagnostic logging setting(s) leave a gap: %s. None of these costs measurable performance; each one is evidence that will not exist the next time something goes wrong at 3am. Current log_line_prefix: %s.',
              cardinality(g.missing),
              array_to_string(g.missing, '; '),
              quote_literal(current_setting('log_line_prefix'))) AS details,
       json_build_object('missing', array_to_string(g.missing, ';'),
                         'log_checkpoints', current_setting('log_checkpoints'),
                         'log_lock_waits', current_setting('log_lock_waits'),
                         'log_autovacuum_min_duration', current_setting('log_autovacuum_min_duration'),
                         'log_temp_files', current_setting('log_temp_files'),
                         'log_line_prefix', current_setting('log_line_prefix'))::text AS evidence_json,
       'high'::text AS confidence
FROM gaps g
WHERE cardinality(g.missing) > 0;
\echo '@@END PG-REL-007'

-- ======== PG-REL-008  P150  Extension updates available ========
\echo '@@CHECK PG-REL-008'
-- check: PG-REL-008
-- title: Extension updates available
-- priority: 150
-- scope: database
-- cost: 0
SELECT 'PG-REL-008'::text AS check_id,
       'database'::text   AS scope,
       format('%I.extension:%s', current_database(), e.extname)::text AS object,
       format('Extension %s is installed at version %s in database %s while the files on this server provide %s. The binary and the SQL objects are therefore out of step: the shared library has been upgraded (usually by a package update) but ALTER EXTENSION %s UPDATE was never run, so any function signature, view or default that changed between the two versions is still the old one. That is where "the extension worked yesterday" comes from after a routine package upgrade. Schema %s, owner %s.',
              e.extname, e.extversion, current_database(), a.default_version,
              quote_ident(e.extname), n.nspname, pg_get_userbyid(e.extowner)) AS details,
       json_build_object('extname', e.extname, 'installed_version', e.extversion,
                         'default_version', a.default_version,
                         'schema', n.nspname, 'owner', pg_get_userbyid(e.extowner),
                         'database', current_database())::text AS evidence_json,
       'high'::text AS confidence
FROM pg_extension e
JOIN pg_available_extensions a ON a.name = e.extname
JOIN pg_namespace n            ON n.oid = e.extnamespace
WHERE a.default_version IS DISTINCT FROM e.extversion
ORDER BY e.extname;
\echo '@@END PG-REL-008'

-- ======== PG-REL-013  P150  Logging collector off with a stderr-only destination ========
\echo '@@CHECK PG-REL-013'
-- check: PG-REL-013
-- title: Logging collector off with a stderr-only destination
-- priority: 150
-- scope: setting
-- cost: 0
SELECT 'PG-REL-013'::text            AS check_id,
       'setting'::text               AS scope,
       'logging_collector'::text     AS object,
       format('logging_collector = off with log_destination = %s. The server writes its log to the standard error it was started with and does nothing else: where that goes depends entirely on how the server was launched. Under systemd it reaches the journal; under a container runtime it reaches the container log; started by hand from a shell that has since closed, it goes nowhere and is unrecoverable. Confidence is low because db-triage cannot see the process supervisor from inside SQL - confirm where stderr points before treating this as a defect. Consequences if it is going nowhere: PG-CORR-005, PG-REL-011 and PG-REL-014 have nothing to read, and neither will you. log_min_duration_statement = %s, log_checkpoints = %s.',
              current_setting('log_destination'),
              current_setting('log_min_duration_statement'),
              current_setting('log_checkpoints')) AS details,
       json_build_object('logging_collector', 'off',
                         'log_destination', current_setting('log_destination'),
                         'log_directory', current_setting('log_directory'),
                         'log_min_duration_statement', current_setting('log_min_duration_statement'))::text AS evidence_json,
       'low'::text AS confidence
WHERE current_setting('logging_collector') = 'off'
  AND current_setting('log_destination') = 'stderr';
\echo '@@END PG-REL-013'

-- ======== PG-REPL-016  P150  hot_standby_feedback on with long-running standby queries ========
SELECT (pg_is_in_recovery()) AS gate_pg_repl_016 \gset
\if :gate_pg_repl_016
\echo '@@CHECK PG-REPL-016'
-- check: PG-REPL-016
-- title: hot_standby_feedback on with long-running standby queries
-- priority: 150
-- scope: cluster
-- cost: 0
-- run_on: standby
-- thresholds: query_seconds
SELECT 'PG-REPL-016'::text AS check_id,
       'cluster'::text     AS scope,
       ('pid:' || a.pid)::text AS object,
       format('hot_standby_feedback = on and pid %s (%s / %s) has been running a query for %s (threshold %s). While that query runs, this standby reports its oldest xmin back to the primary, which stops the primary from vacuuming anything newer: the cost of not cancelling this query is bloat and a rising xmin horizon on the primary (PG-VAC-005 there, not here). Query: %s',
              a.pid, coalesce(nullif(a.usename, ''), '?'), coalesce(nullif(a.application_name, ''), 'no application_name'),
              justify_interval(date_trunc('second', now() - a.query_start)),
              (:'pg_repl_016_query_seconds'::int || ' seconds')::interval,
              left(regexp_replace(coalesce(a.query, ''), '\s+', ' ', 'g'), 200)) AS details,
       json_build_object('pid', a.pid, 'usename', a.usename, 'application_name', a.application_name,
                         'query_seconds', round(extract(epoch FROM now() - a.query_start))::bigint,
                         'threshold_seconds', :'pg_repl_016_query_seconds'::int,
                         'backend_xmin_age', CASE WHEN a.backend_xmin IS NULL THEN NULL ELSE age(a.backend_xmin) END,
                         'hot_standby_feedback', current_setting('hot_standby_feedback'),
                         'client_addr', host(a.client_addr))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_stat_activity a
WHERE pg_is_in_recovery()
  AND current_setting('hot_standby_feedback') = 'on'
  AND a.state = 'active' AND a.backend_type = 'client backend'
  AND a.query_start IS NOT NULL
  AND now() - a.query_start >= (:'pg_repl_016_query_seconds'::int || ' seconds')::interval
ORDER BY a.query_start;
\echo '@@END PG-REPL-016'
\else
\echo '@@SKIP PG-REPL-016 standby only'
\endif

-- ======== PG-SCHEMA-010  P150  Database with more than 10,000 relations ========
\echo '@@CHECK PG-SCHEMA-010'
-- check: PG-SCHEMA-010
-- title: Database with more than 10,000 relations
-- priority: 150
-- scope: database
-- cost: 1
-- thresholds: max_relations
SELECT 'PG-SCHEMA-010'::text  AS check_id,
       'database'::text       AS scope,
       current_database()::text AS object,
       format('Database %s contains %s entries in pg_class (threshold %s): %s tables, %s indexes, %s toast tables, %s partitions, %s views and materialized views, %s sequences, across %s schemas. Every one is a catalog row that autovacuum has to consider on each cycle, that relcache has to hold per backend, and that information_schema has to walk. Past this scale, autovacuum scheduling latency, connection startup cost and catalog bloat all become visible. Frequently the cause is one schema per tenant or per customer.',
              current_database(), c.total, :'pg_schema_010_max_relations'::text,
              c.tables, c.indexes, c.toast, c.partitions, c.views, c.sequences,
              (SELECT count(*) FROM pg_namespace WHERE nspname NOT LIKE 'pg_%' AND nspname <> 'information_schema')) AS details,
       json_build_object('database', current_database(), 'pg_class_rows', c.total,
                         'tables', c.tables, 'indexes', c.indexes, 'toast_tables', c.toast,
                         'partitions', c.partitions, 'views', c.views, 'sequences', c.sequences,
                         'schemas', (SELECT count(*) FROM pg_namespace
                                     WHERE nspname NOT LIKE 'pg_%' AND nspname <> 'information_schema'),
                         'threshold', :'pg_schema_010_max_relations'::int)::text AS evidence_json,
       'high'::text AS confidence
FROM (
  SELECT count(*) AS total,
         count(*) FILTER (WHERE relkind IN ('r', 'p')) AS tables,
         count(*) FILTER (WHERE relkind = 'i')         AS indexes,
         count(*) FILTER (WHERE relkind = 't')         AS toast,
         count(*) FILTER (WHERE relispartition)        AS partitions,
         count(*) FILTER (WHERE relkind IN ('v', 'm')) AS views,
         count(*) FILTER (WHERE relkind = 'S')         AS sequences
  FROM pg_class
) c
WHERE c.total >= :'pg_schema_010_max_relations'::int;
\echo '@@END PG-SCHEMA-010'

-- ======== PG-SEC-017  P150  Untrusted procedural languages or risky extensions installed ========
\echo '@@CHECK PG-SEC-017'
-- check: PG-SEC-017
-- title: Untrusted procedural languages or risky extensions installed
-- priority: 150
-- scope: database
-- cost: 0
SELECT 'PG-SEC-017'::text AS check_id,
       'database'::text   AS scope,
       format('%I.language:%s', current_database(), l.lanname)::text AS object,
       format('Untrusted procedural language %s is installed in database %s. Code written in an untrusted language runs as the operating-system account that owns the server, outside every SQL permission check: it can read and write files, open sockets and run programs. Only superusers can create functions in it by default, so this is a review row rather than a defect - confirm that %s function(s) in this language are all ones you meant to have. EXECUTE on the language handler is granted to: %s.',
              l.lanname, current_database(),
              (SELECT count(*) FROM pg_proc p WHERE p.prolang = l.oid),
              coalesce(array_to_string(l.lanacl, ', '), 'superusers only (no explicit ACL)')) AS details,
       json_build_object('kind', 'language', 'lanname', l.lanname,
                         'function_count', (SELECT count(*) FROM pg_proc p WHERE p.prolang = l.oid),
                         'lanacl', array_to_string(l.lanacl, ';'))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_language l
WHERE NOT l.lanpltrusted AND l.lanispl;

SELECT 'PG-SEC-017'::text AS check_id,
       'database'::text   AS scope,
       format('%I.extension:%s', current_database(), e.extname)::text AS object,
       format('Extension %s (version %s, schema %s) is installed in database %s. %s Confirm it is still needed and that EXECUTE on its functions is not held by PUBLIC.',
              e.extname, e.extversion, n.nspname, current_database(),
              CASE e.extname
                WHEN 'file_fdw'  THEN 'file_fdw reads arbitrary files on the server host as the server account and exposes them as tables.'
                WHEN 'adminpack' THEN 'adminpack lets a client write and read files in the data directory over a normal SQL connection.'
                WHEN 'dblink'    THEN 'dblink opens outbound connections from the server; if EXECUTE is held by PUBLIC it can be used to reach services the client cannot reach directly, and to authenticate as the server to local trust rules.'
                WHEN 'postgres_fdw' THEN 'postgres_fdw opens outbound connections from the server to other PostgreSQL servers using credentials stored in user mappings.'
                ELSE 'Review its capabilities against who can execute it.' END) AS details,
       json_build_object('kind', 'extension', 'extname', e.extname, 'extversion', e.extversion,
                         'schema', n.nspname, 'owner', pg_get_userbyid(e.extowner))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_extension e
JOIN pg_namespace n ON n.oid = e.extnamespace
WHERE e.extname IN ('adminpack', 'file_fdw', 'dblink', 'postgres_fdw');
\echo '@@END PG-SEC-017'

-- ======== PG-WAL-003  P150  checkpoint_completion_target below 0.9 ========
\echo '@@CHECK PG-WAL-003'
-- check: PG-WAL-003
-- title: checkpoint_completion_target below 0.9
-- priority: 150
-- scope: setting
-- cost: 0
-- thresholds: target
SELECT 'PG-WAL-003'::text                 AS check_id,
       'setting'::text                    AS scope,
       'checkpoint_completion_target'::text AS object,
       format('checkpoint_completion_target = %s (threshold %s, default on this version %s), set in %s. The checkpointer spreads its writes over that fraction of the checkpoint interval; at %s it compresses the same dirty pages into the first %s%% of %s, which shows up as a periodic latency spike. 0.9 spreads them and is the default from PostgreSQL 14 onward.',
              s.setting, :'pg_wal_003_target'::text, s.boot_val, s.source,
              s.setting, round(100 * s.setting::numeric)::text,
              current_setting('checkpoint_timeout')) AS details,
       json_build_object('checkpoint_completion_target', s.setting::numeric,
                         'default', s.boot_val::numeric, 'threshold', :'pg_wal_003_target'::numeric,
                         'source', s.source,
                         'checkpoint_timeout', current_setting('checkpoint_timeout'))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_settings s
WHERE s.name = 'checkpoint_completion_target'
  AND s.setting::numeric < :'pg_wal_003_target'::numeric;
\echo '@@END PG-WAL-003'

-- ======== PG-WAL-005  P150  Background writer hitting its per-round limit ========
SELECT (NOT pg_is_in_recovery()) AS gate_pg_wal_005 \gset
\if :gate_pg_wal_005
\echo '@@CHECK PG-WAL-005'
-- check: PG-WAL-005
-- title: Background writer hitting its per-round limit
-- priority: 150
-- scope: cluster
-- cost: 0
-- run_on: primary
-- thresholds: maxwritten_per_day
WITH win AS (
  SELECT b.maxwritten_clean, b.buffers_clean, b.buffers_alloc, b.stats_reset,
         greatest(extract(epoch FROM now() - coalesce(b.stats_reset, pg_postmaster_start_time())) / 86400.0, 0.01) AS days
  FROM pg_stat_bgwriter b
)
SELECT 'PG-WAL-005'::text          AS check_id,
       'cluster'::text             AS scope,
       'bgwriter_lru_maxpages'::text AS object,
       format('The background writer stopped early on %s cleaning rounds over %s days (%s per day, threshold %s per day) because it reached bgwriter_lru_maxpages = %s. It cleaned %s buffers in total against %s allocations. Every buffer it does not clean in advance is one a backend has to write itself (PG-WAL-004). bgwriter_delay = %s.',
              to_char(w.maxwritten_clean, 'FM999,999,999,999'), round(w.days, 1)::text,
              to_char(round(w.maxwritten_clean / w.days), 'FM999,999,999,999'),
              :'pg_wal_005_maxwritten_per_day'::text,
              (SELECT setting FROM pg_settings WHERE name = 'bgwriter_lru_maxpages'),
              to_char(w.buffers_clean, 'FM999,999,999,999'),
              to_char(w.buffers_alloc, 'FM999,999,999,999'),
              current_setting('bgwriter_delay')) AS details,
       json_build_object('maxwritten_clean', w.maxwritten_clean, 'buffers_clean', w.buffers_clean,
                         'buffers_alloc', w.buffers_alloc, 'window_days', round(w.days, 2),
                         'maxwritten_per_day', round(w.maxwritten_clean / w.days)::bigint,
                         'threshold_per_day', :'pg_wal_005_maxwritten_per_day'::bigint,
                         'bgwriter_lru_maxpages', (SELECT setting::int FROM pg_settings WHERE name = 'bgwriter_lru_maxpages'),
                         'bgwriter_delay', current_setting('bgwriter_delay'),
                         'stats_reset', w.stats_reset)::text AS evidence_json,
       'medium'::text AS confidence
FROM win w
WHERE NOT pg_is_in_recovery()
  AND w.maxwritten_clean / w.days >= :'pg_wal_005_maxwritten_per_day'::numeric;
\echo '@@END PG-WAL-005'
\else
\echo '@@SKIP PG-WAL-005 primary only'
\endif

-- ======== PG-WAL-008  P150  WAL compression off with a high full-page-image ratio ========
SELECT (current_setting('server_version_num')::int >= 140000 AND NOT pg_is_in_recovery()) AS gate_pg_wal_008 \gset
\if :gate_pg_wal_008
\echo '@@CHECK PG-WAL-008'
-- check: PG-WAL-008
-- title: WAL compression off with a high full-page-image ratio
-- priority: 150
-- scope: setting
-- cost: 0
-- min_version: 14
-- run_on: primary
-- thresholds: fpi_ratio
SELECT 'PG-WAL-008'::text        AS check_id,
       'setting'::text           AS scope,
       'wal_compression'::text   AS object,
       format('%s of the %s WAL records written since %s carried a full-page image (%s%%, threshold %s%%) while wal_compression = off. A full-page image is written on the first change to a page after each checkpoint, so a high ratio means either frequent checkpoints (PG-WAL-001) or scattered writes across a large working set. Total WAL since reset: %s. PostgreSQL 15 and newer offer lz4 and zstd, which cut WAL volume on this pattern for a small amount of CPU.',
              to_char(w.wal_fpi, 'FM999,999,999,999'),
              to_char(w.wal_records, 'FM999,999,999,999'),
              coalesce(w.stats_reset::text, 'the last statistics reset'),
              round(100.0 * w.wal_fpi / nullif(w.wal_records, 0), 1)::text,
              round(100 * :'pg_wal_008_fpi_ratio'::numeric)::text,
              pg_size_pretty(w.wal_bytes::bigint)) AS details,
       json_build_object('wal_fpi', w.wal_fpi, 'wal_records', w.wal_records,
                         'fpi_ratio', round(w.wal_fpi::numeric / nullif(w.wal_records, 0), 4),
                         'threshold_ratio', :'pg_wal_008_fpi_ratio'::numeric,
                         'wal_bytes', w.wal_bytes::bigint, 'stats_reset', w.stats_reset,
                         'wal_compression', current_setting('wal_compression'),
                         'full_page_writes', current_setting('full_page_writes'))::text AS evidence_json,
       'medium'::text AS confidence
FROM pg_stat_wal w
WHERE NOT pg_is_in_recovery()
  AND current_setting('wal_compression') = 'off'
  AND w.wal_records > 0
  AND w.wal_fpi::numeric / nullif(w.wal_records, 0) >= :'pg_wal_008_fpi_ratio'::numeric;
\echo '@@END PG-WAL-008'
\else
\echo '@@SKIP PG-WAL-008 needs PostgreSQL 14 or newer; primary only'
\endif

\echo '@@RUN-END fast cluster'
